// ==========================================
// ★ K 의 방 — B등급 직업 갈림길 · 은신
// ==========================================

// ── 암살자 (assassin) · 무력 ──
kJob('assassin', 'B', [
{ at:'B', t:'빗길 — 같은 박자',
  x:`비가 온다. 골목 바닥에 네온이 번진다. 빨강, 꺼짐, 빨강.<br><br>
    뒤에서 발소리가 따라온다. 일행 발소리에 딱 맞춰서. 일행이 서면 서고, 걸으면 걷는다.<br>
    암살자는 안다. 남의 걸음에 제 걸음을 묻는 건 배운 사람이 하는 일이다.<br><br>
    앞에 모퉁이가 하나 있다.`,
  o:[
    { l:'① 모퉁이를 돌자마자 벽에 붙어 멈춘다.', k:'hide', dc:20,
      ok:`돌자마자 처마 밑 벽에 등을 붙였다. 일행은 그대로 걸어가게 두었다.<br><br>발소리가 모퉁이를 돈다. 한 박자 늦게. 회색 외투가 바로 앞을 지나간다. 고개는 앞으로. 일행 등만 본다.<br>꺾이는 자리에서는 누구나 앞만 본다. 벽 쪽은 안 본다. 쫓는 쪽은 더 그렇다.<br><br>외투 뒤에 붙었다. 이제 이쪽이 박자를 정한다. 다음 모퉁이부터는 생각하기 전에 몸이 먼저 벽에 붙는다.`,
      ng:`벽에 붙었다. 발소리가 멈췄다. 모퉁이 바로 저쪽에서.<br><br>저쪽도 기다린다. 같은 걸 배운 사람이다.<br>빗물이 처마에서 목덜미로 떨어진다. 먼저 움직인 쪽은 이쪽이었다. 모퉁이에서 무언가 튀어나와 옆구리를 긋고 빗속으로 사라졌다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-24, spirit:-12 }, wake:1 },
    { l:'② 불 켜진 진열창 앞에 서서 지나가게 둔다.', k:'steady', dc:19,
      ok:`네온 아래 진열창 앞에 섰다. 유리 너머를 구경하는 척했다.<br><br>유리에 등 뒤가 비친다. 외투 하나가 지나간다. 모자도 우산도 없다. 머리카락이 말라 있다. 이 비에.<br>그것은 이쪽을 안 봤다. 안 본 척한 건지도 모른다.<br><br>그래도 지나갔다. 마른 머리카락은 외워 뒀다.`,
      ng:`진열창 앞에 섰다. 유리에 등 뒤가 비친다.<br><br>외투가 지나가지 않는다. 바로 등 뒤에 와서 같이 진열창을 본다. 유리 속에서 눈이 마주쳤다.<br>네온이 꺼졌다 켜졌을 때는 없었다. 유리에 손자국 다섯이 남았다. 안쪽에서 찍힌 것처럼.`,
      win:{ exp:15, dream:2 }, lose:{ mind:-14, spirit:-14 } }
  ] },

{ at:'B', t:'문 밑 — 젖은 봉투',
  x:`문 밑으로 봉투가 밀려 들어왔다. 모서리가 젖었다.<br><br>
    안에 사진 한 장과 숫자 하나. 사진은 일행 하나가 잠든 얼굴이다. 찍은 자리는 이쪽이 아까 앉아 있던 자리다.<br>
    숫자는 값이다. 밑에 한 줄. 『다음 정각까지.』<br><br>
    이런 종이는 이 일을 하는 사람에게만 온다. 누가 이쪽 업을 안다.`,
  o:[
    { l:'① 봉투를 태우고 문틈을 지켜본다.', k:'gaze', dc:20,
      ok:`세면대에서 봉투를 태웠다. 연기가 문틈으로 빠져나간다.<br><br>얼마 안 가 문틈 아래 그림자가 선다. 발 둘. 받을 사람이 태웠는지 확인하러 온 것이다.<br>구두 끝이 젖지 않았다. 밖에서 온 발이 아니다. 이 층에 있다.<br><br>그림자가 물러갔다. 의뢰인이 어디 있는지 알았다. 그러면 값은 이쪽이 매긴다.`,
      ng:`태우는데 사진만 안 탄다. 가장자리만 오그라든다.<br><br>문틈 아래 그림자가 서서 기다린다. 다 탈 때까지.<br>사진 속 얼굴이 불 속에서 눈을 뜬 것처럼 보였다. 손을 데었다. 그 밤 내내 눈을 감으면 그 얼굴이 떴다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-12, spirit:-16 } },
    { l:'② 사진을 일행에게 보여 준다.', k:'bond', dc:19,
      ok:`사진을 사진 속 사람에게 건넸다. 말은 짧게 했다. 누가 너를 샀다. 이쪽은 안 판다.<br><br>둘이 자리를 바꿔 잤다. 정각에 원래 자리로 무언가 다가왔다가, 거기 앉아 있는 이쪽을 보고 멈췄다.<br>멈춘 것은 그대로 물러갔다. 일을 맡긴 사람이 지키고 앉아 있으면 그 의뢰는 깨진다.`,
      ng:`사진을 본 일행이 이쪽을 본다. 오래.<br><br>왜 이게 너한테 왔느냐는 얼굴이다. 대답할 말이 없다. 이 업은 원래 이런 종이를 받는 업이다.<br>그 밤 아무도 이쪽 옆에서 자지 않았다. 정각에 누가 문을 두드렸는데, 아무도 이쪽을 깨우지 않았다.`,
      win:{ exp:16, dream:2, spirit:6 }, lose:{ mind:-16, spirit:-12 } },
    { l:'③ 사진 뒤에 의뢰인의 값을 적어 돌려보낸다.', k:'hide', dc:21,
      ok:`사진을 뒤집었다. 연필로 적었다. 젖지 않은 구두, 이 층, 왼쪽 끝 방. 그 밑에 숫자 하나. 이쪽이 매긴 값이다.<br><br>문틈으로 도로 밀었다. 한참 뒤 종이가 사라졌다. 그리고 복도 끝에서 문 하나가 급하게 잠기는 소리가 났다.<br>칼은 한 번도 안 뽑았다. 어디 있는지 안다고 알려 주기만 했다.<br><br>찌르기 전에 이미 끝나는 일이 있다. 손보다 먼저 아는 쪽이 이긴다. 일이 한 겹 넓어졌다.`,
      ng:`종이를 밀어 넣는 순간 저쪽에서 잡아당겼다. 기다리고 있었다.<br><br>얼마 뒤 봉투가 다시 들어왔다. 사진이 한 장 더. 문 앞에 쪼그려 앉아 연필로 뭔가 적는 사람. 이쪽 등이다.<br>값이 두 배가 됐다. 이름 칸에 이쪽 자리가 그려져 있었다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-12, spirit:-18 }, wake:1 }
  ] },

{ at:'B', t:'복도 — 초침에 맞춘 걸음',
  x:`벽시계 초침 소리가 복도를 채운다. 똑. 똑. 똑.<br><br>
    그 소리 밑에 발소리가 숨어 있다. 초침이 울릴 때만 딛는다. 한 번도 안 어긋난다.<br>
    큰 소리에 제 소리를 묻는 법. 이쪽이 쓰는 법이다. 저쪽도 쓴다.<br><br>
    같은 업이 이 복도 어딘가에 있다. 어디인지는 모른다. 저쪽도 이쪽이 어디인지는 모른다. 아직은.`,
  o:[
    { l:'① 무력을 실어 비수로 시계를 멈춘다.', k:'break', dc:21, cost:{ might:22 },
      ok:`소리 나는 쪽으로 비수를 던졌다. 손목만 써서, 세게.<br><br>유리가 깨지고 초침이 멎었다. 그 순간 발소리가 하나 더 났다. 멎은 초침에 맞춰 이미 내디딘 발이다.<br>왼쪽 세 번째 문 앞. 거기다.<br><br>복도가 조용해졌다. 저쪽은 이쪽이 어디 있는지 모르고, 이쪽은 안다. 그 차이만큼 물러나 다른 길로 갔다.`,
      ng:`비수가 시계에 박혔다. 초침이 멎었다.<br><br>발소리도 동시에 멎었다. 한 박자도 안 늦게. 저쪽은 시계가 아니라 이쪽을 듣고 있었다.<br>조용한 복도에서 먼저 숨을 쉰 건 이쪽이었다. 등 뒤에서 무언가 어깨를 찍고 지나갔다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, mind:-12 } },
    { l:'② 이쪽도 초침에 맞춰 걷는다.', k:'hide', dc:21,
      doom:{ title:'두 개의 초침', what:'복도에서 뒷덜미를 잡혔습니다', dc:17, sec:55,
        text:`초침에 맞춰 디뎠다. 똑, 한 걸음. 똑, 한 걸음.<br><br>다섯 걸음째에 초침 소리가 겹친다. 똑똑. 시계가 둘이다. 하나는 복도 끝, 하나는 바로 뒤.<br>어느 쪽에 맞춰야 할지 모르는 사이 발이 반 박자 어긋났다.<br><br>뒤에서 초침 소리가 멎는다. 그 자리에서 손이 나와 뒷덜미를 쥔다. 손목에 시계가 차여 있다.`,
        dieText:`복도에 초침 소리가 다시 차오른다. 똑. 똑.<br><br>그 밑에 발소리가 둘 숨어 있다. 둘 다 안 어긋난다.<br>하나는 조금 전까지 이쪽 걸음이었다.` },
      ok:`초침에 맞춰 디뎠다. 다섯 걸음째에 소리가 겹쳤다. 시계가 둘이다.<br><br>멈추지 않았다. 먼 쪽 시계에 맞췄다. 가까운 쪽은 저쪽이 찬 손목시계다.<br>저쪽은 제 시계에 맞춰 걷고, 이쪽은 벽시계에 맞춰 걸었다. 서로 다른 박자로 같은 복도를 지났다.<br><br>복도 끝에서 돌아봤다. 손목시계 소리가 아직 이쪽을 찾아 헤맨다.`,
      win:{ exp:23, dream:3 } }
  ] },

{ at:'B', t:'쉬는 자리 — 젖은 날',
  x:`잠깐 쉰다. 일행이 벽에 기대 눈을 붙인다.<br><br>
    날에 빗물이 맺혔다. 한 시간이면 녹이 핀다. 녹 핀 날은 걸린다. 걸리는 날은 두 번 찔러야 한다.<br>
    천으로 닦으면 쇠가 운다. 끽 하고.<br><br>
    창밖 네온이 방을 빨갛게 칠했다가 지운다.`,
  o:[
    { l:'① 네온이 꺼질 때만, 숨으로 말린다.', k:'hide', dc:19,
      ok:`날을 입 가까이 대고 숨을 길게 불었다. 물방울이 얇아진다. 소매 안쪽으로 한 번 쓸었다. 소리는 안 났다.<br><br>네온이 켜지면 멈추고, 꺼지면 했다. 빛이 날에 걸리지 않게.<br>다 말랐을 때 날은 방 안에서 제일 어두운 것이 돼 있었다.<br><br>손이 소리를 안 내는 쪽으로 자란다. 닦는 것 하나도 이제 일의 일부다.`,
      ng:`세 번째 쓸 때 소매 실밥이 날에 걸렸다. 끽.<br><br>복도에서 무언가 걸음을 멈춘다. 오래 선다.<br>일행 하나가 깼다. 아무도 다시 못 잤다. 날은 반만 말랐다.`,
      win:{ exp:16, dream:2, mind:8 }, lose:{ mind:-14, spirit:-10 }, wake:1 },
    { l:'② 나갈 길을 다시 센다.', k:'sense', dc:20,
      ok:`문, 창, 환기구. 셋이다.<br><br>환기구 나사 머리가 반짝인다. 새 나사다. 여기 다른 건 다 녹이 슬었는데.<br>누가 나가는 길을 미리 만들어 뒀다. 들어오는 길이기도 하다.<br><br>환기구 앞에 의자를 세워 두었다. 넘어지면 소리가 나게. 밤중에 한 번 났다. 다들 깨어 있었다.`,
      ng:`창은 페인트로 붙어 안 열린다. 문고리는 밖에서도 돈다.<br><br>세다 보니 셋 다 길이 아니다. 갇힌 방에 쉬러 들어온 것이다.<br>그걸 안 채로 쉬는 건 안 쉬는 것보다 나쁘다. 눈을 감을 때마다 문고리가 도는 것 같았다.`,
      win:{ exp:15, dream:2 }, lose:{ mind:-16, spirit:-12 } }
  ] },

{ at:'B', t:'열쇠 구멍 — 꺼진 빛',
  x:`문 열쇠 구멍으로 복도 불빛이 새어 든다. 바닥에 작은 빛점 하나.<br><br>
    빛점이 꺼졌다. 저쪽에서 무언가 구멍에 눈을 댔다.<br>
    열쇠 구멍은 좁다. 들여다보는 눈도 좁게 본다. 문 정면만, 가슴 높이만.<br><br>
    이쪽 등불이 켜져 있다. 그 정면에 일행이 앉아 있다.`,
  o:[
    { l:'① 등불을 끄고 구멍 옆 벽에 붙는다.', k:'hide', dc:20,
      ok:`손바닥으로 심지를 눌러 껐다. 방이 까매졌다. 구멍 너머 눈에는 이제 검은 것뿐이다.<br><br>경첩 쪽 벽에 붙었다. 눈이 닿지 않는 데다. 일행에게 손으로 바닥을 눌러 보였다. 엎드려.<br>빛점이 다시 켜졌다. 눈이 떨어졌다. 발소리가 멀어진다.<br><br>좁게 보는 눈 바로 옆에 서는 법. 몸이 그 자리를 하나 더 알았다.`,
      ng:`등불을 끄는 소리가 났다. 유리 뚜껑이 딸깍.<br><br>빛점이 다시 안 켜졌다. 눈이 안 떨어진다. 구멍으로 철사가 들어와 안쪽 손잡이를 더듬는다.<br>손으로 철사를 쥐었다. 철사가 손바닥을 가르며 빠져나갔다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-22, spirit:-14 } },
    { l:'② 구멍 너머로 먼저 찌른다.', k:'break', dc:22,
      ok:`가는 날을 구멍에 맞춰 단숨에 밀었다.<br><br>저쪽에서 젖은 숨이 끊기듯 새고 무언가 물러났다. 날끝에 맑은 것이 묻어 나왔다. 피가 아니다. 눈물 같은 것.<br>복도로 멀어지는 발소리가 한쪽만 무겁다.<br><br>이 문은 다시 안 들여다볼 것이다. 아픈 데는 기억하는 것들이다.`,
      ng:`날이 반쯤 들어가다 구멍에 끼었다.<br><br>저쪽에서 잡았다. 날을 잡고 비틀었다. 손가락 사이로 칼등이 돌아가며 살을 긁었다.<br>놓았다. 날은 저쪽으로 넘어갔다. 그 밤 문 너머에서 쇠 가는 소리가 들렸다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-12 } }
  ] },

{ at:'B', t:'길잡이 — 먼저 웃은 사람',
  x:`비옷 입은 남자가 앞을 막아선다. 나가는 길을 안다고 한다.<br><br>
    일행이 묻기도 전에 웃었다. 묻기 전에 웃는 사람은 대답을 미리 준비한 사람이다.<br>
    얼굴은 안 본다. 손을 본다. 남자 오른손이 한 번도 주머니에서 안 나온다.<br><br>
    <span style="color:#9fb4c8;">"따라오시오. 금방이오."</span>`,
  o:[
    { l:'① 앞세우고 오른손만 본다.', k:'gaze', dc:20,
      ok:`남자를 앞세웠다. 두 걸음 뒤에서 오른손만 봤다.<br><br>세 번째 모퉁이 앞에서 주머니 속 손가락이 두 번 움직였다. 안에서 무언가 딸깍 눌린다.<br>일행 어깨를 잡아 세웠다. 남자는 모르고 혼자 모퉁이를 돌았다.<br><br>모퉁이 너머에서 짧은 소리가 나고 조용해졌다. 신호를 받은 쪽은 신호가 누구 것인지 따지지 않는다. 남자 우산만 모퉁이 밖으로 굴러 나왔다.`,
      ng:`오른손만 봤다. 오른손은 끝까지 가만히 있었다.<br><br>왼손이 했다. 소매에서 무언가 떨어져 바닥에 깨졌다. 비린내가 퍼진다. 미끼 냄새다.<br>뒤에서 무언가 달려왔다. 일행을 감싸고 맞았다. 등을 길게 긁혔다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-24, spirit:-14 } },
    { l:'② 그의 등 뒤에 붙어 칼끝을 댄다.', k:'hide', dc:21,
      doom:{ title:'뒤에 선 자리', what:'길잡이의 일행에게 끌려갑니다', dc:17, sec:55,
        text:`남자 등 뒤에 바짝 붙었다. 칼끝을 갈비 사이에 댔다. 남자는 웃음을 거두지 않는다.<br><br><span style="color:#9fb4c8;">"늘 이러는 사람이 하나씩 있소. 그래서 나도 뒤에 하나를 세워 두지."</span><br>이쪽 손목 위로 다른 손이 덮인다. 뒤에서. 차고 젖었다.<br><br>칼끝이 남자 등에서 천천히 떨어진다. 이쪽 힘이 아니다.`,
        dieText:`비옷 입은 남자가 다른 일행 앞을 막아선다. 묻기도 전에 웃는다.<br><br>그 두 걸음 뒤에서 누가 따라 걷는다.<br>걸음걸이가 이쪽 것이다.` },
      ok:`칼끝을 대기 전에 이쪽 등부터 벽에 붙였다. 뒤에 서는 사람은 제 뒤를 먼저 본다.<br><br>골목 끝 처마 밑에 하나가 더 서 있다. 남자가 세워 둔 뒤.<br>칼끝을 남자 갈비에 대고 그대로 그쪽으로 밀었다. 남자가 제 뒤를 향해 걸어간다. 웃음이 없어졌다.<br><br>처마 밑의 것이 머뭇거리는 사이 일행을 반대쪽으로 보냈다. 남자는 놓아주었다. 두 번 찌를 일은 아니다.`,
      win:{ exp:23, dream:3 } }
  ] },

{ at:'B', t:'수색 — 마지막으로 보는 자리',
  x:`쫓는 것들이 방을 하나씩 뒤진다. 소리로 순서가 들린다.<br><br>
    문을 연다. 침대 밑. 옷장. 커튼 뒤. 그리고 문 바로 옆 구석. 언제나 맨 마지막이고, 언제나 대충이다.<br>
    방 셋을 뒤지는 동안 한 번도 안 바뀌었다.<br><br>
    다음은 이 방이다.`,
  o:[
    { l:'① 맨 마지막에 보는 구석에 선다.', k:'hide', dc:21,
      ok:`문 옆 구석에 섰다. 문이 열리면 문짝 뒤가 되는 자리다.<br><br>문이 열렸다. 침대 밑, 옷장, 커튼. 다 뒤졌다. 마지막으로 구석. 고개가 반만 돌아온다. 이미 나갈 생각을 하는 고개다.<br>문짝 틈으로 눈이 한 번 스쳤다. 문이 닫혔다.<br><br>몸 뒤에 숨는 게 아니라 남의 버릇 뒤에 숨는다. 버릇은 몸보다 넓다. 그걸 배웠다.`,
      ng:`문 옆 구석에 섰다. 문이 열렸다.<br><br>이번 것은 구석부터 봤다. 버릇이 다른 놈이었다. 쫓는 것도 하나가 아니다.<br>문짝째 밀려 벽에 짓눌렸다. 갈비뼈가 소리를 냈다. 겨우 빠져나와 창으로 굴렀다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, spirit:-14 }, wake:1 },
    { l:'② 무력을 실어 돌아서는 순간 친다.', k:'break', dc:20, cost:{ might:24 },
      ok:`커튼 뒤에서 기다렸다. 커튼은 이미 뒤진 데다.<br><br>마지막 구석을 보고 돌아서는 순간. 등이 문으로 향하는 순간. 한 번에 들어갔다.<br>소리 없이 무너졌다. 끌어다 침대 밑에 넣었다. 이미 뒤진 데다.<br><br>다만 쫓는 것들의 수가 하나 줄었다. 줄어든 수는 누가 세고 있을 것이다.`,
      ng:`돌아서는 순간을 노렸는데 그것은 뒷걸음으로 나갔다.<br><br>등을 한 번도 안 보였다. 커튼이 움직인 걸 봤다.<br>커튼째 끌려 나와 바닥을 굴렀다. 어깨가 빠졌다가 들어갔다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-30, mind:-12 } }
  ] },

{ at:'B', t:'끝 — 한 번',
  x:`나가는 문 앞에 그것이 서 있다.<br><br>
    처음부터 쫓아온 것이다. 지치지 않았다. 젖은 외투 밑으로 숨이 고르다.<br>
    문은 그것 등 뒤에 있다. 시간은 얼마 안 남았다.<br><br>
    한 번이면 된다. 두 번째부터는 싸움이고, 싸움은 이 일이 아니다.`,
  o:[
    { l:'① 어둠에서 한 번에 끝낸다.', k:'hide', dc:22,
      ok:`불빛 가장자리를 따라 돌았다. 숨은 그것의 숨에 실었다. 들이쉴 때 같이, 내쉴 때 같이.<br><br>그것의 귀 뒤에 섰을 때도 그것은 문을 보고 있었다. 이쪽이 문으로 올 줄 알고.<br>한 번 그었다. 외투가 먼저 무너지고 몸이 뒤따랐다.<br><br>손에 남은 것이 아주 적다. 힘도, 소리도, 떨림도. 적게 남을수록 깨끗한 일이다. 이 손이 이제 그걸 안다.`,
      ng:`귀 뒤에 섰다. 그었다. 반만 들어갔다.<br><br>두 번째가 됐다. 그것이 돌아선다. 외투 안에서 팔이 셋 나왔다.<br>문까지 밀려가 문에 등을 찍혔다. 일행이 끌어낼 때까지 숨이 안 쉬어졌다.`,
      win:{ exp:25, dream:4 }, lose:{ hp:-32, spirit:-14 }, wake:1 },
    { l:'② 무력을 다 쏟아 정면으로 친다.', k:'break', dc:21, cost:{ might:28 },
      ok:`숨지 않고 걸어 들어갔다. 그것이 이쪽을 본다. 보게 두었다.<br><br>정면에서 셋을 쳤다. 셋 다 같은 자리에. 셋째에 그것이 무릎을 꿇었다.<br>숨는 칼도 정면에서 쓸 줄 알아야 한다. 정면이 제일 빠를 때가 있다.`,
      ng:`첫째가 막혔다. 외투 안이 쇠처럼 딱딱하다.<br><br>둘째를 치기 전에 그것의 팔이 왔다. 벽까지 날아갔다.<br>일어나는 데 오래 걸렸다. 그것은 그동안 문 앞을 떠나지 않았다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-34, mind:-14 } },
    { l:'③ 일행을 하나씩 문으로 흘려보낸다.', k:'bond', dc:20,
      ok:`이쪽이 그것 앞으로 나갔다. 보이게. 그것의 눈이 이쪽에 붙는다.<br><br>그사이 일행이 벽을 따라 하나씩 문으로 빠졌다. 손짓 하나에 하나씩.<br>마지막으로 이쪽이 빠졌다. 그것은 끝까지 이쪽만 봤다. 미끼가 칼보다 나을 때도 있다.`,
      ng:`마지막 하나가 늦었다. 그것의 눈이 이쪽에서 떨어졌다.<br><br>그 사이에 끼어들었다. 어깨로 받았다. 뼈가 울렸다.<br>둘이 같이 문으로 굴러 나왔다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, spirit:-12 } }
  ] },

{ at:'B1', t:'3번 창고 — 같은 업의 손',
  x:`상자 더미 틈으로 청소부가 보인다. 회색 비옷, 고무장화, 양동이.<br><br>
    대걸레를 제 쪽으로 당기며 닦는다. 그래서 늘 앞을 본다. 등은 언제나 벽이다. 열린 데로 등을 안 돌린다.<br>
    낭비하는 동작이 하나도 없다. 암살자는 그런 손을 알아본다. 같은 일이다. 저쪽은 끝난 다음을 맡을 뿐.<br><br>
    대걸레가 지나간 바닥이 젖어 반짝인다. 창고 한가운데로 넓어진다.`,
  o:[
    { l:'① 그가 닦는 순서를 외운다.', k:'gaze', dc:20,
      ok:`오래 봤다. 벽을 따라 돈다. 한가운데는 가로지르지 않는다. 한 번 닦은 데는 다시 안 본다.<br><br>닦은 자리는 깨끗하니까. 깨끗한 자리에는 아무것도 없으니까.<br>젖은 한가운데를 걸어서 지났다. 그가 벽 쪽 구석을 닦는 동안. 발자국은 물이 메웠다.<br><br>남이 다 됐다고 여기는 자리가 제일 넓은 그늘이다. 눈이 그런 그늘을 하나 더 찾게 됐다.`,
      ng:`보는 사이 대걸레 소리가 멈췄다.<br><br>청소부가 고개를 든다. 이쪽 상자 쪽이다. 한참 본다. 그리고 다시 닦는다. 이쪽 상자 쪽으로.<br>틈에서 빠져나오다 못에 걸려 허벅지가 찢겼다. 피가 바닥에 떨어졌다. 그 자리를 그가 금방 닦을 것이다.`,
      win:{ exp:21, dream:3 }, lose:{ hp:-22, spirit:-16 }, wake:1 },
    { l:'② 등을 보일 때를 기다려 친다.', k:'hide', dc:22,
      doom:{ title:'등을 안 보이는 사람', what:'청소부에게 끌려갑니다', dc:17, sec:55,
        text:`상자 틈에서 기다렸다. 그가 돌아서기를.<br><br>그는 돌아서지 않는다. 대걸레를 당기고, 짜고, 다시 민다. 늘 이쪽을 보는 쪽으로.<br>발밑이 축축해진다. 대걸레 물이 상자 밑으로 스며든다. 그는 이쪽을 향해 닦아 오고 있었다. 처음부터.<br><br>틈 앞에 고무장화가 멎는다. 고무장갑이 상자를 하나 들어 옆으로 치운다.`,
        dieText:`3번 창고 바닥이 깨끗하다. 상자 더미도 하나 줄었다.<br><br>문 옆 고리에 비옷이 하나 더 걸렸다.<br>양동이 물이 조금 붉다.` },
      ok:`기다리다 알았다. 그는 등을 안 보인다. 평생 안 보였을 것이다.<br><br>그래서 등 대신 양동이를 봤다. 물이 다 흐려지면 그는 갈러 간다. 수도는 문 밖이다.<br>양동이를 들고 나가는 동안 그의 눈은 문을 본다. 그때 상자 틈에서 빠져나와 반대쪽으로 갔다.<br><br>찌를 데가 없는 사람은 비켜 가는 게 일이다. 그도 이쪽을 그렇게 볼 것이다.`,
      win:{ exp:23, dream:3 } }
  ] },

{ at:'B1', t:'냉동 창고 — 하얀 숨',
  x:`냉동 창고 안은 숨이 하얗다. 내쉴 때마다 입김이 피어올라 오래 남는다.<br><br>
    갈고리에 걸린 생선들 사이로 손전등 빛이 돈다. 빛 안에서 입김은 등불처럼 빛난다.<br>
    숨는 데 몸은 문제가 아니다. 숨이 문제다.<br><br>
    빛이 이쪽 줄로 온다.`,
  o:[
    { l:'① 옷깃 안으로 숨을 가둔다.', k:'hide', dc:20,
      ok:`옷깃을 입까지 올리고 그 안으로 숨을 쉬었다. 천천히, 아주 얇게. 입김이 옷 안에서 죽는다.<br><br>빛이 지나갈 때는 아예 안 쉬었다. 빛이 생선 비늘에 부딪혀 사방으로 튄다. 그 안에 이쪽 숨은 없다.<br>빛이 다음 줄로 갔다.<br><br>몸을 숨기던 일이 숨까지 숨기는 일이 됐다. 한 겹 더 안쪽이다.`,
      ng:`옷깃 안의 숨이 얼어 목에 성에가 맺혔다. 기침이 올라온다.<br><br>참았다. 참다가 코로 터졌다. 하얀 김 한 줄이 빛 속으로 올라간다.<br>빛이 멎었다. 갈고리 하나가 레일을 따라 이쪽으로 미끄러져 와 어깨를 찍었다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-24, spirit:-12 } },
    { l:'② 무력으로 소금물 통의 얼음을 깨 김을 피운다.', k:'break', dc:21, cost:{ might:22 },
      ok:`소금물 통 위에 얼음이 두껍게 앉았다. 주먹에 힘을 몰아 한 번 내리찍었다.<br><br>얼음이 깨지며 아래 물이 숨을 쉰다. 하얀 김이 바닥으로 깔려 창고 한쪽을 덮는다.<br>김 속에서는 누구 숨이 누구 것인지 모른다. 김을 따라 문까지 갔다. 가는 길에 소금 자루 터진 데서 한 덩이 챙겼다.`,
      ng:`얼음이 한 번에 안 깨졌다. 두 번째 내리친 소리가 창고 끝까지 갔다.<br><br>빛이 모두 이쪽으로 모인다. 레일이 움직이는 소리가 났다.<br>생선 사이로 기어서 빠져나왔다. 손등이 얼음에 쓸려 껍질이 벗겨졌다.`,
      win:{ exp:18, dream:2, item:'소금 덩이' }, lose:{ hp:-28, mind:-12 } }
  ] },

{ at:'B1', t:'경매장 — 종이 울리기 전',
  x:`경매장에 노란 비옷들이 둘러섰다. 고함으로 값을 부른다.<br><br>
    값이 정해지면 경매사가 종을 친다. 종이 울리면 모두 판을 본다. 그 한 번의 소리 동안 아무도 바닥을 안 본다.<br>
    종은 불규칙하다. 언제 울릴지 모른다.<br><br>
    판 위에 올라간 것이 무엇인지는 안 보기로 했다.`,
  o:[
    { l:'① 종이 울릴 때만 움직인다.', k:'hide', dc:21,
      ok:`종이 울렸다. 세 걸음. 고함이 다시 시작됐다. 멈췄다.<br><br>다시 종. 두 걸음. 노란 비옷 하나가 바로 옆에서 손을 들어 값을 부른다. 이쪽은 그 팔 밑에 있었다.<br>경매장 끝까지 종이 아홉 번 울렸다. 아홉 번 다 맞췄다.`,
      ng:`세 번째 종을 기다리는데 너무 오래 안 울린다.<br><br>값이 안 정해진다. 누가 값을 계속 올리고 있다. 이쪽이 판 위의 것을 쳐다볼 때까지.<br>종이 울렸다. 그때는 모두 이쪽을 보고 있었다. 갈고리 장대가 옆구리를 걸고 지나갔다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, spirit:-14 } },
    { l:'② 종 치는 손을 보고 먼저 안다.', k:'gaze', dc:20,
      ok:`종이 아니라 경매사의 손을 봤다.<br><br>값이 정해지기 직전 그는 늘 엄지로 망치 자루를 한 번 쓴다. 습관이다. 그다음에 친다.<br>엄지가 움직이면 이쪽 발이 먼저 나갔다. 종소리는 늘 이쪽 걸음 한가운데 떨어졌다.<br><br>소리를 기다리지 않고 소리 앞을 읽는다. 귀가 하던 일을 눈이 먼저 한다.`,
      ng:`손을 보는데 경매사가 이쪽을 봤다. 손을 보는 눈을 알아본 것이다.<br><br>그는 종을 안 친다. 망치를 내려놓고 다음 물건을 부르는 손짓을 한다. 손가락이 이쪽을 향했다.<br>노란 비옷들 사이를 헤치고 빠져나왔다. 누군가의 손톱이 목덜미를 긁었다.`,
      win:{ exp:21, dream:3 }, lose:{ mind:-14, spirit:-18 } },
    { l:'③ 얼음 더미 밑에서 생선을 하나 빼 온다.', k:'luck', dc:19,
      ok:`판 옆 얼음 더미에 생선이 박혀 있다. 팔고 남은 것이다.<br><br>종이 울릴 때 하나를 빼냈다. 강에서 잡은 것이다. 바다 것들 사이에 하나 섞여 있었다.<br>품에 넣으니 차다. 차가운 건 금방 잊는다.`,
      ng:`빼낸 생선 밑에 손이 있었다. 얼음 속에.<br><br>그 손이 생선을 놓지 않는다. 당겼다. 손톱 셋이 얼음째 따라 나왔다.<br>생선은 두고 왔다. 손바닥에 비늘 대신 손톱자국이 남았다.`,
      win:{ exp:14, item:'민물고기' }, lose:{ hp:-20, spirit:-12 } }
  ] },

{ at:'B1', t:'야적장 — 탐조등 탑',
  x:`컨테이너 야적장을 탐조등이 쓸고 지나간다. 한 바퀴에 마흔을 센다.<br><br>
    빛이 닿는 데는 빗줄기까지 하얗다. 빛 밖은 검다.<br>
    탑 위 조종석에 사람 머리 하나가 보인다. 빛을 돌리는 손이 있으면 끊을 수 있는 손도 있다.<br><br>
    탑 사다리는 빛이 제일 늦게 오는 쪽에 있다.`,
  o:[
    { l:'① 탑에 올라 빛을 돌리는 자를 끝낸다.', k:'hide', dc:22,
      doom:{ title:'빈 조종석', what:'탐조등 탑 위에 갇혔습니다', dc:17, sec:50,
        text:`빛이 지나간 직후 사다리를 탔다. 젖은 쇠가 손바닥에 붙는다. 마흔을 세며 올랐다.<br><br>조종석에 닿았다. 머리 하나. 모자를 씌운 대걸레 자루다. 빛은 혼자 돌고 있다.<br>사다리 아래에서 장화 소리가 올라온다. 한 칸씩, 서두르지 않고.<br><br>탑 위에서 내려갈 길은 사다리 하나다. 빛이 이쪽을 비추고 멎는다.`,
        dieText:`탐조등이 다시 돈다. 한 바퀴에 마흔.<br><br>조종석에 머리가 둘이 됐다.<br>하나는 모자를 썼고, 하나는 안 썼다.` },
      ok:`사다리를 반쯤 오르다 멈췄다. 조종석 머리가 빛이 돌아도 한 번도 안 움직인다.<br><br>사람 머리는 빛을 따라 조금이라도 돈다. 저건 안 돈다. 미끼다.<br>사다리 밑을 봤다. 컨테이너 그늘에 장화 한 켤레가 기다린다. 이쪽이 끝까지 오르기를.<br><br>반대편 쇠기둥을 타고 내려와 빛이 지난 자리로 빠졌다. 미끼를 알아보는 것도 먼저 보는 일이다.`,
      win:{ exp:24, dream:4 } },
    { l:'② 무력을 실어 빛과 빛 사이를 한달음에 뛴다.', k:'evade', dc:20, cost:{ might:22 },
      ok:`빛이 지나가자마자 다리에 힘을 몰았다. 마흔까지 셀 필요 없다. 스물에 다음 그늘에 닿았다.<br><br>컨테이너 셋을 그렇게 건넜다. 숨이 터지기 직전에 철문 그늘로 굴러 들어갔다.<br>빛이 등 뒤에서 늦게 왔다.`,
      ng:`스물다섯에 웅덩이를 밟았다. 미끄러졌다.<br><br>빛이 왔다. 하얀 원 안에 엎어진 채였다. 빛이 멈춘다. 돌지 않는다.<br>기어서 빠져나왔다. 무릎이 다 까졌다. 그 뒤로 빛은 한 바퀴에 서른만 셌다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-14 } }
  ] },

{ at:'B2', t:'정각 점검 — 딸깍 사이',
  x:`간호사가 병실을 돈다. 딸깍. 엄지가 계수기를 누른다.<br><br>
    누를 때마다 눈이 계수기로 내려간다. 숫자를 확인한다. 아주 잠깐.<br>
    딸깍 한 번에 눈을 한 번 감는 셈이다.<br><br>
    이쪽 침대는 문에서 제일 멀다. 문까지 침대가 여섯. 정각까지 한 바퀴뿐이다.`,
  o:[
    { l:'① 딸깍 사이로만 움직인다.', k:'hide', dc:21,
      ok:`딸깍. 침대 하나만큼. 눈이 올라온다. 굳는다.<br><br>딸깍. 또 하나만큼. 간호사가 세는 건 침대 위의 숫자다. 침대 사이 바닥은 안 센다.<br>여섯 번째 딸깍에 문 옆에 닿았다. 간호사가 마지막 침대를 세고 나간다. 이쪽 침대도 셌다. 이쪽은 거기 없는데.<br><br>남이 숫자를 보는 그 짧은 틈. 몸이 그 틈을 길게 쓰는 법을 알았다.`,
      ng:`네 번째 딸깍이 안 왔다. 간호사가 엄지를 멈췄다.<br><br>숫자가 맞지 않는다. 침대가 하나 비었다. 눈이 바닥으로 내려온다.<br>침대 밑으로 굴러 들어갔다. 흰 구두가 침대 둘레를 한참 돌았다. 숨을 너무 오래 참아 눈앞이 하얘졌다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-14 }, wake:1 },
    { l:'② 침대 밑에서 간호사 발만 본다.', k:'gaze', dc:20,
      ok:`침대 밑에 엎드려 발을 봤다. 흰 구두. 뒤축이 하나도 안 닳았다.<br><br>걷는 발은 뒤축부터 닳는다. 저 발은 걷지 않는다. 미끄러진다. 제 발소리가 없으니 남의 발소리를 잘 듣는다.<br>그래서 안 움직였다. 계수기가 이쪽 침대를 세고 지나갔다. 다음 정각까지 시간을 벌었다.`,
      ng:`발을 보는데 구두가 이쪽 침대 앞에 선다.<br><br>무릎을 굽히지 않고 얼굴만 내려온다. 침대 밑을 들여다본다. 마스크 위 눈이 웃는 모양이다.<br>딸깍. 세어졌다. 침대 밑에서. 그 숫자는 다음 정각에 다시 찾으러 온다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-14, spirit:-18 } }
  ] },

{ at:'B2', t:'처치실 — 메스 쟁반',
  x:`처치실 선반에 쟁반이 있다. 메스가 가지런하다. 가볍고, 잘 들고, 소매에 들어간다.<br><br>
    이 일에 이만한 날은 드물다.<br>
    쟁반 가장자리에 반창고가 붙어 있다. 볼펜으로 『12』.<br><br>
    여기는 무엇이든 센다. 사람도, 날도.`,
  o:[
    { l:'① 하나를 빼고 같은 무게로 채운다.', k:'luck', dc:20,
      ok:`숟가락 자루를 꺾어 거즈로 감쌌다. 손에 올려 보니 메스와 무게가 같다.<br><br>하나를 빼고 그것을 끼웠다. 줄이 가지런하다. 열둘.<br>나가는데 처치실 불이 한 번 깜빡였다. 누가 세러 들어온다. 문 뒤에서 들었다. 열둘. 발소리가 나갔다.`,
      ng:`무게는 맞췄다. 길이가 손톱 하나만큼 짧았다.<br><br>세러 온 손이 쟁반을 쓸어 본다. 열하나와 반.<br>불이 꺼졌다. 처치실 문이 바깥에서 잠겼다. 어둠 속에서 쟁반이 한 번 더 세어졌다. 그다음엔 이쪽 차례였다. 손목에 가는 상처가 여럿 남았다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-20, mind:-14 } },
    { l:'② 집지 않고 쟁반 자리만 외워 둔다.', k:'steady', dc:19,
      ok:`안 집었다. 남의 날은 남의 손버릇을 기억한다. 그리고 여기 날은 세어진다.<br><br>대신 자리를 외웠다. 처치실, 둘째 선반, 문에서 일곱 걸음.<br>나중에 쫓길 때 이 방으로 들어와 문을 잠그고, 그 자리에서 한 번 쓰고 도로 놓았다. 열둘. 아무도 몰랐다.`,
      ng:`집지 않고 돌아서는데 등 뒤에서 쟁반이 덜그럭했다.<br><br>돌아보니 열하나다. 이쪽이 들어오기 전부터 열하나였는지도 모른다.<br>상관없다. 여기선 마지막에 있던 사람이 가져간 것이다. 복도의 계수기 소리가 빨라졌다. 한참을 숨어 있었다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-16, spirit:-12 } }
  ] },

{ at:'B2', t:'비상계단 — 난간 틈의 눈',
  x:`비상계단 난간 틈으로 아래가 다 보인다. 층층이 일곱.<br><br>
    위도 다 보인다. 맨 위 계단참에서 흰 얼굴 하나가 내려다보고 있다.<br>
    계단은 눈을 위한 통로다. 가운데 틈으로 보면 모든 층이 보인다.<br><br>
    다만 계단참 바깥벽 쪽, 한 사람 폭만큼은 틈에서 안 보인다.`,
  o:[
    { l:'① 바깥벽에 붙어 계단참마다 멈춘다.', k:'hide', dc:20,
      ok:`바깥벽에 어깨를 붙이고 내려갔다. 계단을 돌 때만 틈에 드러난다. 그때는 숨을 멈추고 빨리.<br><br>계단참마다 섰다. 위의 얼굴이 틈을 따라 내려온다. 한 층 늦게.<br>세 층을 내려갔을 때 얼굴이 이쪽을 놓쳤다. 아래까지 내려다보다 고개를 갸웃했다.<br><br>남의 눈이 지나는 길을 먼저 그리고 그 밖을 걷는다. 이제 계단 하나가 지도처럼 보인다.`,
      ng:`세 번째 계단을 돌 때 빗물 묻은 신발이 미끄러졌다. 난간을 잡았다. 손이 틈 위로 나갔다.<br><br>위에서 얼굴이 멎는다. 손을 봤다.<br>흰 신발 소리가 계단을 뛰어 내려온다. 두 칸씩. 문 하나로 몸을 던져 넣었다. 문틀에 어깨를 찧었다.`,
      win:{ exp:21, dream:3 }, lose:{ hp:-24, spirit:-14 }, wake:1 },
    { l:'② 무력을 실어 위로 올라가 먼저 친다.', k:'break', dc:22, cost:{ might:26 },
      ok:`두 칸씩 올랐다. 바깥벽 쪽으로. 얼굴은 아래만 본다. 위로 오는 것은 셈에 안 넣었다.<br><br>맨 위 계단참. 흰 등. 한 번에 들어갔다. 소리 없이 주저앉았다.<br>흰 신발 한 짝이 벗겨져 틈으로 떨어졌다. 일곱 층을. 바닥에 닿는 소리가 한참 늦게 올라왔다.<br><br>그 소리를 아래층 누가 들었을지도 모른다. 서둘렀다.`,
      ng:`다섯 칸 남기고 얼굴이 이쪽으로 돌아왔다. 아래를 보던 얼굴이 그대로 위를 본다. 목이 너무 많이 돈다.<br><br>흰 손이 난간 너머로 뻗어 멱살을 잡았다. 틈 위로 몸이 반쯤 넘어갔다.<br>난간을 발로 걸어 겨우 빠졌다. 목에 손가락 자국이 남았다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-30, mind:-14 } }
  ] },

{ at:'B2', t:'세탁실 — 하얀 김',
  x:`세탁실은 김으로 하얗다. 드럼이 쿵, 쿵 돈다.<br><br>
    김 속에 사람 모양이 움직인다. 시트를 안고 오가는 직원들이다. 김 속에서는 다 모양만 있다.<br>
    모양만 있는 데서는 모양만 들키지 않으면 된다.<br><br>
    김은 한쪽으로 흐른다. 천장 환기구 쪽으로.`,
  o:[
    { l:'① 김이 흐르는 쪽으로 같이 흐른다.', k:'hide', dc:21,
      ok:`김이 흐르는 빠르기로 걸었다. 빠르지도 느리지도 않게.<br><br>직원 모양들은 김을 거슬러 걷는다. 그래서 그들 둘레만 김이 갈라진다. 이쪽 둘레는 안 갈라졌다.<br>김 속을 김처럼 지나갔다. 환기구 밑 문까지.`,
      ng:`드럼 하나가 갑자기 멎었다. 김이 흐르기를 멈춘다.<br><br>멈춘 김 속에서 이쪽만 움직이고 있었다. 모양 하나가 고개를 돌린다.<br>젖은 시트가 날아와 얼굴을 덮었다. 숨이 막힌 채 바닥을 굴러 겨우 벗겨 냈다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-22, mind:-14 } },
    { l:'② 드럼이 멈추는 박자를 센다.', k:'sense', dc:20,
      ok:`드럼마다 멈추는 때가 다르다. 그런데 셋이 한꺼번에 멎는 때가 있다. 이백까지 세면 온다.<br><br>그때 세탁실은 고요하다. 고요할 때는 모든 게 듣는다.<br>그 한 번만 서 있고 나머지 내내 걸었다. 반대편 문에 닿았다.`,
      ng:`세다가 숫자가 엉켰다. 김 속에서 누가 숫자를 소리 내어 센다. 이쪽 숫자보다 하나 앞서서.<br><br>셋이 멎었다. 이쪽은 걷던 중이었다. 발소리가 세탁실을 다 채웠다.<br>모양들이 일제히 돈다. 다리미대 밑으로 기어 빠졌다. 팔에 증기 화상이 길게 났다.`,
      win:{ exp:17, dream:2 }, lose:{ hp:-24, spirit:-12 } }
  ] },

{ at:'B3', t:'침대칸 — 이음매 박자',
  x:`침대칸 통로 양쪽에 커튼이 늘어섰다. 커튼마다 숨소리가 난다.<br><br>
    바퀴가 이음매를 넘는다. 덜컹, 덜컹.<br>
    한 커튼의 숨이 덜컹에 딱 맞는다. 들이쉬고 덜컹, 내쉬고 덜컹. 사람 숨은 그렇게 안 맞는다.<br><br>
    박자를 맞춘다는 건 박자로 듣는다는 뜻이다. 박자에서 벗어나는 것을.`,
  o:[
    { l:'① 덜컹에만 발을 디뎌 지난다.', k:'hide', dc:21,
      ok:`덜컹, 한 걸음. 덜컹, 한 걸음. 발이 소리 속에 들어갔다.<br><br>그 커튼 앞을 지날 때 숨이 한 번 멎었다. 무언가 귀를 기울인다. 덜컹. 이쪽 발은 그 소리 안에 있었다.<br>숨이 다시 박자로 돌아간다. 지나갔다.<br><br>남의 박자 안에 있는 동안은 그 박자의 일부다. 몸에 박자 하나가 더 들어왔다.`,
      ng:`덜컹이 한 번 비었다. 이음매가 아니라 다리 위였다. 이음매 없는 철교.<br><br>이쪽 발소리만 홀로 났다. 커튼 숨이 멎었다.<br>커튼 사이로 손이 나와 발목을 쥐었다. 걷어차고 빠지는 데 발목 살이 벗겨졌다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, spirit:-14 }, wake:1 },
    { l:'② 칼끝으로 그 커튼을 젖혀 먼저 본다.', k:'gaze', dc:21,
      doom:{ title:'위 칸', what:'위 칸 침대로 끌려 올라갑니다', dc:17, sec:50,
        text:`칼끝으로 커튼을 젖혔다. 아래 칸이 비어 있다. 시트가 반듯하다.<br><br>숨소리는 계속된다. 덜컹에 맞춰. 바로 위에서.<br>위 칸 커튼 틈으로 팔이 내려온다. 길다. 관절이 하나 더 있다.<br><br>팔이 겨드랑이 밑으로 들어와 들어 올린다. 위 칸 커튼이 열렸다가 닫힌다.`,
        dieText:`침대칸 커튼마다 숨소리가 난다.<br><br>위 칸 하나에서 숨이 둘 난다. 덜컹에 맞춰.<br>하나는 아직 서툴다.` },
      ok:`커튼을 젖히기 전에 눈을 위로 올렸다. 숨는 데를 열 때는 그 위부터 본다. 버릇이다.<br><br>위 칸 커튼 틈에 손가락 끝이 걸려 있다. 아래 칸은 미끼다. 숨소리는 위에서 났다.<br>커튼을 젖히지 않고 놓았다. 위 칸 고리를 칼끝으로 하나 끊어 커튼이 안쪽으로 감기게 했다. 손가락이 천에 엉켰다. 그 사이 지났다.`,
      win:{ exp:23, dream:3 } }
  ] },

{ at:'B3', t:'식당칸 — 칼 쥔 손',
  x:`식당칸에 손님들이 앉아 늦은 저녁을 먹는다. 포크와 나이프 소리.<br><br>
    얼굴을 바꾸는 손님이 이 중에 있을지도 모른다. 얼굴은 믿을 게 못 된다.<br>
    암살자는 얼굴 대신 손을 본다. 칼 쥔 손은 얼굴보다 거짓말을 못 한다.<br><br>
    창가 남자 하나가 나이프를 거꾸로 쥐었다. 날을 아래로, 엄지를 칼등에 대고.`,
  o:[
    { l:'① 나이프를 쥔 손을 끝까지 본다.', k:'gaze', dc:21,
      ok:`두 식탁 떨어져 창을 봤다. 창에 그 손이 비친다.<br><br>나이프는 사람을 다뤄 본 손으로 쥐었다. 그런데 포크는 처음 잡아 보는 손이다. 손가락이 하나씩 따로 논다.<br>몸에 익은 건 칼뿐이고, 밥 먹는 법은 아직 못 배웠다. 빌려 온 몸이다.<br><br>그가 일어설 때 이쪽은 이미 다른 칸에 있었다. 손을 읽는 눈이 얼굴을 읽는 눈보다 한 칸 빠르다. 이 눈은 이제 손부터 간다.`,
      ng:`손을 보는데 그 손이 멈췄다. 남자가 창에 비친 이쪽 눈을 본다.<br><br>남자가 나이프를 바꿔 쥔다. 천천히. 날은 아래로, 엄지는 칼등에. 이쪽이 쥐는 법 그대로다.<br>그리고 웃는다. 이쪽 얼굴로. 식당칸을 나오는데 무릎이 풀렸다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-18 }, wake:1 },
    { l:'② 빈 식탁에서 꿀단지와 나이프를 챙긴다.', k:'luck', dc:20,
      ok:`손님이 막 떠난 식탁이다. 접시에 손도 안 댔다.<br><br>작은 꿀단지 하나를 주머니에 넣었다. 나이프도. 무게가 좋다. 균형이 손잡이 쪽에 있다.<br>떠난 손님은 열차에서 내린 게 아니다. 서지 않는 열차다. 그래도 접시는 그대로 식어 있었다.`,
      ng:`식탁 밑에 누가 있었다. 손님이 떠난 게 아니라 내려간 것이다.<br><br>식탁보 아래에서 손이 손목을 잡는다. 꿀단지가 깨졌다.<br>뿌리치고 나왔다. 손등에 손톱자국이 넷. 다른 손님들은 고개도 안 들었다.`,
      win:{ exp:15, dream:1, item:'꿀 한 줌' }, lose:{ hp:-22, spirit:-12 } }
  ] },

{ at:'B3', t:'특실 복도 — 이번엔 뒤를 밟는다',
  x:`그것으로 보이는 등이 앞에 간다. 외투가 젖었다. 이 복도에선 다들 젖었다.<br><br>
    이번엔 이쪽이 쫓는다. 열차 복도는 좁고 길고 창이 많다.<br>
    쫓는 법은 하나다. 등을 보지 않는다. 창을 본다. 창에 비친 등을 본다.<br><br>
    곧 터널이다. 기적이 길게 운다.`,
  o:[
    { l:'① 창에 비친 등만 보며 따라간다.', k:'hide', dc:21,
      ok:`창에 비친 등만 봤다. 진짜 등은 한 번도 안 봤다. 보는 눈은 들킨다. 비친 걸 보는 눈은 안 들킨다.<br><br>그것이 두 번 돌아봤다. 두 번 다 이쪽은 창밖을 보는 손님이었다.<br>그것이 문 하나로 들어갔다. 번호가 없는 문이다. 기억했다.<br><br>쫓는 일과 숨는 일이 같은 일이다. 앞에 있어도 뒤에 있어도 이쪽은 안 보인다.`,
      ng:`창에 비친 등이 멈췄다. 진짜 등은 계속 걷는다.<br><br>창 속의 것이 돌아본다. 이쪽을. 진짜 쪽은 돌아보지 않았는데.<br>무엇을 쫓고 있었는지 모르게 됐다. 창에서 눈을 떼지 못하는 사이 진짜 쪽이 사라졌다. 등 뒤에서 이쪽 목소리가 이쪽을 불렀다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-18 } },
    { l:'② 터널 어둠 속에서 무력을 실어 친다.', k:'break', dc:22, cost:{ might:26 },
      ok:`터널이 덮쳤다. 창이 까매진다. 서른을 센다.<br><br>열에 다가갔다. 스물에 쳤다. 손에 외투가 걸렸다. 무언가 몸을 비틀어 빠져나간다.<br>빛이 돌아왔다. 바닥에 젖은 외투 하나. 안이 비었다. 외투 깃에 얼굴 하나가 걸려 있다. 쓰다 버린 얼굴이다.<br><br>그것은 다쳤다. 다친 것은 다음 얼굴을 고를 때 서두른다.`,
      ng:`스물에 쳤다. 벽이었다. 그것은 거기 없었다.<br><br>어둠 속에서 귓가에 숨이 닿는다. 이쪽 목소리로 낮게 웃는다.<br>빛이 돌아왔을 때 이쪽 외투 소매가 길게 갈라져 있었다. 팔도.`,
      win:{ exp:21, dream:4 }, lose:{ hp:-28, spirit:-16 } }
  ] },

{ at:'B3', t:'탄수차 — 화실 문',
  x:`탄수차 위는 석탄 더미다. 비가 석탄을 검게 적신다.<br><br>
    앞에서 화부가 삽질을 한다. 화실 문이 열릴 때마다 붉은빛이 쏟아져 석탄 더미를 다 비춘다. 닫히면 검다.<br>
    문이 열리는 박자는 삽질 박자다. 퍼서, 열고, 넣고, 닫고.<br><br>
    기관실은 화부 등 뒤다.`,
  o:[
    { l:'① 화실 문이 닫혀 있을 때만 기어간다.', k:'hide', dc:21,
      ok:`문이 닫혔다. 기었다. 석탄이 손바닥 밑에서 미끄러진다. 소리는 빗소리가 먹었다.<br><br>문이 열린다. 엎드렸다. 붉은빛이 등을 지나간다. 등도 석탄처럼 검다.<br>네 번 열리고 네 번 닫혔다. 다섯 번째 닫힐 때 화부 등 뒤에 있었다. 그는 끝까지 불만 봤다.`,
      ng:`세 번째 닫히는 박자가 늦었다. 삽에 석탄이 덜 퍼졌다.<br><br>기던 몸이 붉은빛 한가운데서 드러났다. 화부가 돌아본다. 삽을 든 채.<br>삽 등이 어깨를 찍었다. 석탄 더미를 굴러 탄수차 가장자리에 매달렸다.`,
      win:{ exp:21, dream:3 }, lose:{ hp:-30, mind:-12 } },
    { l:'② 삽질 박자에 맞춰 한 번에 건넌다.', k:'evade', dc:20,
      ok:`세 번 지켜봤다. 퍼서 넣는 데 넷, 닫는 데 하나.<br><br>닫히는 소리와 함께 뛰었다. 넷을 세는 동안 석탄 더미를 건넜다. 다섯에 화부 등 뒤 그늘에 내렸다.<br>문이 다시 열렸다. 빛은 빈 석탄만 비췄다.`,
      ng:`셋에서 석탄이 무너졌다. 발이 빠졌다.<br><br>넷. 다섯. 문이 열렸다. 빛 속에서 허우적거렸다.<br>화부가 석탄 한 삽을 이쪽으로 퍼부었다. 뜨거운 재가 눈에 들어갔다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-12 } },
    { l:'③ 젖은 석탄 사이에서 기름종이 꾸러미를 찾는다.', k:'luck', dc:19,
      ok:`석탄 더미 가장자리에 기름종이 꾸러미가 끼어 있다. 화부의 밤참이다.<br><br>말린 고기다. 비에 반쯤 젖었다. 그래도 고기다.<br>화부는 돌아보지 않았다. 밤참이 없어진 걸 언제 알지는 모른다.`,
      ng:`꾸러미를 당기는데 석탄이 같이 쏟아졌다. 소리가 컸다.<br><br>삽질이 멈췄다. 이쪽은 석탄에 반쯤 묻혀 있었다.<br>빛이 지나갈 때까지 숨을 참았다. 석탄 가루가 목에 들어가 한참 기침이 났다.`,
      win:{ exp:14, item:'말린 고기' }, lose:{ hp:-20, mind:-12 } }
  ] }
]);

// ── 자객 (killer) · 내공 ──
kJob('killer', 'B', [
{ at:'B', t:'빗속 — 살기를 맡는 것',
  x:`빗속 저편에 무언가 서 있다. 고개를 천천히 돌린다. 사람마다 한 번씩.<br><br>
    보는 게 아니다. 맡는다. 자객은 그런 것을 안다. 냄새가 아니라 살기를 맡는 것.<br>
    일행에게서는 겁이 난다. 이쪽에게서는 다른 것이 난다. 이 일을 오래 한 몸에서 나는 것.<br><br>
    고개가 이쪽으로 돈다. 다섯을 세면 닿는다.`,
  o:[
    { l:'① 살기를 거두지 않고 다른 데로 던진다.', k:'hide', dc:21,
      ok:`거두기엔 늦었다. 그래서 던졌다.<br><br>골목 끝 하수구 쇠창살을 봤다. 거기 죽일 것이 있다고 마음을 한 번 세게 먹었다. 손은 안 움직이고.<br>빗속의 고개가 이쪽을 지나 하수구로 꺾였다. 그쪽으로 걸어간다. 쇠창살 앞에 쭈그려 앉아 오래 맡는다.<br><br>살기는 감추는 것이라고만 배웠다. 던질 수도 있다. 돌멩이처럼. 몸이 그걸 처음 해냈다.`,
      ng:`던졌다. 하수구 쪽으로.<br><br>고개가 하수구로 꺾였다가 돌아왔다. 던진 건 가벼웠고 남은 건 무거웠다. 무거운 쪽이 이쪽이다.<br>빗속에서 그것이 걸어온다. 일행을 밀어내고 맞섰다. 팔뚝이 젖은 이빨에 찢겼다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, spirit:-14 }, wake:1 },
    { l:'② 내공으로 맥을 늦추고 살기를 가라앉힌다.', k:'steady', dc:20, cost:{ qi:22 },
      ok:`단전으로 기운을 내려 심장을 눌렀다. 맥이 느려진다. 살기도 맥을 타고 돈다. 맥이 느리면 살기도 느리다.<br><br>고개가 이쪽에서 멈췄다. 맡는다. 오래.<br>잔잔한 물 같은 것만 맡았다. 고개가 다음 사람으로 넘어갔다.`,
      ng:`맥을 누르다 기운이 엇나갔다. 가슴이 막힌다.<br><br>막힌 숨이 터지면서 살기가 한 번에 솟았다. 고개가 딱 멈췄다.<br>빗속에서 뛰어오는 소리. 일행과 흩어져 달렸다. 무릎이 돌바닥에 깨졌다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, mind:-14 } }
  ] },

{ at:'B', t:'빗물 — 흘러가는 피',
  x:`옆구리 상처가 다시 터졌다. 피가 빗물에 섞여 발밑으로 흐른다.<br><br>
    빗물은 골목 아래로 간다. 아래에는 쫓는 것들이 있다.<br>
    물은 냄새를 실어 나른다. 피 냄새가 저쪽에 먼저 닿는다.<br><br>
    피를 남기지 않는 게 이 일이다. 제 피도.`,
  o:[
    { l:'① 내공으로 혈을 눌러 피를 멈춘다.', k:'heal', dc:20, cost:{ qi:20 },
      ok:`상처 위 두 군데를 손가락으로 짚었다. 기운을 밀어 넣었다.<br><br>피가 가늘어지다 멎었다. 빗물이 맑아진다.<br>아래 골목에서 무언가 킁킁대다 멈췄다. 냄새가 끊긴 것이다. 그것은 냄새가 끊긴 자리에서 오래 서성였다.`,
      ng:`짚은 자리가 반 치 어긋났다. 피가 멎지 않는다. 기운만 새어 나갔다.<br><br>손가락 사이로 피가 계속 빗물에 섞인다.<br>아래에서 발소리가 올라온다. 하나가 아니다. 벽을 타고 지붕으로 피했다. 상처가 더 벌어졌다.`,
      win:{ exp:16, dream:2, hp:8 }, lose:{ hp:-28, mind:-12 } },
    { l:'② 피 묻힌 천을 반대쪽 물길에 띄운다.', k:'hide', dc:21,
      ok:`소매를 찢어 피를 듬뿍 적셨다. 길 건너 다른 도랑에 띄웠다. 그 물은 반대쪽으로 흐른다.<br><br>상처는 손바닥으로 누르고 처마 밑 마른 데로만 걸었다. 빗물에 피가 안 닿게.<br>아래 골목의 것들이 방향을 틀었다. 천 조각을 따라 반대로 간다.<br><br>남기지 않는 것만이 아니다. 남길 데를 고르는 것도 일이다. 피 한 줌이 길을 하나 만들었다.`,
      ng:`천을 띄웠다. 도랑이 얼마 안 가 이쪽 골목 물과 합쳐졌다.<br><br>냄새가 둘로 갈라졌다가 다시 하나가 됐다. 더 진하게.<br>골목 끝에서 그것들이 동시에 고개를 들었다. 쫓겼다. 등을 할퀴는 손이 셋이었다.`,
      win:{ exp:21, dream:3 }, lose:{ hp:-26, spirit:-14 }, wake:1 }
  ] },

{ at:'B', t:'문설주 — 끝난 자리 표식',
  x:`쉬려던 방 문설주에 칼자국이 있다. 가로 셋, 세로 하나.<br><br>
    자객은 이 표식을 안다. 같은 문하에서 쓰던 것이다. 일을 끝낸 자리에 남긴다. 다음에 온 사람이 헛걸음하지 않게.<br>
    칼자국이 아직 하얗다. 오늘 밤에 그었다.<br><br>
    이 방은 아직 아무 일도 없었다. 아직은.`,
  o:[
    { l:'① 표식 밑에 「아직」 표식을 덧긋는다.', k:'hide', dc:21,
      ok:`세로 획 밑에 짧은 점 둘을 찍었다. 같은 문하에서 「아직 안 끝났다, 손대지 마라」는 뜻이다.<br><br>한밤중에 복도로 발소리가 왔다. 문설주 앞에 멈췄다. 손가락이 칼자국을 쓰다듬는 소리.<br>발소리가 물러갔다. 표식을 읽을 줄 아는 쪽은 표식을 지킨다. 그게 문하의 규칙이다.<br><br>남의 표식에 한 획을 더해 남의 칼을 멈췄다. 칼을 안 쓰고 칼을 막는 법이다.`,
      ng:`점 둘을 찍는데 칼끝이 미끄러졌다. 점이 길게 그어졌다.<br><br>그것은 「대신 끝낸다」는 표식이 됐다.<br>한밤중에 발소리가 문 앞에 멈췄다가 문고리를 돌렸다. 일을 넘겨받으러 온 것이다. 밤새 문을 붙들고 버텼다. 문틈으로 들어온 칼끝에 손등이 갈렸다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-24, spirit:-14 } },
    { l:'② 칼자국의 깊이로 그은 손을 읽는다.', k:'gaze', dc:20,
      ok:`가로 셋이 다 왼쪽이 깊다. 왼손잡이다. 세로 획은 위에서 아래로 한 번에.<br><br>서두르지 않는 손이다. 문하에서 왼손잡이는 하나였다. 이쪽보다 먼저 들어온 사람.<br>그 사람은 늘 창으로 들어왔다. 창 앞에 탁자를 대고 그 위에 물잔을 올렸다.<br><br>새벽에 물잔이 떨어지는 소리가 났다. 창은 다시 닫혔다.`,
      ng:`칼자국을 보다가 깊이를 알았다. 문설주 너머까지 그어졌다. 벽 속까지.<br><br>사람 손으로 낼 깊이가 아니다. 문하의 표식을 흉내 낸 무언가다.<br>등골이 식었다. 그 밤 내내 문설주에서 무언가 손톱으로 획을 덧그리는 소리가 났다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-16 } }
  ] },

{ at:'B', t:'쉬는 자리 — 정각 전 한 바퀴',
  x:`벽시계가 정각 이십 분 전을 가리킨다. 정각이면 무언가 돈다. 여기선 늘 그랬다.<br><br>
    흐트러진 기운을 돌려야 한다. 한 바퀴 다 도는 데 이십 분이 조금 안 걸린다.<br>
    운기 중에 끊기면 기운이 거꾸로 돈다. 거꾸로 돈 기운은 몸 안을 칼처럼 긋는다.<br><br>
    가부좌를 튼다. 초침 소리를 등 뒤에 둔다.`,
  o:[
    { l:'① 초침에 숨을 맞춰 한 바퀴를 끝낸다.', k:'steady', dc:20,
      ok:`들숨 넷에 초침 넷. 날숨 넷에 초침 넷. 숨이 시계가 됐다.<br><br>기운이 단전에서 등을 타고 정수리를 돌아 다시 내려온다. 막힌 데마다 초침이 한 번씩 두드린다.<br>정각 일 분 전에 눈을 떴다. 손끝까지 따뜻하다.<br><br>쫓기면서도 도는 기운. 시간을 등에 지고도 안 흩어지는 숨. 몸 안이 한 단 넓어졌다.`,
      ng:`열다섯 분째에 복도에서 발소리가 났다. 정각이 아닌데.<br><br>귀가 그쪽으로 갔다. 기운이 따라갔다. 거꾸로.<br>가슴 안에서 무언가 찢어지는 느낌이 났다. 입 안에 쇠맛이 고였다. 발소리는 문 앞을 그냥 지나갔다.`,
      win:{ exp:18, dream:2, qi:12, mind:6 }, lose:{ hp:-24, mind:-14 }, wake:1 },
    { l:'② 운기를 미루고 문 앞을 지킨다.', k:'sense', dc:19,
      ok:`문에 등을 대고 앉았다. 기운은 흐트러진 채 두었다.<br><br>정각에 복도로 무언가 돈다. 문마다 한 번씩 멈춘다. 이쪽 문 앞에서도. 등 너머로 숨소리가 하나 지나간다.<br>문은 안 열렸다. 지친 몸으로 버틴 이십 분이 길었다.`,
      ng:`문을 지키는 사이 졸음이 왔다. 흐트러진 기운이 몸을 무겁게 누른다.<br><br>눈을 떴을 때 문틈으로 손가락 하나가 들어와 있었다. 이쪽 뒤통수를 만지고 있다.<br>몸을 날려 피했다. 문을 다시 잠그는 손이 떨렸다.`,
      win:{ exp:15, dream:2 }, lose:{ mind:-16, spirit:-12 } },
    { l:'③ 일행 하나의 등에 손을 대고 같이 돌린다.', k:'bond', dc:21,
      ok:`제일 지친 일행 등에 손바닥을 댔다. 이쪽 기운을 그쪽으로 흘려 한 바퀴 같이 돌았다.<br><br>둘이 도니 더디다. 그래도 둘이 같이 따뜻해진다.<br>정각에 둘 다 눈을 떴다. 일행이 처음으로 제대로 숨을 쉰다.`,
      ng:`그쪽 기운이 너무 흐트러져 있었다. 이쪽 기운이 휩쓸렸다.<br><br>둘이 같이 거꾸로 돌았다. 일행이 먼저 쓰러졌다. 이쪽은 코피를 흘리며 손을 뗐다.<br>정각이 됐을 때 둘 다 아무것도 할 수 없었다.`,
      win:{ exp:16, dream:2, hp:10 }, lose:{ hp:-22, mind:-12 } }
  ] },

{ at:'B', t:'복도 — 등 셋, 비수 셋',
  x:`긴 복도에 등이 셋 켜져 있다. 셋 다 하얀 빛이다. 아래가 낮처럼 밝다.<br><br>
    복도 끝에 의자가 하나 있고 무언가 앉아 있다. 밝은 데로 오는 것만 본다. 어두운 데는 안 본다.<br>
    소매에 비수가 셋 남았다.<br><br>
    던지면 한 번이다. 셋이면 세 번. 넷째는 없다.`,
  o:[
    { l:'① 비수 셋으로 등 셋을 끈다.', k:'break', dc:21,
      ok:`첫째는 손목만. 퍽. 복도 끝이 어두워진다. 의자의 것이 고개를 든다.<br><br>둘째. 퍽. 고개가 둘째 쪽으로 돈다. 셋째는 돌기 전에. 퍽.<br>복도가 까매졌다. 의자의 것이 어둠을 본다. 어두운 데는 안 보는 것이다. 볼 데가 없어졌다.<br><br>세 번 던져 셋이 꺼졌다. 손이 세 번을 한 번처럼 썼다. 그 사이 숨을 한 번도 안 쉬었다.`,
      ng:`둘째가 등을 스치고 벽에 박혔다. 등이 흔들리기만 한다.<br><br>흔들리는 빛 속에 이쪽 그림자가 복도 끝까지 늘었다 줄었다 한다.<br>의자가 비었다. 셋째를 던지기 전에 무언가 그림자를 따라 달려왔다. 팔이 길게 찢겼다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-28, spirit:-12 }, wake:1 },
    { l:'② 내공을 실어 빛 아래를 바람처럼 지난다.', k:'evade', dc:20, cost:{ qi:24 },
      ok:`기운을 발끝에 모았다. 몸이 가벼워진다.<br><br>빛 아래를 지날 때 바닥을 거의 안 디뎠다. 의자의 것이 고개를 들었을 때는 둘째 등 아래였다. 다시 들었을 때는 이미 셋째 너머 어둠이었다.<br>밝은 데를 무언가 지나갔다는 것만 알았을 것이다.`,
      ng:`둘째 등 아래서 기운이 끊겼다. 발이 바닥에 쿵 떨어졌다.<br><br>밝은 데 서 있는 이쪽을 의자의 것이 정면으로 봤다.<br>뛰었다. 복도 끝 문에 몸을 던졌다. 문에 끼인 발목이 부어올랐다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-12 } }
  ] },

{ at:'B', t:'통로 — 같은 걸음',
  x:`통로 저편에서 발소리가 온다. 가볍게 셋, 무겁게 하나.<br><br>
    자객의 걸음이다. 같은 문하에서 배운 걸음. 셋으로 소리를 흐리고 하나로 땅을 잡는다.<br>
    같은 걸음을 하는 사람은 같은 것을 듣는다. 이쪽 걸음도 저쪽에 들렸을 것이다.<br><br>
    둘 다 멈췄다. 통로가 조용하다.`,
  o:[
    { l:'① 숨까지 멈추고 굳는다.', k:'hide', dc:21,
      doom:{ title:'같은 문하', what:'같은 걸음의 것에게 붙들렸습니다', dc:17, sec:55,
        text:`굳었다. 숨도 맥도 눌렀다. 문하에서 배운 대로. 걸음이 들키면 굳는다.<br><br>저쪽도 그걸 배웠다. 굳은 다음에 무엇을 하는지도.<br>통로 바닥의 빗물이 한 군데만 흐르지 않는다. 이쪽이 선 자리다. 굳은 것은 물을 막는다.<br><br>가볍게 셋, 무겁게 하나. 걸음이 다시 온다. 이번엔 이쪽 앞에서 멎는다. 손이 목덜미의 혈을 짚는다.`,
        dieText:`통로 저편에서 발소리가 온다. 가볍게 셋, 무겁게 하나.<br><br>둘이다. 걸음이 꼭 맞는다.<br>하나는 아직 조금 무겁다.` },
      ok:`굳기 전에 발밑을 봤다. 빗물이 흐르고 있다. 굳으면 물이 막힌다. 막힌 물은 말을 한다.<br><br>굳는 대신 물을 따라 아주 천천히 흘렀다. 물보다 빠르지 않게.<br>저쪽은 굳었다. 문하의 가르침대로. 그 앞으로 물이 고이는 게 보였다. 저쪽이 어디 섰는지 이쪽이 먼저 알았다.<br><br>가르침을 다 지킨 쪽보다 하나를 버린 쪽이 살았다. 그 자리를 비켜 다른 통로로 갔다.`,
      win:{ exp:24, dream:4 } },
    { l:'② 내공을 끌어올려 한 수에 끝낸다.', k:'break', dc:22, cost:{ qi:26 },
      ok:`멈춘 쪽에서 먼저 움직이는 쪽이 진다. 그래서 움직이지 않고 기운만 모았다.<br><br>저쪽이 참지 못하고 한 걸음 왔다. 가볍게. 그 소리 위로 몸을 실었다.<br>한 수. 손바닥이 가슴에 닿았다. 안에서 기운이 터졌다.<br><br>쓰러진 얼굴을 봤다. 모르는 얼굴이다. 걸음만 같았다. 걸음을 배운 것이다. 누구에게서인지는 모른다.`,
      ng:`저쪽이 먼저 왔다. 한 박자 먼저.<br><br>손이 엇갈렸다. 이쪽 장은 어깨를 스쳤고 저쪽 손끝은 갈비 밑 혈을 짚었다.<br>숨이 반으로 줄었다. 통로 벽에 기대 한참을 못 일어났다. 저쪽은 그사이 사라졌다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-32, mind:-14 } }
  ] },

{ at:'B', t:'갈림길 — 옛 이름',
  x:`갈림길 왼쪽에서 누가 부른다. 이름이다.<br><br>
    이 일을 시작하기 전의 이름. 아무도 모르는 이름. 자객이 제일 먼저 버린 것.<br>
    부르는 목소리가 낯익다. 이 일을 처음 가르쳐 준 목소리다.<br><br>
    오른쪽은 조용하다.`,
  o:[
    { l:'① 대답 대신 목소리의 숨을 듣는다.', k:'sense', dc:20,
      ok:`대답하지 않고 들었다. 이름을 부르고, 쉬고, 다시 부른다.<br><br>쉴 때 숨을 안 쉰다. 부르는 데 숨이 안 든다. 사람 목소리가 아니다.<br>그 사람은 이름을 부를 때 늘 끝을 내렸다. 이건 끝을 올린다. 배운 소리다.<br><br>오른쪽으로 갔다. 등 뒤에서 이름이 오래 따라왔다.`,
      ng:`듣다가 그 목소리가 다른 것을 말했다. 이쪽이 처음 일을 망친 밤 이야기.<br><br>아무도 모르는 밤이다. 가르쳐 준 사람만 안다.<br>다리가 왼쪽으로 반걸음 나갔다. 일행이 팔을 붙들었다. 그 손을 뿌리치려다 일행 얼굴을 쳤다. 그 뒤로 오래 둘 다 말이 없었다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-18 } },
    { l:'② 그 이름을 마음에서 한 번 더 버린다.', k:'hide', dc:21,
      ok:`이름을 들었다. 들은 채로 놓았다. 버린 걸 다시 주워서, 다시 버렸다.<br><br>이번엔 이름에 붙은 것들까지. 그 목소리, 가르침, 처음 쥔 칼의 무게.<br>목소리가 이름을 부른다. 부르는 데가 비었다. 대답할 사람이 거기 없다.<br><br>오른쪽으로 갔다. 이름이 따라오지 못했다. 버리는 것도 두 번째가 더 깊다. 비운 자리가 넓어졌다.`,
      ng:`버리려는데 이름이 안 떨어진다. 그 목소리에 묶여 있다.<br><br>목소리가 이름을 부를 때마다 손이 저절로 움찔한다. 칼 쥐는 손이.<br>오른쪽으로 갔지만 이름이 등에 붙어 왔다. 그 밤 잠꼬대로 대답을 했다. 일행이 들었다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-14, spirit:-20 }, wake:1 }
  ] },

{ at:'B', t:'끝 — 한 수의 무게',
  x:`나가는 길 앞에 그것이 앉아 있다. 쫓아오던 것들 중 제일 늦게 움직인 것. 제일 오래 남은 것.<br><br>
    그것도 살기를 맡는다. 다른 것들보다 깊이.<br>
    아는 건 하나다. 한 수에 끝내야 한다. 두 수째부터는 싸움이다.<br><br>
    빗물이 그것의 어깨에서 떨어진다. 똑. 똑. 그것이 숨 쉬는 박자다.`,
  o:[
    { l:'① 살기 없이 다가가 단번에 거둔다.', k:'hide', dc:22,
      ok:`걸음마다 마음을 하나씩 내려놨다. 겁, 화, 서두름. 마지막에 이기려는 마음.<br><br>그것 앞에 섰을 때 이쪽에는 아무것도 없었다. 그것이 맡을 것이 없었다.<br>한 수. 빗물이 떨어지는 박자 사이에.<br><br>그것이 앉은 채로 기울었다. 손에 남은 것이 깃털만큼 가볍다. 이 무게로도 끝난다는 걸 손이 알았다.`,
      ng:`마지막 하나가 안 내려놔졌다. 이기려는 마음이었다.<br><br>그것의 콧등이 떨렸다. 맡았다. 일어선다.<br>한 수가 빗나갔다. 두 수째. 세 수째. 싸움이 됐다. 끝났을 때 이쪽도 바닥에 있었다.`,
      win:{ exp:25, dream:4 }, lose:{ hp:-34, spirit:-14 }, wake:1 },
    { l:'② 단전을 비워 내공을 다 실은 장을 친다.', k:'break', dc:21, cost:{ qi:28 },
      ok:`기운을 단전에서 손바닥까지 한 줄로 올렸다. 남김없이.<br><br>장이 그것의 가슴에 닿았다. 소리가 안 났다. 안에서 무언가 무너지는 느낌만 손바닥에 왔다.<br>그것이 천천히 앞으로 엎어졌다. 다리가 후들거렸다. 비운 단전이 시렸다.`,
      ng:`기운이 팔꿈치에서 멈췄다. 반만 실렸다.<br><br>반만 실린 장은 그것을 깨우기만 했다.<br>그것의 팔이 휘둘렀다. 벽까지 날아갔다. 빈 단전으로는 일어나는 데도 한참 걸렸다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-32, mind:-14 } },
    { l:'③ 일행을 하나씩 업어 그것의 등 뒤로 넘긴다.', k:'bond', dc:20,
      ok:`그것이 숨을 들이쉴 때마다 하나씩. 일행을 등에 업고 발끝으로 그것 뒤를 지났다.<br><br>업힌 사람의 겁이 이쪽 등에 스민다. 그 겁까지 이쪽이 눌렀다.<br>다섯 번 오갔다. 그것은 끝까지 앞만 봤다. 다리가 다 풀렸다.`,
      ng:`셋째를 업었을 때 업힌 쪽이 떨었다. 떨림이 살기처럼 번졌다.<br><br>그것이 고개를 돌렸다. 업은 채로 뛰었다. 등에 그것의 손톱이 박혔다.<br>둘 다 살았다. 업힌 쪽이 울었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, spirit:-12 } }
  ] },

{ at:'B1', t:'냉동 창고 — 식은 맥',
  x:`냉동 창고에 청소부가 들어온다. 고무장갑 낀 손으로 걸린 것들의 목을 하나씩 짚는다.<br><br>
    언 고기는 지나간다. 따뜻한 데가 있으면 멈춘다.<br>
    산 것을 맥으로 찾는 손이다. 자객도 그렇게 찾는다.<br><br>
    숨을 데는 언 것들 사이뿐이다.`,
  o:[
    { l:'① 내공으로 맥을 눌러 몸을 언 것처럼 식힌다.', k:'steady', dc:21, cost:{ qi:24 },
      doom:{ title:'냉동 화물', what:'언 화물과 함께 실려 갑니다', dc:17, sec:55,
        text:`기운을 거두어 손발 끝부터 식혔다. 맥을 눌러 아주 느리게. 살갗에 서리가 앉는다.<br><br>고무장갑이 목에 닿는다. 멈추지 않는다. 지나간다. 됐다.<br>그런데 몸이 안 돌아온다. 너무 식혔다. 기운이 언 혈 자리에서 막혔다.<br><br>갈고리가 옷깃을 꿴다. 레일이 움직인다. 언 것들과 같이 문 쪽으로. 해무호 쪽으로.`,
        dieText:`해무호 냉동칸에 화물이 가득 실렸다. 다섯 시 십 분이다.<br><br>갈고리마다 언 것이 하나씩.<br>하나는 목에 아직 손가락 자국이 남아 있다.` },
      ok:`기운을 거두어 손발 끝부터 식혔다. 다만 단전 한 점만 남겼다. 불씨처럼.<br><br>고무장갑이 목을 짚는다. 차다. 지나간다.<br>청소부가 나간 뒤 단전의 불씨를 키웠다. 손끝이 하나씩 돌아온다. 아주 아팠다. 살아서 아픈 것이다.`,
      win:{ exp:24, dream:4 } },
    { l:'② 천장 레일에 거꾸로 매달린다.', k:'evade', dc:20,
      ok:`갈고리 레일 위로 올라가 다리를 걸고 매달렸다. 언 고기들 위다.<br><br>청소부는 걸린 것의 목만 짚는다. 레일 위는 안 짚는다. 걸려 있는 것이 아니니까.<br>그가 나갈 때까지 피가 머리로 몰렸다. 내려왔을 때 눈앞이 한참 붉었다.`,
      ng:`레일이 얼어 미끄러웠다. 다리가 풀렸다.<br><br>언 고기 위로 떨어졌다. 고기들이 갈고리째 흔들리며 부딪힌다.<br>청소부가 손전등을 들었다. 고기 사이로 기어서 문까지 갔다. 손바닥이 얼음에 붙었다 떨어졌다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-12 } }
  ] },

{ at:'B1', t:'3번 창고 — 살기 없는 사람',
  x:`청소부가 대걸레를 민다. 상자 하나 건너에 있다.<br><br>
    그에게서 아무것도 맡아지지 않는다. 살기가 없다. 겁도, 화도, 서두름도 없다.<br>
    그는 죽이러 온 게 아니다. 치우러 왔다. 치우는 데는 살기가 안 든다.<br><br>
    살기로 사람을 듣던 귀가 처음으로 먹통이 됐다.`,
  o:[
    { l:'① 살기 대신 물소리로 그를 듣는다.', k:'sense', dc:21,
      ok:`귀를 바꿨다. 살기 말고 물소리. 대걸레가 바닥에 닿는 소리, 짜는 소리, 양동이에 물 떨어지는 소리.<br><br>밀 때는 멀다. 짤 때는 서 있다. 물이 떨어지는 동안은 고개를 숙인다.<br>짜는 소리가 날 때마다 상자 하나씩 건넜다. 그는 끝까지 물만 봤다.<br><br>살기 없는 것도 들을 수 있다. 살기만 듣던 귀가 한 겹 넓어졌다.`,
      ng:`물소리를 듣는데 물소리가 멎었다. 짜지도 밀지도 않는다.<br><br>살기가 없으니 지금 그가 무엇을 하는지 모른다. 보러 고개를 내밀었다.<br>바로 앞에 고무장화가 있다. 대걸레 자루가 이마를 쳤다. 눈앞이 하얘졌다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-24, mind:-14 }, wake:1 },
    { l:'② 소금 자루 뒤에서 상처를 소금으로 씻는다.', k:'heal', dc:19,
      ok:`자루 하나가 터져 굵은 소금이 쏟아져 있다. 한 줌 쥐어 팔 상처에 문질렀다.<br><br>이를 악물었다. 소리는 안 냈다. 소금은 피 냄새도 덮는다.<br>남은 덩이는 기름종이에 싸 품에 넣었다.`,
      ng:`소금을 문지르는 순간 숨이 샜다. 짧게.<br><br>대걸레 소리가 멈췄다. 상자 너머에서 장화가 이쪽으로 돈다.<br>소금 자루를 넘어뜨리고 그 뒤로 기었다. 쏟아진 소금이 상처를 다시 덮쳤다.`,
      win:{ exp:14, dream:1, item:'소금 덩이', hp:6 }, lose:{ hp:-22, spirit:-12 } },
    { l:'③ 상자 너머에서 살기를 일부러 흘려 본다.', k:'hide', dc:22,
      ok:`살기를 못 내는 사람이 살기를 맡을 수는 있는지 시험했다. 상자 너머에서 살기를 한 줄 흘렸다.<br><br>그는 대걸레를 멈추지 않았다. 고개도 안 들었다. 정말 못 맡는다.<br>그렇다면 그는 이쪽을 눈으로만 찾는다. 눈만 피하면 된다. 그건 할 줄 안다.`,
      ng:`살기를 흘렸다. 그는 못 맡았다.<br><br>대신 창고 다른 쪽에서 무언가 맡았다. 상자 위로 고개가 올라온다. 사람 고개가 아니다.<br>상자 사이를 이리저리 쫓겼다. 정강이가 팔레트 모서리에 깨졌다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, mind:-12 } }
  ] },

{ at:'B1', t:'야적장 — 컨테이너 지붕',
  x:`컨테이너가 서너 층으로 쌓였다. 사이 골목은 좁고 길다. 골목마다 손전등이 돈다.<br><br>
    지붕은 비어 있다. 비가 지붕을 두드려 북처럼 운다.<br>
    지붕과 지붕 사이는 사람 키 두 배.<br><br>
    젖은 철판 위를 발끝으로 건너는 걸음은 배웠다. 이렇게 젖은 데서 해 본 적은 없다.`,
  o:[
    { l:'① 내공을 실어 지붕에서 지붕으로 건넌다.', k:'evade', dc:21, cost:{ qi:24 },
      ok:`기운을 발바닥 가운데 모았다. 철판에 닿는 건 발끝의 한 점.<br><br>건넜다. 하나, 둘, 셋. 북소리 같은 빗소리가 발소리를 다 먹었다.<br>아래 골목에서 손전등이 돌았다. 위는 비추지 않았다. 비 오는 날에는 아무도 위를 안 본다.`,
      ng:`셋째 지붕 철판이 기름에 젖어 있었다. 발끝이 미끄러졌다.<br><br>모서리에 손가락만 걸렸다. 아래 골목에서 손전등이 올라온다.<br>몸을 끌어올리는 데 손톱이 둘 깨졌다. 빛이 바로 아래를 지나갔다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, mind:-12 } },
    { l:'② 골목 손전등이 지나간 뒤를 따라 걷는다.', k:'hide', dc:21,
      ok:`손전등 뒤에 붙었다. 빛은 앞을 비춘다. 뒤는 안 비춘다.<br><br>빛을 든 것이 골목 끝에서 돌아설 때마다 옆 골목으로 꺾었다. 빛이 지나간 데는 방금 확인한 데다. 다시 안 본다.<br>야적장 끝까지 남의 빛 뒤에서 걸었다.`,
      ng:`빛을 든 것이 갑자기 뒤돌아섰다. 확인한 데를 다시 보는 놈이었다.<br><br>빛이 정면으로 얼굴에 꽂혔다.<br>컨테이너 문을 열고 뛰어들었다. 안에 든 상자 모서리에 갈비를 찧었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-14 } }
  ] },

{ at:'B1', t:'방파제 — 우산 아래 맥',
  x:`방파제 끝에 검은 우산이 서 있다. 처음에 일을 준 남자다.<br><br>
    <span style="color:#9fb4c8;">"수고했소. 배는 조금 늦소."</span><br>
    말은 차분하다. 그런데 자객의 눈에는 다른 게 보인다. 목의 핏줄이 한 번도 안 뛴다. 말하는 동안 한 번도.<br><br>
    남자가 손을 내민다. 악수하자는 손이다.`,
  o:[
    { l:'① 악수하며 손목 맥을 짚는다.', k:'gaze', dc:21,
      ok:`손을 잡으며 엄지를 손목 안쪽에 댔다. 버릇처럼. 아무도 모를 만큼.<br><br>뛴다. 아주 느리게. 열을 셀 때 한 번. 잠든 사람의 맥이다. 깨어 말하는 사람의 맥이 아니다.<br>우산 아래 이 사람은 깨어 있지 않다. 누가 대신 말하고 있다.<br><br>손을 놓고 웃었다. 배를 기다리지 않기로 했다. 맥으로 거짓을 읽는 손이 하나 더 생겼다.`,
      ng:`엄지를 대는 순간 남자가 손을 비틀었다. 이쪽 엄지가 이쪽 손목 쪽으로 꺾였다.<br><br><span style="color:#9fb4c8;">"남의 맥을 짚는 버릇. 그 일 하는 사람들은 다 그렇더군."</span><br>손을 빼는 데 손목 힘줄이 늘어났다. 우산 아래서 남자 목의 핏줄이 처음으로 한 번 뛰었다. 웃은 것이다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-22, spirit:-16 }, wake:1 },
    { l:'② 손을 안 잡고 한 걸음 물러선다.', k:'steady', dc:20,
      ok:`손을 안 잡았다. 젖은 손이라 실례라고 했다.<br><br>남자는 손을 거두지 않는다. 한참 내밀고 있다. 빗물이 손바닥에 고인다.<br>고인 물이 넘치지 않는다. 손바닥이 아주 조금씩 마셔 들인다. 물러섰다. 그것으로 충분했다.`,
      ng:`물러서는데 등 뒤가 방파제 끝이다. 아래는 검은 물.<br><br>남자가 손을 거둔다. 대신 우산을 기울였다. 우산 끝이 이쪽 가슴을 민다. 가볍게.<br>발뒤꿈치가 허공에 걸렸다. 겨우 버텼다. 그 뒤로 숨이 한참 안 돌아왔다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-16, spirit:-16 } }
  ] },

{ at:'B2', t:'폐쇄 병동 — 진정제',
  x:`팔뚝에 주사 자국이 있다. 잠든 사이 누가 놨다.<br><br>
    팔부터 무겁다. 무거운 게 위로 올라온다. 어깨, 목, 눈꺼풀.<br>
    여기서 잠들면 다음 정각에 세어지는 쪽이다. 세어지기만 하면 다행이다.<br><br>
    자객은 몸에 들어온 독을 기운으로 민다. 진정제도 독이다.`,
  o:[
    { l:'① 내공으로 약 기운을 손끝으로 밀어낸다.', k:'steady', dc:21, cost:{ qi:22 },
      ok:`단전에서 기운을 끌어 무거운 데를 밀었다. 어깨에서 팔로, 팔에서 손목으로.<br><br>손끝 하나를 깨물어 터뜨렸다. 검은 방울이 맺혀 떨어진다. 약이다. 다섯 방울.<br>눈꺼풀이 가벼워졌다. 정각에 간호사가 이쪽 이름을 불렀다. 대답이 또렷하게 나왔다.<br><br>독을 밀어내는 길이 손끝까지 하나 더 났다. 다음엔 더 빨리 민다.`,
      ng:`기운이 약에 섞여 같이 무거워졌다.<br><br>미는 손이 둔해진다. 어깨에서 멈췄다. 눈이 감긴다.<br>정각에 이름이 불렸다. 대답이 반만 나왔다. 계수기가 두 번 눌렸다. 깨어났을 때 침대가 복도 쪽으로 반쯤 끌려 나가 있었다.`,
      win:{ exp:20, dream:3, mind:6 }, lose:{ mind:-16, spirit:-14 }, wake:1 },
    { l:'② 약 기운에 맞춰 잠든 척 숨을 늘인다.', k:'hide', dc:20,
      ok:`약에 취한 숨을 흉내 냈다. 길고 무겁게. 눈꺼풀 아래 눈동자는 굴리지 않았다.<br><br>흰 옷이 들어와 손목을 짚는다. 맥이 느리다. 고개를 끄덕이고 나간다.<br>약 맞은 사람은 내버려 둔다. 그 사이 혀를 깨물어 정신을 붙들었다. 진짜로 잠들 뻔했다.`,
      ng:`흉내 낸 숨이 진짜가 됐다. 약이 이겼다.<br><br>깨어 보니 정각이 두 번 지났다. 팔뚝에 주사 자국이 하나 늘었다.<br>머리가 납처럼 무겁다. 누가 이쪽 손톱 밑에 무언가 적어 두었다. 숫자다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-18, spirit:-14 } }
  ] },

{ at:'B2', t:'처치실 — 맥으로 세는 손',
  x:`처치실 복도에서 흰 옷이 침대마다 손목을 짚는다. 얼굴은 안 본다. 맥만 짚고 차트에 적는다.<br><br>
    차트마다 맥 숫자가 적혀 있다. 이름 대신 맥으로 사람을 가린다.<br>
    이쪽 침대 차트에는 『72』. 이쪽 맥은 지금 백이 넘는다. 쫓겨 왔으니까.<br><br>
    숫자가 다르면 다른 사람이다. 다른 사람은 여기 있으면 안 된다.`,
  o:[
    { l:'① 내공으로 맥을 아예 멈춰 죽은 척한다.', k:'steady', dc:21,
      doom:{ title:'시신 운반', what:'시신 운반차에 실려 갑니다', dc:17, sec:55,
        text:`맥을 눌러 멈췄다. 숨도 닫았다. 죽은 것은 안 센다고 여겼다.<br><br>흰 손이 손목을 짚는다. 오래 짚는다. 차트에 무언가 적는다. 『0』.<br>바퀴 소리가 온다. 덜컹거리는 운반차다. 시트가 얼굴까지 덮인다.<br><br>여기서는 죽은 것도 센다. 다른 칸에. 운반차가 밀린다. 내려가는 승강기는 없는데, 내려간다.`,
        dieText:`처치실 복도 끝 차트판에 칸이 하나 늘었다. 『0』 칸이다.<br><br>그 칸에는 이름이 많다.<br>맨 아래 이름은 아직 잉크가 마르지 않았다.` },
      ok:`맥을 멈추려다 그만뒀다. 차트판 맨 아래에 『0』 칸이 있다. 이름이 빽빽하다.<br><br>여기는 죽은 것도 센다. 세어서 어디론가 보낸다.<br>대신 맥을 반쯤만 눌렀다. 느리게, 약하게. 흰 손이 고개를 갸웃하고 차트에 『?』를 적고 갔다. 물음표에는 다음 정각까지 아무도 안 온다.`,
      win:{ exp:22, dream:3 } },
    { l:'② 내공으로 맥을 차트 숫자에 맞춘다.', k:'hide', dc:21, cost:{ qi:22 },
      ok:`기운으로 심장을 감쌌다. 백에서 아흔, 여든. 일흔둘에서 멈춰 붙들었다.<br><br>흰 손이 손목을 짚는다. 시계를 본다. 일흔둘. 차트에 점을 찍고 다음 침대로 간다.<br>이쪽은 『72』가 됐다. 명패의 이름이 누구였든.<br><br>맥을 숫자 하나에 못 박아 두는 손. 남의 맥으로 사는 법을 몸이 알았다.`,
      ng:`일흔다섯에서 더 안 내려간다. 셋이 모자란다.<br><br>흰 손이 시계를 오래 본다. 차트에 줄을 긋는다. 이쪽 명패를 뗀다.<br>명패 없는 침대는 비워야 할 침대다. 끌어내리는 손을 뿌리치고 커튼 뒤로 숨었다. 손목에 손톱자국이 깊게 남았다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-14, spirit:-18 }, wake:1 }
  ] },

{ at:'B2', t:'휴게실 — 식은 차',
  x:`휴게실 탁자에 찻잔이 놓여 있다. 일행 수대로. 김은 이미 식었다.<br><br>
    쪽지가 받쳐져 있다. 『수고하셨습니다. — 간호부』<br>
    자객은 독을 냄새로 안다. 쓰는 일도 했으니까.<br><br>
    한 잔에서만 아몬드 냄새가 아주 엷게 난다.`,
  o:[
    { l:'① 독이 든 잔을 가려낸다.', k:'gaze', dc:20,
      ok:`잔마다 코를 댔다. 넷은 그냥 식은 보리차다. 하나에서만 아몬드.<br><br>그 잔 받침 밑을 봤다. 쪽지 글씨가 다른 잔보다 반듯하다. 이 잔만 따로 적었다.<br>다 쏟았다. 일행에게는 아무 말 안 했다. 독이 하나뿐이라는 게 더 무서운 일이다. 누구 몫인지 정해져 있었다는 뜻이니까.`,
      ng:`잔마다 코를 댔다. 다섯 다 아몬드 냄새가 난다. 엷게.<br><br>코가 먼저 독을 마셨다. 머리가 핑 돈다.<br>탁자를 짚고 버텼다. 휴게실 벽시계가 두 개로 보였다. 한참 뒤에야 하나가 됐다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, mind:-14 } },
    { l:'② 일부러 한 모금 마시고 내공으로 몸 밖으로 민다.', k:'steady', dc:22, cost:{ qi:24 },
      ok:`아몬드 잔을 들어 한 모금 머금었다. 삼키고, 바로 기운으로 감쌌다.<br><br>독이 위에서 멈춘다. 기운을 돌려 목으로 끌어올렸다. 세면대에 뱉었다. 검다.<br>잔을 비운 채 탁자에 엎어 두었다. 다 마셨다는 표시다.<br><br>얼마 뒤 흰 옷이 와서 엎어진 잔을 보고 고개를 끄덕였다. 이쪽은 그 등 뒤 커튼에 있었다. 죽은 줄 아는 사람은 다시 안 찾는다.`,
      ng:`기운이 독보다 늦었다. 반은 이미 피에 들어갔다.<br><br>목으로 끌어올리다 가슴이 타는 것 같았다. 바닥에 웅크렸다. 손가락이 저려 펴지지 않는다.<br>일행이 등을 두드려 겨우 토해 냈다. 입술이 한참 파랬다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-30, mind:-14 } }
  ] },

{ at:'B2', t:'비상계단 — 난간 틈으로',
  x:`비상계단 위층에서 흰 신발 소리가 내려온다. 여럿이다. 아래층에서도 올라온다.<br><br>
    계단참 가운데 난간 틈이 있다. 위아래로 뚫렸다. 어깨 하나 들어갈 폭.<br>
    떨어지면 여러 층이다. 남은 길은 그것 하나다.<br><br>
    몸을 가볍게 하는 법은 안다. 떨어지는 몸을 가볍게 한 적은 없다.`,
  o:[
    { l:'① 내공을 실어 난간을 짚으며 틈으로 내려간다.', k:'evade', dc:22, cost:{ qi:26 },
      ok:`틈으로 몸을 넣었다. 떨어지면서 층마다 난간을 손끝으로 한 번씩 짚었다. 짚을 때마다 기운을 터뜨려 떨어지는 힘을 끊었다.<br><br>하나, 둘, 셋. 넷째 난간에서 발을 걸고 계단참에 내렸다. 소리는 손끝 다섯 번뿐이다.<br>위아래의 흰 신발들이 빈 계단참에서 만났다.`,
      ng:`셋째 난간을 놓쳤다. 손끝이 젖은 쇠에 미끄러졌다.<br><br>한 층을 그대로 떨어졌다. 계단참에 옆구리부터 박혔다.<br>숨이 안 쉬어진다. 위에서 흰 얼굴들이 틈으로 내려다본다. 기어서 문 안으로 들어갔다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-34, mind:-12 } },
    { l:'② 계단참 문 뒤에 붙어 신발들이 엇갈리게 둔다.', k:'hide', dc:21,
      ok:`계단참 문을 반쯤 열고 문짝 뒤에 섰다. 살기를 바닥까지 내렸다.<br><br>위에서 내려온 것과 아래서 올라온 것이 계단참에서 만났다. 서로를 본다. 잠깐 서로를 센다.<br>열린 문은 셈에 없었다. 둘이 엇갈려 각자 가던 데로 갔다.`,
      ng:`문짝 뒤에 섰다. 위에서 내려온 것이 문을 닫았다. 닫힌 문 뒤의 이쪽이 드러났다.<br><br>흰 손이 멱살을 잡고 난간 쪽으로 민다. 틈 위로 상체가 넘어간다.<br>문틀을 발로 걸고 빠졌다. 난간 모서리에 등이 길게 쓸렸다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, spirit:-14 } }
  ] },

{ at:'B3', t:'9호차 — 흔들리는 바닥',
  x:`열차 바닥이 쉬지 않고 흔들린다. 좌우로, 아래위로.<br><br>
    흔들리는 바닥에서는 발소리가 제멋대로 난다. 힘을 주면 쿵, 빼면 휘청.<br>
    자는 손님들 사이를 지나야 한다. 깨면 다들 이쪽을 본다. 아무 말 없이.<br><br>
    땅을 잡는 걸음은 배웠다. 움직이는 땅은 배운 적이 없다.`,
  o:[
    { l:'① 무게를 발바닥 가운데 두고 흔들림을 받아 낸다.', k:'hide', dc:20,
      ok:`무릎을 풀었다. 흔들림이 발에서 무릎으로, 무릎에서 허리로 올라와 사라지게.<br><br>몸 위쪽은 가만히 두고 아래만 흔들렸다. 열차가 기울 때 같이 기울고, 펴질 때 같이 폈다.<br>통로 끝까지 발소리가 한 번도 안 났다. 자는 사람들 고개가 창 쪽으로 기운 채 그대로다.<br><br>움직이는 땅도 땅이다. 잡지 않고 타는 걸음이 하나 늘었다.`,
      ng:`열차가 이음매에서 크게 튀었다. 무릎이 늦게 풀렸다.<br><br>쿵. 통로에 발소리가 크게 울렸다.<br>자던 얼굴들이 일제히 눈을 떴다. 눈들이 이쪽에 붙었다. 다음 칸에 갈 때까지 등에서 안 떨어졌다. 목덜미가 오래 저렸다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-16, spirit:-16 }, wake:1 },
    { l:'② 좌석 등받이를 짚으며 간다.', k:'evade', dc:19,
      ok:`등받이 꼭대기를 손끝으로 짚었다. 흔들릴 때마다 손으로 받았다.<br><br>발은 거의 안 썼다. 손바닥이 바닥 대신이었다.<br>끝 문에 닿았다. 등받이마다 손자국이 남았을 것이다. 얕게.`,
      ng:`짚은 등받이에 사람 머리가 기대 있었다. 머리카락을 짚었다.<br><br>머리가 천천히 돌아본다. 이쪽 손을, 그리고 이쪽 얼굴을.<br>손을 떼고 걸었다. 그 사람이 일어나 따라온다. 끝 문 앞에서 어깨를 잡혔다. 뿌리치는 데 어깨가 빠질 뻔했다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-22, spirit:-12 } },
    { l:'③ 선반에서 젖지 않은 물병을 챙긴다.', k:'luck', dc:20,
      ok:`선반 끝에 물병이 하나 누워 있다. 마개가 꽉 닫혔다. 이 칸에서 유일하게 안 젖은 것.<br><br>흔들림에 맞춰 손을 뻗어 집었다. 차고 맑다.<br>자는 사람들이 숨을 한 번 멈췄다가 다시 쉬었다.`,
      ng:`물병을 집는데 마개가 열려 있었다. 물이 아래 손님 얼굴로 쏟아졌다.<br><br>그 사람이 눈을 뜨지 않는다. 젖은 얼굴로 웃는다.<br>그 칸을 나오는 내내 등 뒤에서 물 떨어지는 소리가 따라왔다. 한기가 오래 남았다.`,
      win:{ exp:13, item:'맑은 물' }, lose:{ mind:-14, spirit:-14 } }
  ] },

{ at:'B3', t:'특실 — 한 박자 늦은 맥',
  x:`특실 칸 손님 하나가 의심스럽다. 얼굴은 멀쩡하다. 창에 비친 얼굴도 같다.<br><br>
    자객은 얼굴 말고 다른 걸 안다. 얼굴은 혈 자리 몇 개가 붙들고 있다. 빌린 얼굴이면 붙든 손이 다르다.<br>
    맥도 안다. 맥은 빌리기 어렵다.<br><br>
    손님이 졸고 있다. 손목이 팔걸이에 놓였다.`,
  o:[
    { l:'① 내공을 실어 광대 밑 혈을 짚어 얼굴을 흔든다.', k:'gaze', dc:22, cost:{ qi:24 },
      doom:{ title:'잘못 짚은 얼굴', what:'문으로 들어온 것에게 붙들렸습니다', dc:17, sec:50,
        text:`광대 밑 두 혈을 짚고 기운을 넣었다. 빌린 얼굴이라면 미끄러진다.<br><br>안 미끄러진다. 손님이 비명을 지르며 깬다. 진짜 사람이다. 진짜 얼굴이다.<br>비명을 듣고 통로 문이 열린다. 들어오는 얼굴이 이쪽 얼굴이다.<br><br>진짜 이쪽은 여기 있다. 그런데 일행이 문 쪽 이쪽을 본다. 문 쪽의 것이 손을 뻗어 이쪽 목을 쥔다.`,
        dieText:`특실 칸 손님 하나가 잠든다. 손목이 팔걸이에 놓였다.<br><br>통로 문 옆에 일행 하나가 기대 서 있다.<br>아무도 그쪽이 몇 번째로 들어왔는지 안 센다.` },
      ok:`광대 밑 두 혈을 짚었다. 기운을 아주 조금만. 사람이면 간지럽고, 아니면 미끄러진다.<br><br>얼굴이 미끄러졌다. 눈꼬리가 반 치 내려갔다 다시 붙는다. 붙는 데 숨 한 번이 걸렸다.<br>손님은 깨지 않았다. 아니, 깨지 않은 척했다. 감은 눈 밑에서 눈알이 이쪽을 따라온다.<br><br>손을 거두고 나왔다. 이 칸의 그것은 이쪽이 안다는 걸 안다. 서두를 것이다.`,
      win:{ exp:24, dream:4 } },
    { l:'② 팔걸이 위 손목의 맥을 몰래 센다.', k:'sense', dc:20,
      ok:`지나가는 척 팔걸이에 손을 얹었다. 손가락 하나가 손목 위에 닿았다.<br><br>뛴다. 그런데 열차 이음매 소리보다 한 박자 늦다. 늘 한 박자. 바깥 소리를 듣고 따라 뛰는 맥이다. 제 박자가 없다.<br>진짜 맥은 제가 먼저 뛴다. 이건 남을 따라 뛴다.<br><br>얼굴이 아니라 맥으로 가짜를 가리는 손. 이 열차에서 그 손이 하나 생겼다.`,
      ng:`손가락이 닿자 손목이 뒤집혔다. 손님의 손이 이쪽 손목을 쥔다.<br><br>눈을 감은 채다. 이쪽 맥을 센다. 천천히, 꼼꼼히.<br>뿌리쳤다. 그 사이에 이쪽 맥을 다 외웠을 것이다. 다음엔 이쪽 맥으로 뛸 것이다. 그 생각에 한참 손이 떨렸다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-18 }, wake:1 }
  ] },

{ at:'B3', t:'화물칸 — 개 우리',
  x:`화물칸에 쇠우리가 늘어섰다. 입마개 한 개들이 코를 철망에 대고 있다.<br><br>
    짖지 않는다. 입마개 때문이 아니다. 짖지 않게 길렀다.<br>
    맡는 개들이다. 피, 땀, 겁. 그리고 칼을 쥔 사람에게서 나는 것.<br><br>
    우리 사이 통로를 지나야 앞 칸이다.`,
  o:[
    { l:'① 피와 땀과 살기를 차례로 지운다.', k:'hide', dc:21,
      ok:`석탄 가루로 손과 목을 문질렀다. 피와 땀이 덮인다.<br><br>남은 건 살기다. 칼 쥐던 손을 폈다. 손바닥을 철망 쪽으로 보이게 하고 걸었다. 빈손이라는 걸 코가 아니라 눈으로 보게.<br>개들이 철망에서 코를 뗐다. 하나씩 엎드린다. 맡을 것이 없는 것은 지나가게 둔다.`,
      ng:`살기가 다 안 지워졌다. 소매 속 비수가 생각났다. 생각하자 났다.<br><br>개 한 마리가 일어섰다. 입마개 사이로 숨이 거칠다. 우리 빗장이 저절로 덜컥 풀린다.<br>앞 칸 문까지 뛰었다. 종아리를 물렸다. 입마개를 하고도 문다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, spirit:-12 } },
    { l:'② 내공으로 숨을 닫고 맥을 바닥까지 내린다.', k:'steady', dc:20, cost:{ qi:22 },
      ok:`숨을 단전 아래로 내려 닫았다. 맥을 눌렀다. 몸이 짐짝처럼 식는다.<br><br>개들은 산 것을 맡는다. 짐짝은 안 맡는다. 화물칸에는 짐짝이 많다.<br>짐짝 하나가 천천히 통로를 지났다. 개들은 철망 너머로 그걸 따라보기만 했다.`,
      ng:`숨을 닫았는데 겁이 새어 나왔다. 숨이 안 쉬어지니 겁이 났다.<br><br>개들이 일제히 일어섰다. 겁 냄새는 숨을 안 쉬어도 난다.<br>철망이 흔들렸다. 뛰어 지났다. 우리 모서리에 허벅지가 길게 찢겼다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-14 } }
  ] },

{ at:'B3', t:'탄수차 위 — 맞바람',
  x:`기관실로 가는 길은 탄수차 위밖에 없다. 비가 옆으로 날아온다. 바람이 몸을 떼어 내려 한다.<br><br>
    석탄 더미 끝에서 기관실 지붕까지 한 번에 건너야 한다. 사이는 비었다. 선로가 아래로 흘러간다.<br>
    바람을 타는 걸음은 안다. 이렇게 센 바람은 처음이다.<br><br>
    멀리 터널 입구가 다가온다.`,
  o:[
    { l:'① 내공을 실어 바람이 꺾이는 순간 뛴다.', k:'evade', dc:21, cost:{ qi:25 },
      ok:`바람을 셌다. 불다가, 아주 잠깐 꺾인다. 열차가 굽은 데를 돌 때다.<br><br>굽은 데가 왔다. 기운을 다리에 몰아 뛰었다. 바람이 꺾인 틈으로 몸이 날아간다.<br>기관실 지붕에 손바닥이 닿았다. 붙었다. 등 뒤로 바람이 다시 몰아친다. 늦었으면 선로 위였다.`,
      ng:`뛰는 순간 바람이 다시 불었다.<br><br>몸이 옆으로 밀렸다. 기관실 지붕 모서리에 팔꿈치만 걸렸다. 다리가 허공에서 흔들린다.<br>기어올랐다. 팔꿈치 살이 다 벗겨졌다. 터널이 머리 위를 지나갔다.`,
      win:{ exp:21, dream:3 }, lose:{ hp:-32, mind:-12 } },
    { l:'② 엎드려 터널을 지나 보낸 뒤 건넌다.', k:'steady', dc:20,
      ok:`석탄 더미에 엎드렸다. 손을 석탄 속 깊이 박았다.<br><br>터널이 덮쳤다. 그을음과 굉음. 그 안에서는 바람이 없다. 서른을 셌다.<br>터널을 나오기 직전, 바람 없는 마지막 숨 동안 건넜다. 기관실 지붕이 발밑에 왔다.`,
      ng:`터널 안에서 그을음이 숨을 막았다. 기침이 나 손이 빠졌다.<br><br>석탄과 같이 미끄러졌다. 가장자리에 발이 걸렸다.<br>터널을 나와 다시 기어올랐다. 눈에 그을음이 들어가 한참 앞이 안 보였다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-14 } }
  ] }
]);

// ── 그림자술사 (shadow) · 마력 ──
kJob('shadow', 'B', [
{ at:'B', t:'네온 — 깜빡이는 그림자',
  x:`길 건너 네온 간판이 깜빡인다. 켜짐, 꺼짐. 고장 난 박자다.<br><br>
    켜지면 골목에 그림자가 선다. 꺼지면 다 사라진다.<br>
    그림자술사에게 그림자는 길이다. 이 골목의 길은 반만 있다.<br><br>
    골목 끝에 손전등을 든 것이 서 있다. 그림자가 아니라 사람을 찾는다.`,
  o:[
    { l:'① 간판이 켜질 때만 그림자에서 그림자로 옮긴다.', k:'hide', dc:21,
      ok:`켜짐. 쓰레기통 그림자에 발을 넣었다. 꺼짐. 멈췄다. 숨도.<br><br>켜짐. 처마 그림자로. 꺼짐. 켜짐. 계단 그림자로. 박자가 고르지 않아 한 번은 셋을 세고 한 번은 하나를 셌다.<br>손전등 옆을 지날 때 간판이 켜졌다. 그 사람 발밑 그림자 속에 이쪽이 겹쳐 있었다.<br><br>반만 있는 길도 길이다. 빛이 끊기는 박자까지 몸에 들였다. 그림자가 깜빡여도 이제 안 놓친다.`,
      ng:`세 번째 켜짐이 오지 않았다. 간판이 아예 꺼졌다.<br><br>그림자 속에 있던 몸이 그냥 어두운 골목에 서 있게 됐다. 손전등이 돈다. 얼굴에 꽂힌다.<br>뛰었다. 젖은 계단에서 미끄러져 정강이를 찧었다.`,
      win:{ exp:21, dream:3 }, lose:{ hp:-24, spirit:-14 }, wake:1 },
    { l:'② 마력으로 꺼진 동안에도 그림자를 붙든다.', k:'steady', dc:20, cost:{ mana:22 },
      ok:`간판이 켜졌을 때 골목 그림자들을 손으로 쓸어 모았다. 마력으로 바닥에 눌러 붙였다.<br><br>꺼져도 그림자가 남는다. 빛 없이 남은 그림자는 더 검다.<br>그 위로 걸었다. 손전등 빛이 닿아도 그림자는 비켜 주지 않았다. 빛이 그림자에 먹혔다.`,
      ng:`붙들었는데 간판이 다시 켜지자 그림자가 두 겹이 됐다. 붙든 것과 새로 선 것.<br><br>두 겹 그림자가 골목 바닥에 이상하게 진했다. 손전등이 그 진한 데서 멈췄다.<br>그림자를 놓고 달렸다. 놓은 그림자가 발목을 한 번 잡아당겼다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, mind:-14 } }
  ] },

{ at:'B', t:'젖은 바닥 — 비친 것과 진 것',
  x:`비 온 바닥은 거울이다. 불빛마다 거꾸로 비친다.<br><br>
    골목 입구에 사람이 서 있다. 바닥에 그 사람이 거꾸로 비친다. 그런데 그림자가 없다. 가로등 바로 밑인데.<br>
    비치는 건 빛이 하는 일이다. 그림자는 몸이 하는 일이다.<br><br>
    몸 없이 빛만 있는 것이 이쪽으로 걸어온다.`,
  o:[
    { l:'① 비친 것을 무시하고 그림자만 본다.', k:'gaze', dc:20,
      ok:`바닥의 거꾸로 선 사람에게서 눈을 뗐다. 그림자만 봤다.<br><br>그림자는 거짓말을 안 한다. 그림자가 없으니 거기 몸은 없다. 걸어오는 것은 빛이다. 가로등이 꺼지면 같이 꺼진다.<br>가로등 전선 이음매를 찾아 돌로 쳤다. 빛이 죽자 골목 입구가 텅 비었다.`,
      ng:`그림자만 봤다. 없다. 몸이 없다.<br><br>그런데 바닥에 비친 그것의 손이 바닥에 비친 이쪽의 발목을 잡았다. 비친 것끼리.<br>진짜 발목이 차가워졌다. 한참 절었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, spirit:-16 } },
    { l:'② 마력으로 그림자만 떼어 반대쪽으로 걸려 보낸다.', k:'hide', dc:21, cost:{ mana:24 },
      ok:`발뒤꿈치에서 그림자를 뜯었다. 살갗이 같이 당긴다.<br><br>그림자를 반대쪽 골목으로 걸어가게 했다. 이쪽 걸음으로. 가로등 밑을 지날 때 일부러 길게.<br>빛만 있는 것이 그림자를 따라갔다. 그림자를 가진 것이 몸이라고 여기는 것이다. 몸이 없는 것일수록.<br><br>나중에 돌아온 그림자가 발에 붙었다. 미끼로 써도 돌아오는 그림자. 손이 그림자를 멀리 놓아도 안 끊긴다.`,
      ng:`그림자를 떼어 보냈다. 그것은 그림자를 쳐다보지도 않았다.<br><br>그림자 없는 이쪽을 봤다. 그림자 없는 것끼리는 서로 알아본다.<br>그것이 다가와 이쪽 얼굴을 손바닥으로 덮었다. 빛이 눈 안으로 쏟아졌다. 한참 앞이 하얬다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-18 }, wake:1 }
  ] },

{ at:'B', t:'복도 — 그림자 미행',
  x:`쫓는 것들이 어디서 쉬는지 알면 길이 보인다.<br><br>
    방금 하나가 복도를 지나갔다. 그림자를 길게 끌고.<br>
    그림자술사는 제 그림자를 떼어 남의 그림자에 붙일 수 있다. 붙은 그림자는 같이 가서 보고 돌아온다.<br><br>
    돌아올 때 혼자 오는지는 장담 못 한다.`,
  o:[
    { l:'① 마력으로 그림자를 떼어 그것의 그림자에 붙인다.', k:'sense', dc:21, cost:{ mana:22 },
      doom:{ title:'돌아온 그림자', what:'제 그림자에게 끌려갑니다', dc:17, sec:55,
        text:`그림자를 떼어 그것의 그림자 끝에 붙였다. 둘이 같이 복도 끝으로 사라졌다.<br><br>한참 뒤 그림자가 돌아왔다. 발에 붙었다. 무겁다.<br>그림자가 이쪽 걸음을 안 따른다. 이쪽이 그림자 걸음을 따른다. 복도 끝 쪽으로.<br><br>그림자가 본 데로 데려간다. 쉬는 것들이 모인 데로. 다리가 멈추지 않는다.`,
        dieText:`복도 끝 방에 쫓는 것들이 쉬고 있다. 그림자를 길게 끌고.<br><br>그림자 하나가 더 늘었다.<br>주인은 그 그림자 위에 아직 서 있다.` },
      ok:`그림자를 붙여 보냈다. 한참 뒤 돌아왔다. 붙이기 전에 등불 아래 세워 길이를 쟀다.<br><br>손가락 하나만큼 길다. 무언가 묻어 왔다. 끝을 손으로 훑어 짜냈다. 검은 얼룩이 바닥으로 떨어져 기어갔다.<br>그다음에 붙였다. 그림자가 본 것이 머릿속에 들어온다. 복도 끝, 왼쪽 셋째 문, 물 끓는 소리.<br><br>그쪽을 피하는 길을 그렸다.`,
      win:{ exp:23, dream:3 } },
    { l:'② 직접 그것의 그림자 속에 들어가 따라간다.', k:'hide', dc:21,
      ok:`그것의 그림자 안으로 발을 넣었다. 남의 그림자는 차갑다.<br><br>그것이 걸으면 그림자가 끌려가고 이쪽도 끌려갔다. 그것은 제 그림자를 한 번도 안 봤다. 아무도 제 그림자를 안 본다.<br>쉬는 방 앞까지 갔다. 문이 열리기 전에 빠져나왔다.`,
      ng:`그림자 안이 너무 차가웠다. 발가락이 곱았다. 한 걸음 늦었다.<br><br>그림자 밖으로 발이 삐져나왔다. 그것이 걸음을 멈추고 제 발밑을 내려다봤다. 처음으로.<br>그림자가 이쪽 발목을 감은 채 조였다. 겨우 빼냈다. 발목에 검은 줄이 남았다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-24, spirit:-14 } }
  ] },

{ at:'B', t:'쉬는 자리 — 해진 그림자',
  x:`쉬려고 등불 아래 앉았다. 그림자가 이상하다.<br><br>
    어깨 쪽이 뜯겨 나갔다. 아까 문틈에 낀 자리다. 그림자가 다치면 몸도 그쪽이 시리다.<br>
    그대로 두면 뜯긴 데로 무언가 들어온다. 그림자는 빈 데를 오래 못 견딘다.<br><br>
    등불 심지가 짧다. 오래 안 간다.`,
  o:[
    { l:'① 마력을 실로 삼아 뜯긴 데를 꿰맨다.', k:'heal', dc:20, cost:{ mana:20 },
      ok:`손끝에서 마력을 가늘게 뽑았다. 그림자 가장자리를 한 땀씩 끌어당겨 꿰맸다.<br><br>그림자를 꿰매는 바늘은 없다. 손가락이 바늘이다. 땀마다 어깨가 따끔했다.<br>심지가 다 타기 직전에 끝냈다. 어깨가 따뜻해졌다.<br><br>그림자를 다루던 손이 그림자를 고치게 됐다. 찢어져도 끝이 아니다.`,
      ng:`땀이 고르지 않았다. 당긴 데가 비틀렸다.<br><br>꿰맨 그림자가 어깨 하나만 높다. 이쪽 몸은 그렇지 않은데.<br>그 뒤로 걸을 때마다 그림자가 한쪽으로 기운다. 몸도 따라 기울려 했다. 밤새 어깨가 결렸다.`,
      win:{ exp:18, dream:2, mind:8 }, lose:{ mind:-14, spirit:-16 }, wake:1 },
    { l:'② 일행 그림자를 겹쳐 뜯긴 데를 덮어 둔다.', k:'bond', dc:19,
      ok:`옆에 앉은 일행에게 몸을 붙였다. 둘의 그림자가 겹친다. 이쪽 뜯긴 어깨가 그쪽 그림자에 덮였다.<br><br>남의 그림자로 남의 빈 데를 덮는 건 잠깐은 된다.<br>밤새 그렇게 앉아 잤다. 일행은 이유를 안 물었다.`,
      ng:`겹치자 일행이 몸을 떨었다. 이쪽 빈 데로 그쪽 그림자가 빨려 들어간다.<br><br>둘이 같이 시렸다. 떼어 냈다.<br>일행 그림자 가장자리가 조금 묽어져 있었다. 미안하다고 했다. 그쪽은 무슨 말인지 몰랐다.`,
      win:{ exp:15, dream:2, hp:6 }, lose:{ mind:-12, spirit:-16 } },
    { l:'③ 뜯긴 데를 그대로 두고 등불을 끈다.', k:'hide', dc:21,
      ok:`등불을 껐다. 빛이 없으면 그림자도 없다. 없는 것은 다칠 데도 없다.<br><br>어둠 속에서 몸이 그림자 없이 쉬었다. 처음으로 그림자 걱정 없이 잤다.<br>새벽에 빛이 들자 그림자가 돌아왔다. 뜯긴 데가 조금 아물어 있었다.`,
      ng:`등불을 껐다. 어둠 속에서 무언가 어깨에 닿았다. 그림자가 뜯긴 자리에.<br><br>빛이 없어도 그 자리는 비어 있었던 것이다.<br>손으로 쳐냈다. 손바닥에 차갑고 끈적한 것이 묻었다. 밤새 어깨가 얼음 같았다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, spirit:-14 } }
  ] },

{ at:'B', t:'문틈 아래 — 발 그림자',
  x:`잠긴 문 아래 틈으로 빛이 새어 든다. 빛 속에 발 그림자가 넷.<br><br>
    두 사람이다. 문을 지킨다.<br>
    그림자술사는 그림자로 무게를 안다. 무거운 발은 그림자 가장자리가 또렷하고, 가벼운 발은 번진다.<br><br>
    한 쌍은 또렷하다. 한 쌍은 그림자 가장자리가 아예 없다. 빛 속에 구멍이 난 것처럼.`,
  o:[
    { l:'① 마력으로 그림자를 틈 너머로 밀어 빗장을 연다.', k:'hide', dc:22, cost:{ mana:24 },
      doom:{ title:'문 아래 틈', what:'문틈 아래로 끌려 들어갑니다', dc:17, sec:50,
        text:`손가락 그림자를 길게 늘여 틈으로 넣었다. 문 저쪽 빗장 그림자에 닿았다. 들어 올린다.<br><br>그때 구멍 같은 발이 움직였다. 이쪽 손가락 그림자를 밟았다.<br>밟힌 그림자가 안 빠진다. 저쪽에서 당긴다. 손가락이 문 아래 틈으로 끌려간다.<br><br>틈은 손가락 하나 들어갈 폭이다. 손이 따라간다. 팔이 따라간다.`,
        dieText:`잠긴 문 아래 틈으로 빛이 새어 든다.<br><br>빛 속에 발 그림자가 여섯.<br>가장자리가 없는 발이 둘로 늘었다.` },
      ok:`그림자를 넣기 전에 구멍 같은 발의 자리를 봤다. 문 왼쪽이다. 그림자를 오른쪽 끝으로 붙여 넣었다.<br><br>빗장 그림자를 들어 올렸다. 빗장이 따라 들렸다. 그림자가 들리면 몸도 들린다.<br>문이 소리 없이 반 뼘 열렸다. 또렷한 발 쪽이 돌아보는 사이 일행이 반대쪽으로 빠졌다. 구멍 같은 발은 끝까지 안 움직였다.`,
      win:{ exp:24, dream:4 } },
    { l:'② 두 쌍의 그림자를 읽고 비는 때를 기다린다.', k:'gaze', dc:20,
      ok:`또렷한 발은 가끔 무게를 옮긴다. 지루한 사람의 발이다. 오래 서 있으면 자리를 뜬다.<br><br>가장자리 없는 발은 한 번도 안 움직인다. 지루함을 모르는 것이다.<br>또렷한 발이 떠났을 때 문 오른쪽 끝을 살짝 밀어 봤다. 안 잠겼다. 지키는 데가 문이 아니라 문틈이었다.`,
      ng:`기다리는데 가장자리 없는 발이 문틈 쪽으로 다가왔다. 틈 바로 앞.<br><br>틈으로 들어오는 빛이 반으로 줄었다. 그것이 틈에 눈을 댄 것이다. 빛 대신 냉기가 들어온다.<br>물러나다 의자를 넘어뜨렸다. 문 너머가 한참 시끄러웠다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-14, spirit:-16 } }
  ] },

{ at:'B', t:'동행 — 먼저 돌아서는 그림자',
  x:`같이 갇혔다는 남자가 따라붙었다. 나가는 길을 같이 찾자고 한다.<br><br>
    말은 앞으로 하는데 그림자가 자꾸 뒤를 본다. 등불이 흔들릴 때마다 그림자 머리가 뒤쪽으로 돌아간다. 몸은 안 돌았는데.<br>
    그림자는 몸보다 먼저 움직인다. 마음이 가는 쪽으로.<br><br>
    남자의 그림자가 가리키는 뒤쪽은 쫓는 것들이 오는 쪽이다.`,
  o:[
    { l:'① 그림자가 몸보다 먼저 하는 말을 읽는다.', k:'gaze', dc:21,
      ok:`남자를 안 보고 그림자만 봤다. 걷는 동안 그림자의 손이 몇 번 뒤쪽으로 뻗었다. 손짓이다. 이리 오라는.<br><br>모퉁이 앞에서 그림자가 먼저 멈췄다. 남자는 한 걸음 뒤에 멈췄다. 모퉁이 너머에 뭐가 있는지 그림자는 알고 있다.<br>일행을 붙들어 세웠다. 남자에게 먼저 가라고 했다. 남자의 그림자가 한참 머뭇거렸다. 몸보다 오래.<br><br>남자는 혼자 갔다. 그림자는 마지막까지 이쪽을 보고 있었다. 몸이 하는 거짓말을 그림자로 읽게 됐다.`,
      ng:`그림자를 보다가 남자가 알아챘다. 남자 몸이 처음으로 그림자처럼 뒤를 돌아봤다.<br><br><span style="color:#9fb4c8;">"내 그림자가 뭐라고 합디까."</span><br>뒤쪽에서 발소리가 몰려온다. 남자가 부른 것이다. 일행을 끌고 뛰었다. 남자의 그림자가 바닥을 미끄러져 이쪽 발을 걸었다. 무릎이 깨졌다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-24, spirit:-16 }, wake:1 },
    { l:'② 모른 척 따라가며 남자 그림자에 제 그림자를 엮어 둔다.', k:'hide', dc:21,
      ok:`걸으면서 이쪽 그림자 끝을 남자 그림자 발목에 살짝 감았다. 남자는 모른다.<br><br>모퉁이 앞에서 남자가 신호하려 했다. 그림자가 묶여 손이 안 올라갔다. 그림자가 안 따라가면 손도 안 간다.<br>남자 얼굴이 굳었다. 그 사이 다른 길로 일행을 돌렸다. 엮은 그림자는 나중에 풀어 주었다. 멀리서.`,
      ng:`그림자를 감는 순간 남자 그림자가 되감았다. 저쪽도 그림자를 다룬다.<br><br>둘의 그림자가 엉켜 바닥에서 몸부림쳤다. 몸도 같이 비틀렸다.<br>억지로 끊었다. 이쪽 그림자 끝이 저쪽에 남았다. 손끝이 한참 감각이 없었다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-22, mind:-14 } }
  ] },

{ at:'B', t:'갈림길 — 불을 끄는 손',
  x:`앞쪽에서 불이 하나씩 꺼진다. 이쪽으로 다가오며.<br><br>
    딸깍, 딸깍. 스위치 소리다. 누가 끄면서 온다.<br>
    불이 다 꺼지면 그림자가 없다. 그림자가 없으면 그림자술사는 그냥 사람이다.<br><br>
    꺼진 쪽 어둠에서 무언가 움직인다. 빛이 있는 동안은 거기 없던 것이다.`,
  o:[
    { l:'① 마력으로 손바닥에 불씨를 켜 둔다.', k:'fix', dc:20, cost:{ mana:22 },
      ok:`손바닥 위에 손톱만 한 불을 켰다. 작아서 멀리서는 안 보인다. 가까이에는 그림자가 선다.<br><br>마지막 불이 꺼졌다. 어둠 속에 이쪽 손바닥만 남았다. 일행 그림자 다섯이 이쪽 발밑에 짧게 섰다.<br>그림자를 모아 일행을 덮었다. 어둠 속의 것이 지나갔다. 작은 불 옆은 피해서.`,
      ng:`불씨를 켰다. 어둠 속에서 이쪽만 빛났다.<br><br>어둠 속의 것이 그 빛으로 곧장 왔다. 빛이 없는 데 사는 것은 빛을 제일 싫어하고, 제일 먼저 찾는다.<br>불씨를 쥐어 껐다. 손바닥을 데었다. 어깨를 무언가가 할퀴고 지나갔다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-12 } },
    { l:'② 불이 꺼지기 전에 그림자를 접어 품에 넣는다.', k:'hide', dc:21,
      ok:`마지막 불 아래서 그림자를 바닥에서 걷어 올렸다. 손수건처럼 네 번 접었다. 품에 넣었다.<br><br>딸깍. 어둠. 어둠 속의 것이 지나간다. 이쪽은 그림자가 없다. 빛 있을 때 거기 있던 것들 축에 안 든다.<br>한참 뒤 품에서 그림자를 꺼내 펼쳤다. 빛이 없는데도 펼쳐졌다. 검은 위에 더 검게.<br><br>빛이 없어도 꺼내 쓰는 그림자. 그림자를 갖고 다니는 법을 몸이 알았다.`,
      ng:`세 번째 접을 때 불이 꺼졌다. 반만 접힌 그림자가 어둠에 녹았다.<br><br>품에 넣은 것은 그림자 반쪽이다. 나머지 반은 어둠 속에 남았다.<br>어둠 속의 것이 그 반쪽을 주워 갔다. 몸 반쪽이 한참 시렸다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-14, spirit:-18 }, wake:1 }
  ] },

{ at:'B', t:'끝 — 다섯을 하나로',
  x:`나가는 문 앞에 큰 등이 하나 켜져 있다. 그 밑에 그것이 서 있다.<br><br>
    등 아래를 지나야 문이다. 그것은 등 아래 그림자를 센다. 사람 수만큼 그림자가 지나가면 사람 수만큼 잡는다.<br>
    일행 그림자는 다섯이다.<br><br>
    그것 자신의 그림자는 등 아래 바닥에 크게 깔려 있다.`,
  o:[
    { l:'① 다섯 그림자를 꼬아 하나로 만들어 지난다.', k:'hide', dc:22,
      ok:`일행을 한 줄로 바짝 세웠다. 그림자 다섯을 손으로 모아 꼬았다. 밧줄처럼, 한 가닥으로.<br><br>한 그림자 안에 다섯이 들어가 등 아래를 지났다. 그것이 센다. 하나.<br>하나쯤은 그냥 보낸다. 그것이 정한 규칙이 그랬다.<br><br>문 밖에서 그림자를 풀었다. 다섯이 다시 각자 발밑으로 돌아갔다. 남의 그림자 다섯을 한 손에 쥔 무게가 손바닥에 오래 남았다. 손이 그만큼 커졌다.`,
      ng:`넷까지 꼬았다. 하나가 빠졌다. 등 아래에서 그림자가 둘이 됐다.<br><br>그것이 센다. 둘. 둘은 안 보낸다.<br>그것의 팔이 빠진 그림자 주인을 잡으려 했다. 이쪽이 대신 앞에 섰다. 갈비가 울렸다.`,
      win:{ exp:25, dream:4 }, lose:{ hp:-32, spirit:-14 }, wake:1 },
    { l:'② 마력을 다 쏟아 등을 눌러 끈다.', k:'break', dc:21, cost:{ mana:28 },
      ok:`마력을 한 줄로 모아 등을 눌렀다. 빛이 흔들리다 꺼졌다.<br><br>그림자가 없으니 셀 것도 없다. 그것이 어둠 속에서 두리번거린다.<br>그 사이 다섯이 문을 빠졌다. 빛 없는 데서는 그것도 그냥 큰 것이었다.`,
      ng:`등이 반만 꺼졌다. 깜빡인다.<br><br>깜빡이는 빛 속에서 그림자가 열이 됐다가 다섯이 됐다가 한다. 그것이 화를 냈다.<br>바닥의 그림자가 한꺼번에 일어섰다. 벽까지 밀려났다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-34, mind:-14 } },
    { l:'③ 그것 자신의 그림자 속으로 일행을 이끈다.', k:'bond', dc:20,
      ok:`그것의 그림자는 등 아래 크게 깔려 있다. 그 안에 들어가면 이쪽 그림자는 안 생긴다. 남의 그림자 안에서는 그림자가 안 진다.<br><br>일행을 하나씩 그것의 그림자 안으로 데려가 문까지 지났다.<br>제 그림자 안을 세는 것은 없다.`,
      ng:`그것의 그림자 안에서 하나가 넘어졌다.<br><br>그것이 고개를 숙였다. 제 그림자를 처음 봤다.<br>끌어내는 데 어깨가 빠질 뻔했다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, spirit:-12 } }
  ] },

{ at:'B1', t:'3번 창고 — 그림자를 닦는 대걸레',
  x:`청소부가 대걸레를 민다. 백열등 아래서.<br><br>
    대걸레가 지나간 바닥에는 그림자가 안 진다. 상자 그림자도, 기둥 그림자도. 등은 그대로인데.<br>
    그림자술사는 본다. 그는 물을 닦는 게 아니다. 남은 그림자를 닦는다. 누가 있었다는 흔적을.<br><br>
    양동이 물이 잿빛이다. 대걸레가 이쪽 그림자 쪽으로 온다.`,
  o:[
    { l:'① 그림자를 대걸레 길에서 거둬들인다.', k:'hide', dc:22,
      doom:{ title:'잿빛 양동이', what:'양동이 속으로 그림자째 끌려갑니다', dc:17, sec:55,
        text:`그림자를 발밑으로 접어 들였다. 대걸레가 앞을 지나간다. 닿지 않았다.<br><br>그런데 그가 대걸레를 양동이에 짰다. 잿빛 물이 출렁이며 이쪽 그림자 끝 한 올을 핥았다. 접다 만 끝이다.<br>물이 그 한 올을 빨아들인다. 한 올이 두 올이 된다. 그림자가 양동이 쪽으로 풀려 나간다.<br><br>그림자가 끌려가면 몸도 간다. 발이 양동이 쪽으로 미끄러진다.`,
        dieText:`3번 창고 바닥이 깨끗하다. 그림자 하나 없이.<br><br>청소부가 양동이를 들고 나간다. 물이 조금 더 진해졌다.<br>창고 백열등 아래에 이제 아무도 서 있지 않다.` },
      ok:`그림자를 접기 전에 끝까지 셌다. 손가락, 발끝, 옷자락. 한 올도 안 남기고 접어 들였다.<br><br>대걸레가 앞을 지났다. 양동이 물이 출렁였다. 핥을 것이 없었다.<br>그는 이쪽 앞에서 한 번 멈췄다. 바닥을 내려다본다. 그림자 없는 자리에 그림자 없는 몸이 서 있다. 닦을 게 없다. 그는 지나갔다.`,
      win:{ exp:24, dream:4 } },
    { l:'② 양동이 물에 무엇이 섞였는지 들여다본다.', k:'gaze', dc:21,
      ok:`그가 등을 돌린 사이 양동이를 봤다. 잿빛 물 속에서 무언가 움직인다.<br><br>그림자들이다. 사람 모양으로 물속에서 천천히 돈다. 손을 뻗었다 오므린다. 다섯, 일곱, 열.<br>주인은 다 어디 갔을까. 그건 안 보기로 했다.<br><br>대신 알았다. 그림자는 몸을 떠나도 한동안 산다. 제 그림자를 놓쳐도 아직 늦은 게 아니다. 손이 그림자를 다시 붙잡는 법을 하나 더 알았다.`,
      ng:`들여다보는데 물속 그림자 하나가 이쪽을 올려다봤다. 손을 뻗는다. 물 위로.<br><br>이쪽 그림자가 양동이 쪽으로 기울었다. 부르는 것이다.<br>물러섰다. 그림자를 억지로 끌어당겼다. 발목이 꺾이는 것처럼 아팠다. 청소부가 돌아봤다.`,
      win:{ exp:21, dream:3 }, lose:{ hp:-22, spirit:-18 }, wake:1 }
  ] },

{ at:'B1', t:'야적장 — 도는 그림자',
  x:`탐조등이 돈다. 빛이 돌면 컨테이너 그림자도 돈다. 시곗바늘처럼.<br><br>
    그림자 끝이 야적장을 쓸고 지나간다. 그림자 속은 검다. 빛을 든 쪽에서 안 보인다.<br>
    그림자술사에게 저건 움직이는 길이다.<br><br>
    다만 길이 제 마음대로 돈다.`,
  o:[
    { l:'① 도는 그림자 속에 들어가 같이 돈다.', k:'hide', dc:21,
      ok:`컨테이너 그림자가 발밑에 왔을 때 들어갔다. 그림자가 도는 쪽으로 같이 걸었다. 빠르지도 느리지도 않게.<br><br>빛이 이쪽을 지나간다. 이쪽은 늘 그림자 안이다. 빛의 반대편에.<br>그림자가 철문 앞을 지날 때 빠져나왔다. 야적장 절반을 남의 그림자를 타고 건넜다.<br><br>멈춘 그림자만 길이 아니다. 도는 그림자도 탄다. 그림자를 고르는 눈이 넓어졌다.`,
      ng:`그림자를 타고 돌다 그림자가 갑자기 빨라졌다. 탐조등을 누가 세게 돌렸다.<br><br>그림자가 이쪽을 두고 앞서 갔다. 빛 한가운데 혼자 남았다.<br>빛이 멈췄다. 뛰었다. 젖은 철판에 미끄러져 손목을 삐었다.`,
      win:{ exp:21, dream:3 }, lose:{ hp:-26, mind:-12 }, wake:1 },
    { l:'② 마력으로 그림자 하나를 붙들어 세운다.', k:'steady', dc:21, cost:{ mana:24 },
      ok:`컨테이너 그림자 하나를 손으로 눌러 바닥에 박았다. 빛이 돌아도 그 그림자는 안 돈다.<br><br>안 도는 그림자 속을 걸어서 철문까지 갔다. 빛을 든 쪽이 이상하다고 여길 시간은 있었다.<br>철문 앞에서 그림자를 놓았다. 그림자가 제자리로 튕겨 돌아갔다.`,
      ng:`그림자를 붙들었다. 컨테이너가 같이 끌려왔다. 그림자를 붙들면 주인도 멈추려 한다.<br><br>쇠가 긁히는 소리가 야적장을 찢었다. 빛이 이쪽으로 꽂혔다.<br>그림자를 놓고 뛰었다. 손바닥이 그림자 가장자리에 베인 것처럼 쓰라렸다.`,
      win:{ exp:19, dream:2 }, lose:{ hp:-28, mind:-12 } }
  ] },

{ at:'B1', t:'경매장 — 얼음 위의 빛',
  x:`경매장 바닥에 얼음이 깔렸다. 생선 위에도 얼음.<br><br>
    얼음은 빛을 사방으로 튕긴다. 그림자가 엷게 흩어진다. 그림자술사가 제일 약해지는 바닥이다.<br>
    노란 비옷들의 그림자만 겨우 진다. 비옷이 두꺼워서.<br><br>
    경매판 너머 하역장 문까지 얼음판이다.`,
  o:[
    { l:'① 마력으로 엷은 그림자를 짙게 눌러 쓴다.', k:'hide', dc:21, cost:{ mana:22 },
      ok:`흩어진 그림자를 손으로 모았다. 마력으로 눌러 얼음 위에 진하게 붙였다.<br><br>얼음은 빛을 튕기지만 마력은 못 튕긴다. 이쪽 발밑에만 밤이 생겼다.<br>그 밤을 끌고 얼음판을 건넜다. 노란 비옷들은 경매판만 봤다.`,
      ng:`눌러 붙인 그림자가 얼음에 미끄러졌다. 그림자가 이쪽보다 먼저 앞으로 미끄러져 간다.<br><br>얼음판 위에 그림자만 혼자 진하다. 몸은 뒤에 있는데.<br>노란 비옷 하나가 그 진한 그림자를 밟았다. 이쪽이 휘청 넘어졌다. 얼음에 턱을 찧었다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, spirit:-12 } },
    { l:'② 노란 비옷들 그림자 사이에 제 그림자를 끼운다.', k:'fix', dc:20,
      ok:`노란 비옷 셋이 나란히 서 있다. 셋의 그림자가 겹쳐 얼음 위에 큰 덩어리를 만든다.<br><br>그 덩어리에 이쪽 그림자를 붙였다. 하나가 더해져도 덩어리는 덩어리다.<br>비옷들이 하역장 쪽으로 움직일 때 같이 움직였다. 그림자 덩어리가 문 앞에서 흩어졌을 때 이쪽은 문 밖이었다.`,
      ng:`붙이는데 비옷 하나가 제 발밑을 봤다. 그림자가 넷이다. 셋이 서 있는데.<br><br>비옷이 고개를 든다. 고함이 멎었다.<br>갈고리 장대가 얼음 위를 쓸었다. 정강이를 맞고 얼음 위를 굴렀다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-14 } }
  ] },

{ at:'B1', t:'선착장 — 배 그림자',
  x:`해무호가 부두에 붙었다. 갑판 등이 선체 그림자를 부두에 길게 던진다.<br><br>
    그림자는 정문 쪽까지 뻗었다. 그 안을 걸으면 경비 초소에서 안 보인다.<br>
    그런데 배 그림자가 너무 검다. 그림자에도 짙고 옅은 결이 있는데, 이건 결이 없다.<br><br>
    결이 없는 그림자는 비어 있는 게 아니라 무언가로 차 있는 것이다.`,
  o:[
    { l:'① 배 그림자를 타고 정문 쪽으로 간다.', k:'hide', dc:22,
      ok:`그림자 가장자리만 밟았다. 결이 없는 한가운데는 피했다.<br><br>가장자리는 그래도 그림자다. 경비 초소의 빛이 닿지 않는다.<br>정문 기둥 그늘까지 갔다. 돌아보니 배 그림자 한가운데가 조금 부풀어 있었다. 무언가 숨을 쉬듯이.`,
      ng:`가장자리를 밟다 발이 한가운데로 미끄러졌다.<br><br>발목까지 잠겼다. 그림자에. 물처럼 차갑고 진흙처럼 끈적하다.<br>빼내는 데 발목 살이 벗겨지는 것 같았다. 경비 초소 빛이 이쪽을 한 번 스쳤다.`,
      win:{ exp:21, dream:3 }, lose:{ hp:-28, spirit:-14 } },
    { l:'② 결 없는 그림자 안의 것을 먼저 들여다본다.', k:'gaze', dc:21,
      ok:`손가락 그림자를 아주 가늘게 늘여 배 그림자 가장자리에 담갔다.<br><br>안에 그림자가 많다. 사람 그림자들이 겹겹이 누워 있다. 배에 실린 것들의 그림자다. 몸은 배 안에, 그림자는 부두에.<br>배가 떠나면 그림자도 끌려간다. 그림자를 남겨 두면 몸만 실려 간다.<br><br>그림자를 들여다보면 그 몸이 어디 있는지도 보인다. 그림자로 사람을 찾는 눈이 하나 더 열렸다.`,
      ng:`손가락을 담그자 안의 그림자들이 일제히 손을 뻗었다.<br><br>이쪽 손가락 그림자를 잡아끈다. 같이 실려 가자고.<br>끊어 냈다. 손가락 끝 그림자가 짧아졌다. 진짜 손가락 끝도 한참 감각이 없었다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-14, spirit:-18 }, wake:1 }
  ] },

{ at:'B2', t:'폐쇄 병동 — 형광등',
  x:`복도 천장에 형광등이 줄지어 있다. 빛이 사방에서 고르게 내린다.<br><br>
    그림자가 거의 안 진다. 발밑에 엷은 얼룩 하나뿐이다.<br>
    병원 빛은 그림자를 싫어한다. 그림자술사가 제일 맨몸이 되는 곳이다.<br><br>
    형광등 하나가 깜빡인다. 그 아래서만 그림자가 잠깐씩 선다.`,
  o:[
    { l:'① 깜빡이는 등 아래서 그림자를 세워 쓴다.', k:'hide', dc:21,
      ok:`깜빡이는 등 아래로 갔다. 어두워질 때마다 그림자가 섰다. 짧게.<br><br>그 짧은 그림자를 붙잡아 늘였다. 복도 벽을 따라 다음 등까지. 깜빡일 때마다 한 뼘씩.<br>간호사실 앞을 그 그림자 안에서 지났다. 계수기 소리가 멎지 않았다.<br><br>빛이 고르게 내리는 데서도 그림자는 생긴다. 빛이 한 번 숨을 쉴 때. 그 숨을 쓰는 법을 알았다.`,
      ng:`깜빡임이 멎었다. 등이 그냥 밝아졌다. 누가 고쳤다.<br><br>복도 한가운데 그림자 없이 서 있었다. 간호사실 유리 너머로 흰 얼굴이 고개를 든다.<br>커튼 뒤로 뛰어들었다. 링거대가 넘어지며 이마를 쳤다.`,
      win:{ exp:21, dream:3 }, lose:{ hp:-22, spirit:-16 }, wake:1 },
    { l:'② 마력으로 형광등 하나를 죽인다.', k:'break', dc:20, cost:{ mana:22 },
      ok:`손가락을 등에 겨누고 마력을 한 점 쏘았다. 등이 퍽 꺼졌다.<br><br>그 아래에 진짜 어둠이 한 칸 생겼다. 양쪽 등이 그 칸에 그림자를 던진다. 짙다.<br>그 칸을 지나 비상계단 문까지 갔다. 꺼진 등은 정각에 누가 갈러 올 것이다.`,
      ng:`등이 꺼지는 대신 터졌다. 유리가 복도에 쏟아졌다.<br><br>복도 끝에서 흰 신발들이 일제히 이쪽으로 돈다.<br>유리 조각 위를 맨발처럼 뛰었다. 발바닥이 여러 군데 베였다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-12 } }
  ] },

{ at:'B2', t:'정각 점검 — 벽에 진 그림자',
  x:`정각이다. 간호사가 문간에 서서 계수기를 든다.<br><br>
    침대를 보지 않는다. 벽을 본다. 복도 등이 병실 벽에 침대마다 그림자를 던진다. 간호사는 그 그림자를 센다.<br>
    일행 하나가 아직 돌아오지 않았다. 그 침대는 비었다. 벽에 그림자가 하나 모자란다.<br><br>
    숫자가 맞지 않으면 맞을 때까지 센다.`,
  o:[
    { l:'① 마력으로 제 그림자를 반으로 갈라 두 침대에 눕힌다.', k:'hide', dc:22, cost:{ mana:24 },
      ok:`그림자를 가운데서 갈랐다. 머리부터 발끝까지 길게. 몸도 같이 갈라지는 것처럼 아팠다.<br><br>반쪽을 빈 침대 위로 보냈다. 벽에 그림자 둘이 섰다. 둘 다 조금 가늘다.<br>딸깍. 딸깍. 간호사가 셌다. 맞다. 문을 닫고 나갔다.<br><br>그림자 하나로 두 자리를 채웠다. 반으로 갈라도 둘 다 이쪽 것이다. 그림자가 한 몸보다 넓게 쓰인다.`,
      ng:`가르다 반쪽이 너무 가늘었다. 벽에 실 같은 그림자가 섰다.<br><br>간호사가 그 실 앞에서 멈췄다. 계수기를 누르지 않는다. 고개를 기울여 오래 본다.<br>실 그림자를 거둬들이는 순간 간호사가 셌다. 하나 모자란다. 다시 센다. 정각이 끝날 때까지 다섯 번을 셌다. 다섯 번 다 이쪽 침대에서 멈췄다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-16, spirit:-18 }, wake:1 },
    { l:'② 빈 침대에 외투를 세워 그림자를 만든다.', k:'fix', dc:20,
      ok:`의자 등받이에 외투를 걸고 베개를 넣어 빈 침대에 앉혔다. 벽에 사람 어깨 같은 그림자가 섰다.<br><br>간호사가 셌다. 딸깍. 외투 그림자에서도 딸깍.<br>나갔다. 다음 정각까지 일행이 돌아와야 한다. 외투는 오래 못 속인다.`,
      ng:`외투 그림자가 섰다. 그런데 어깨가 너무 넓다. 의자 등받이 모양이 그대로 보인다.<br><br>간호사가 그 앞에서 멈췄다. 외투를 들어 올렸다. 아래에 의자다.<br>계수기가 이쪽 쪽으로 돌았다. 눌리지 않았다. 대신 이쪽 명패가 떼어졌다. 밤새 명패 없는 침대에서 떨었다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-16, spirit:-14 } }
  ] },

{ at:'B2', t:'기록 보관실 — 엑스레이 필름',
  x:`기록 보관실 벽에 판독등이 켜져 있다. 필름이 여러 장 꽂혔다.<br><br>
    필름은 뼈의 그림자다. 빛을 뒤에서 비춰야 보인다.<br>
    한 장의 이름 칸에 이쪽 명패 이름이 적혀 있다. 찍은 날짜는 오늘 밤이다.<br><br>
    그림자술사는 그림자를 읽는다. 뼈의 그림자도 그림자다.`,
  o:[
    { l:'① 이쪽 이름이 적힌 필름을 읽는다.', k:'gaze', dc:21,
      ok:`필름을 봤다. 가슴뼈, 갈비, 팔. 다 이쪽 몸과 같다.<br><br>손가락만 다르다. 한 손에 뼈 그림자가 여섯이다. 이쪽 손가락은 다섯.<br>이 이름의 원래 주인은 손가락이 여섯이었다. 오늘 밤 그 자리에 이쪽을 넣으려고 미리 찍어 둔 것이다. 맞지 않는 데가 하나는 남는다.<br><br>필름을 뽑아 판독등을 뒤집어 꽂았다. 이 필름으로는 이쪽을 못 센다.`,
      ng:`필름을 보는데 뼈 그림자가 움직였다. 손가락 하나가 굽는다. 필름 안에서.<br><br>이쪽 손가락이 같이 굽었다. 펴지지 않는다.<br>필름을 뽑아 판독등을 껐다. 빛이 없어지자 손가락이 풀렸다. 그 손가락 마디가 한참 쑤셨다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-22, spirit:-16 } },
    { l:'② 필름 한 장으로 판독등을 가리고 그 그늘로 지난다.', k:'hide', dc:20,
      ok:`판독등이 보관실에서 제일 밝은 빛이다. 서가 사이를 다 비춘다.<br><br>필름 한 장을 등 앞에 끼웠다. 빛이 필름을 지나며 벽 가득 뼈 그림자를 던졌다. 크고 검게.<br>그 뼈 그림자 안으로 걸어 서가를 지났다. 창가의 경비원은 벽에 진 뼈를 보고 고개를 돌렸다. 보기 싫은 것이다.`,
      ng:`벽에 뼈 그림자가 크게 떴다. 경비원이 고개를 돌리지 않았다. 오히려 일어섰다.<br><br>뼈 그림자 하나에 이쪽 그림자가 겹쳐 있다. 갈비 사이로 사람 모양이 비친다.<br>경비원이 손전등을 켰다. 서가 사이로 기어 빠졌다. 서가 모서리에 머리를 찧었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-14 } }
  ] },

{ at:'B2', t:'세탁실 — 걸린 시트 뒤',
  x:`빨랫줄에 흰 시트가 줄줄이 걸렸다. 뒤쪽 벽등이 시트를 비춘다.<br><br>
    시트마다 그림자가 비친다. 빨랫줄, 집게, 지나가는 직원들.<br>
    그중 하나가 이상하다. 빛은 왼쪽에서 오는데 그 그림자만 오른쪽으로 길다.<br><br>
    빛을 거슬러 지는 그림자는 없다. 그림자가 아니라 시트 안에서 무언가 비치는 것이다.`,
  o:[
    { l:'① 거꾸로 진 그림자를 피해 길을 낸다.', k:'gaze', dc:20,
      ok:`그림자마다 빛의 방향을 맞춰 봤다. 맞는 것은 직원, 안 맞는 것은 시트 안의 것.<br><br>안 맞는 그림자가 셋이다. 시트 셋. 그 셋 사이를 안 지나는 길을 찾았다.<br>빨랫줄 끝을 돌아 다리미대 뒤로 지났다. 시트 셋이 바람도 없이 한 번씩 부풀었다.`,
      ng:`둘은 찾았다. 셋째를 못 봤다. 빛이 마침 셋째 뒤에서 왔다.<br><br>셋째 시트 옆을 지나는데 시트가 이쪽 쪽으로 기울었다.<br>젖은 천이 얼굴에 붙었다. 숨이 막혔다. 뜯어내는 데 손톱이 꺾였다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-14 } },
    { l:'② 제 그림자를 바닥에 눕혀 시트에 안 비치게 하고 지난다.', k:'hide', dc:21,
      doom:{ title:'시트 뒤', what:'시트에 감겨 끌려갑니다', dc:17, sec:55,
        text:`그림자를 발밑에 납작하게 눕혔다. 시트에 아무것도 안 비친다. 시트 사이를 걸었다.<br><br>그런데 시트 안의 것들은 그림자로 보지 않았다. 시트 안에서 이쪽을 직접 본다.<br>시트 하나가 빨랫줄에서 미끄러져 내려온다. 이쪽 어깨를 감는다. 젖고 무겁다.<br><br>둘째 시트가 다리를 감는다. 시트들이 줄을 따라 안쪽으로 끌려간다. 이쪽을 감은 채.`,
        dieText:`빨랫줄에 흰 시트가 줄줄이 걸렸다. 하나가 늘었다.<br><br>그 시트도 벽등 빛을 거슬러 그림자를 던진다.<br>아직 서툴다. 가끔 손 모양이 비친다.` },
      ok:`그림자를 눕히기 전에 시트 아래 틈을 봤다. 거꾸로 진 그림자 셋의 시트 아래로 발이 없다. 천이 바닥에 닿아 있다.<br><br>그 셋은 그림자가 아니라 천으로 본다. 그러니 그림자를 숨겨도 소용이 없다.<br>그 셋 앞에서는 그림자를 오히려 크게 세웠다. 시트에 사람 하나가 크게 비쳤다. 시트 안의 것들이 그 그림자를 감싸려 천을 오므렸다. 그 사이 몸은 옆으로 지났다.`,
      win:{ exp:23, dream:3 } }
  ] },

{ at:'B3', t:'객차 — 지나가는 역 불빛',
  x:`열차가 역을 지나간다. 서지 않는다.<br><br>
    승강장 불빛이 창으로 쏟아져 객차를 쓸고 지나간다. 앞에서 뒤로. 그림자가 그 빛을 따라 의자에서 의자로 넘어간다.<br>
    역 하나에 한 번. 빛이 지나가는 동안만 그림자가 산다.<br><br>
    이쪽은 객차 끝 문까지 가야 한다. 통로에 검표원이 서 있다.`,
  o:[
    { l:'① 역 불빛이 쓸고 갈 때 그림자에 실려 간다.', k:'hide', dc:21,
      ok:`빛이 앞 창으로 들어오는 순간 의자 그림자에 몸을 실었다. 빛이 뒤로 갈 때 그림자가 앞으로 넘어간다. 그 그림자를 탔다.<br><br>세 번 넘어가니 통로 가운데다. 검표원 그림자를 지나 넷째 의자 그림자로.<br>빛이 끝났다. 객차가 다시 어둡다. 이쪽은 끝 문 앞에 있었다. 검표원은 승강장을 보고 있었다.<br><br>스쳐 가는 빛 한 번에도 그림자 길은 생긴다. 짧은 빛을 길게 쓰는 법이 몸에 붙었다.`,
      ng:`셋째 그림자로 넘어가는데 역이 끝났다. 짧은 역이었다.<br><br>그림자가 꺼졌다. 통로 한가운데, 검표원 바로 앞이다.<br>검표원이 표를 달라고 손을 내민다. 손이 이쪽 손목을 쥔다. 뿌리치는 데 손목이 비틀렸다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-24, spirit:-14 }, wake:1 },
    { l:'② 검표원 그림자를 잠깐 바닥에 눌러 둔다.', k:'steady', dc:21, cost:{ mana:22 },
      ok:`역 불빛이 들어올 때 검표원 그림자가 통로에 섰다. 그림자 발목을 마력으로 바닥에 눌렀다.<br><br>검표원이 돌아서려다 못 돈다. 발이 안 떨어진다. 제 발을 내려다본다.<br>그 사이 옆을 지났다. 빛이 끝나자 그림자가 풀렸다. 검표원은 한참 제 구두를 봤다.`,
      ng:`눌렀는데 검표원이 그림자째 돌아섰다. 그림자를 끌고.<br><br>마력이 손에서 뜯겨 나갔다. 검표원이 이쪽을 본다. 표 구멍 뚫는 집게를 든 채.<br>집게가 손등을 물었다. 구멍이 하나 났다.`,
      win:{ exp:19, dream:2 }, lose:{ hp:-26, mind:-12 } },
    { l:'③ 선반 그림자 속 가방에서 먹을 것을 꺼낸다.', k:'luck', dc:20,
      ok:`선반 위는 늘 그림자다. 빛이 거기까지 안 닿는다.<br><br>그림자 안으로 손을 넣었다. 가방 하나, 기름종이 꾸러미. 말린 고기다.<br>꺼낼 때도 그림자 안으로만 손을 움직였다. 아래 손님은 끝까지 눈을 안 떴다.`,
      ng:`그림자 안에 손을 넣었는데 가방이 아니라 손이 잡혔다. 선반 위에 누가 누워 있었다.<br><br>그 손이 이쪽 손을 그림자 안으로 당긴다.<br>억지로 빼냈다. 손등에 손톱자국이 네 줄 났다.`,
      win:{ exp:14, item:'말린 고기' }, lose:{ hp:-20, spirit:-14 } }
  ] },

{ at:'B3', t:'터널 — 빛 없는 서른',
  x:`열차가 터널로 들어간다. 객차 불이 깜빡이다 꺼진다. 서른을 세면 나간다고 했다.<br><br>
    빛이 없다. 그림자도 없다. 그림자술사는 그냥 사람이다.<br>
    어둠 속에서 무언가 통로를 걸어온다. 빛이 있을 때는 없던 발소리다.<br><br>
    셋. 넷. 다섯.`,
  o:[
    { l:'① 마력으로 손바닥 불씨를 켜 그림자를 세운다.', k:'fix', dc:21, cost:{ mana:24 },
      ok:`손바닥에 손톱만 한 불을 켰다. 객차 바닥에 일행 그림자가 짧게 섰다.<br><br>그림자를 모아 일행 위에 덮었다. 불은 손안에 감췄다.<br>발소리가 다가와 그림자 앞에서 멈췄다. 어둠보다 검은 덩어리를 본다. 빛 없는 데 사는 것은 더 검은 것을 피한다. 지나갔다.<br><br>스물아홉. 서른. 빛이 돌아왔다.`,
      ng:`불씨가 켜지자 발소리가 빨라졌다. 어둠 속의 것은 빛을 찾아온다.<br><br>불씨를 쥐어 껐다. 늦었다. 손목이 잡혔다. 차고 축축하다.<br>서른에 빛이 돌아왔을 때 손목에 손자국이 검게 남아 있었다. 손을 쥐었다 펴는 데 한참 걸렸다.`,
      win:{ exp:21, dream:3 }, lose:{ hp:-26, spirit:-16 } },
    { l:'② 그림자 없이 어둠에 몸을 맡기고 버틴다.', k:'steady', dc:21,
      doom:{ title:'빛 없는 서른', what:'터널 어둠 속으로 끌려갑니다', dc:17, sec:50,
        text:`움직이지 않았다. 어둠 속에선 그림자도 안 생긴다. 들킬 것도 없다고 여겼다.<br><br>발소리가 다가온다. 열하나, 열둘. 바로 앞에서 멈춘다.<br>그림자가 없으니 어디까지가 이쪽 몸인지 저쪽도 모르고 이쪽도 모른다. 저쪽 손이 이쪽 어깨를 찾는다. 찾았다.<br><br>스물. 객차 문이 열리는 소리. 바람이 들어온다. 어깨를 쥔 손이 문 쪽으로 당긴다.`,
        dieText:`서른에 객차 불이 돌아왔다.<br><br>자리마다 그림자가 선다.<br>빈 자리 하나에만 그림자가 남았다. 앉은 사람 없이.` },
      ok:`움직이지 않되 그림자를 버리지 않았다. 빛이 꺼지기 직전 제 그림자를 품에 접어 넣었다.<br><br>발소리가 앞에서 멈췄다. 손이 어깨를 찾는다. 그 손바닥 밑에 품에서 그림자를 펼쳤다. 빛 없는데 검게.<br>손이 그림자를 쥐었다. 그림자만. 이쪽은 옆으로 비켰다.<br><br>서른. 빛이 돌아왔다. 그림자는 끝이 조금 뜯긴 채 발로 돌아왔다.`,
      win:{ exp:24, dream:4 } }
  ] },

{ at:'B3', t:'특실 — 그림자는 얼굴을 안 바꾼다',
  x:`특실 복도 등 아래로 손님 하나가 지나간다. 얼굴은 점잖은 노신사다.<br><br>
    벽에 진 그림자를 봤다. 머리 모양이 다르다. 모자도 안 썼는데 머리가 길쭉하다. 어깨가 하나 높다.<br>
    얼굴은 바꿔 써도 그림자는 몸이 던지는 것이다. 몸은 못 바꾼다.<br><br>
    그것이 3호실 문을 연다.`,
  o:[
    { l:'① 그림자 윤곽을 끝까지 읽어 외운다.', k:'gaze', dc:21,
      ok:`문이 닫히기 전까지 그림자를 봤다. 길쭉한 머리, 높은 어깨, 무릎이 하나 더 있는 다리.<br><br>이제 얼굴을 몇 번 바꿔도 소용없다. 등 아래만 지나면 안다.<br>그 뒤로 이 열차에서 그림자를 먼저 봤다. 사람 얼굴은 나중에. 일행 그림자도 하나씩 외웠다. 바뀌면 알게.<br><br>얼굴 뒤의 몸을 그림자로 본다. 눈이 그 순서를 버릇으로 삼았다.`,
      ng:`그림자를 보는데 그림자가 고개를 돌렸다. 노신사의 고개는 안 돌았는데.<br><br>벽의 그림자가 이쪽 그림자를 본다. 이쪽 그림자 윤곽을 따라 손가락으로 훑는다. 외우는 것이다.<br>그 손가락이 지나간 데마다 몸이 서늘했다. 한참 떨었다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-18 }, wake:1 },
    { l:'② 마력으로 그것의 그림자를 복도 바닥에 꿰맨다.', k:'hide', dc:22, cost:{ mana:26 },
      ok:`문이 닫히기 직전 복도에 남은 그림자 끝을 손으로 눌렀다. 마력을 실로 박았다. 바닥에 꿰맸다.<br><br>문 안에서 그것이 멈췄다. 그림자가 문 밖에 걸렸다. 그림자가 안 따라가면 몸도 못 간다.<br>문틈으로 노신사 얼굴이 바닥에 떨어졌다. 벗어 던지고 빠져나가려는 것이다. 그래도 그림자는 남았다.<br><br>그 그림자를 꿰맨 채 두고 왔다. 그것은 이제 문 하나 너머로 못 간다. 한동안은.`,
      ng:`꿰매는 땀이 바닥에 안 박혔다. 열차가 흔들려 바늘이 빗나갔다.<br><br>그림자가 꿈틀하고 손을 거꾸로 감았다. 이쪽 손가락 그림자가 문틈으로 끌려 들어간다.<br>손을 빼냈다. 문이 닫히며 손가락 끝이 끼었다. 손톱이 들렸다.`,
      win:{ exp:23, dream:4 }, lose:{ hp:-28, spirit:-14 } }
  ] },

{ at:'B3', t:'기관실 앞 — 화실 불빛',
  x:`화실 문이 열린다. 붉은빛이 쏟아져 화부 그림자를 탄수차 위에 크게 던진다.<br><br>
    그림자가 사람 모양이 아니다. 팔이 넷이고 삽이 둘이다. 화부 몸은 팔 둘에 삽 하나인데.<br>
    그림자는 몸이 던지는 것이다. 몸이 거짓말을 하고 있다.<br><br>
    기관실 문은 화부 뒤에 있다.`,
  o:[
    { l:'① 마력으로 화부의 그림자를 붙들어 묶는다.', k:'steady', dc:22, cost:{ mana:25 },
      ok:`화실 문이 열린 순간, 그림자가 제일 클 때 손을 뻗었다. 넷인 팔 그림자를 둘씩 묶었다.<br><br>화부가 삽을 들려 한다. 안 들린다. 그림자 팔이 묶였다. 진짜 팔도 묶인 것처럼 멈춘다.<br>삽이 손에서 떨어졌다. 그 옆을 지나 기관실 문에 손을 댔다. 그림자를 놓아주는 건 문을 연 다음에 했다.`,
      ng:`팔 둘은 묶었다. 남은 둘이 이쪽 그림자를 잡았다.<br><br>그림자 손이 이쪽 그림자 목을 쥔다. 진짜 목이 조인다.<br>화실 문이 닫혀 빛이 꺼지고서야 풀렸다. 목에 손자국이 남았다. 그림자 손이 만든 자국이다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-30, mind:-14 } },
    { l:'② 일행 그림자를 화부 그림자 속에 숨겨 지난다.', k:'bond', dc:21,
      ok:`화부 그림자는 크다. 화실 문이 열릴 때마다 탄수차 위를 다 덮는다.<br><br>문이 열린 순간 일행을 하나씩 그 그림자 안으로 보냈다. 남의 그림자 안에서는 이쪽 그림자가 안 진다.<br>네 번 열리는 동안 다섯이 다 지났다. 화부는 끝까지 불만 봤다. 제 그림자 안을 보는 것은 없다.`,
      ng:`셋째를 보낼 때 화실 문이 일찍 닫혔다. 그림자가 꺼졌다.<br><br>석탄 위에 일행 하나가 덩그러니 드러났다. 화부가 돌아본다.<br>그 앞으로 몸을 던졌다. 삽 날이 팔뚝을 스쳤다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, spirit:-12 } },
    { l:'③ 화실 문이 닫힌 어둠에 섞여 기어간다.', k:'hide', dc:20,
      ok:`문이 닫히면 탄수차 위는 까맣다. 그때만 기었다.<br><br>열리면 엎드려 화부 그림자 가장자리에 몸을 붙였다. 남의 그림자 끝에 붙은 몸은 그림자의 일부로 보인다.<br>다섯 번째에 기관실 문 앞이었다.`,
      ng:`엎드린 자리가 그림자 가장자리가 아니라 밖이었다. 한 뼘.<br><br>붉은빛이 이쪽 등을 비췄다. 화부가 석탄 한 삽을 이쪽으로 던졌다.<br>뜨거운 석탄이 목덜미로 들어갔다. 굴러서 털었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-12 } }
  ] }
]);

// ── 첩자 (agent) · 자원 없음 ──
kJob('agent', 'B', [
{ at:'B', t:'접선 — 마른 외투',
  x:`약속한 자리에 사람이 서 있다. 모자를 눌러썼다. 암호를 묻는다.<br><br>
    <span style="color:#9fb4c8;">"오늘 비는 몇 시에 그칩니까."</span> 정해 둔 질문이다. 답도 정해져 있다.<br>
    첩자는 답보다 먼저 외투를 본다. 어깨가 말라 있다. 밖에 서 있던 사람 외투가 아니다.<br><br>
    안에서 기다리다 방금 나온 사람이다. 접선은 밖에서 하기로 했는데.`,
  o:[
    { l:'① 일부러 틀린 답을 댄다.', k:'hide', dc:21,
      ok:`<span style="color:#9fb4c8;">"내일 아침에요."</span> 틀린 답이다. 진짜 답은 「그치지 않습니다」.<br><br>진짜 연락책이라면 고쳐 줄 것이다. 아니면 돌아설 것이다.<br>남자는 고개를 끄덕였다. <span style="color:#9fb4c8;">"좋소. 따라오시오."</span> 답을 모르는 사람이다. 맞는지 틀린지도 모른다.<br><br>따라가지 않았다. 틀린 답 하나로 가짜를 갈랐다. 거짓말로 참을 시험하는 손이 한 번 더 늘었다.`,
      ng:`틀린 답을 댔다. 남자가 웃었다.<br><br><span style="color:#9fb4c8;">"틀린 답을 대는 사람이 진짜라고 들었소."</span> 저쪽도 이 수를 안다.<br>뒤에서 발소리가 다가온다. 골목 양쪽이다. 담을 넘어 빠졌다. 철조망에 팔이 길게 긁혔다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-24, spirit:-14 }, wake:1 },
    { l:'② 정해 둔 답을 그대로 댄다.', k:'bond', dc:21,
      doom:{ title:'마른 외투', what:'가짜 연락책에게 끌려갑니다', dc:17, sec:55,
        text:`<span style="color:#9fb4c8;">"그치지 않습니다."</span> 정해 둔 답이다.<br><br>남자가 고개를 끄덕인다. <span style="color:#9fb4c8;">"맞소. 그 답을 아는 사람은 이제 당신 하나요."</span><br>진짜 연락책은 이미 그 답을 털어놓았다는 뜻이다. 어디서, 누구에게.<br><br>남자 손이 팔꿈치를 잡는다. 정중하게. 문 안쪽으로 이끈다. 말라 있는 쪽으로.`,
        dieText:`약속한 자리에 사람이 서 있다. 모자를 눌러썼다. 외투 어깨가 말라 있다.<br><br>다음 사람에게 암호를 묻는다.<br>목소리가 이쪽 것이다.` },
      ok:`답을 대기 전에 남자 구두를 봤다. 젖었다. 그런데 밑창만 젖었다. 위는 말랐다.<br><br>문 안 바닥에서 막 걸어 나온 발이다. 답을 대는 대신 질문을 하나 더 했다. 연락책만 아는 것. 지난번 접선 때 이쪽이 떨어뜨린 물건.<br>남자가 대답을 못 했다. 그 틈에 골목으로 빠졌다. 정해 둔 답은 끝까지 아꼈다.`,
      win:{ exp:23, dream:3 } }
  ] },

{ at:'B', t:'빗속 — 꼬리 떼기',
  x:`뒤에 꼬리가 붙었다. 셋째 가로등부터.<br><br>
    빨리 걸으면 빨리 오고 서면 진열창을 본다. 배운 꼬리다.<br>
    첩자는 꼬리를 떼는 법을 여럿 안다. 대개는 꼬리가 모르는 사이에 꼬리 뒤로 가는 것이다.<br><br>
    앞에 처마 깊은 문간이 있다.`,
  o:[
    { l:'① 문간에서 외투를 뒤집어 입고 거꾸로 걸어 나간다.', k:'hide', dc:21,
      ok:`문간에 들어서자마자 외투를 벗어 뒤집었다. 안감은 회색이다. 모자를 벗어 품에 넣었다. 걸음을 바꿨다. 무릎을 조금 굽히고 왼발을 끌었다.<br><br>문간에서 나와 왔던 쪽으로 걸었다. 꼬리를 마주 보고.<br>꼬리가 문간 앞을 지나 이쪽을 지나쳤다. 검은 외투에 모자 쓴 사람을 찾으며.<br>이제 이쪽이 꼬리 뒤에 있다.`,
      ng:`외투를 뒤집는데 소매가 걸렸다. 한쪽 팔이 안 빠진다.<br><br>문간 앞에 꼬리가 멈췄다. 반쯤 뒤집힌 외투를 입은 이쪽을 본다.<br>둘 다 아무 말 없었다. 꼬리가 칼을 꺼냈다. 문간 안쪽 문을 어깨로 부수고 들어갔다. 어깨가 빠질 듯 아팠다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, mind:-12 } },
    { l:'② 웅덩이 앞에서 신발 끈을 매며 꼬리 수를 센다.', k:'sense', dc:20,
      ok:`웅덩이 앞에 쪼그려 신발 끈을 풀었다 맸다. 웅덩이에 뒤쪽이 거꾸로 비친다.<br><br>꼬리는 하나가 아니다. 길 건너 우산 하나, 처마 밑 담배 불씨 하나. 셋이 번갈아 붙는다.<br>하나만 떼면 나머지가 붙는다. 셋이 바뀌는 자리를 외웠다. 바뀔 때 생기는 틈이 있다. 거기로 빠졌다.`,
      ng:`끈을 매는데 웅덩이에 비친 꼬리가 바로 뒤에 서 있었다.<br><br>고개를 들기 전에 우산 끝이 목덜미에 닿았다. 차다.<br><span style="color:#9fb4c8;">"끈은 집에 가서 매시오."</span> 우산이 물러갔다. 다리가 한참 안 펴졌다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-16 } }
  ] },

{ at:'B', t:'주머니 — 제 글씨의 쪽지',
  x:`주머니에 접힌 쪽지가 있다. 넣은 기억이 없다.<br><br>
    펴 보니 이쪽 글씨다. 틀림없이. 『셋째로 말 거는 사람을 믿지 마.』<br>
    첩자는 제 글씨를 남보다 잘 안다. 남의 글씨를 흉내 낼 때 제 버릇부터 지우니까.<br><br>
    방금 말을 건 사람이 둘이다.`,
  o:[
    { l:'① 쪽지 글씨의 버릇을 하나하나 대 본다.', k:'gaze', dc:21,
      ok:`ㅁ을 쓸 때 이쪽은 오른쪽 아래를 안 닫는다. 쪽지 ㅁ은 닫혔다. 받침 ㄹ의 꼬리가 길다. 이쪽은 짧게 끊는다.<br><br>흉내 낸 글씨다. 아주 잘 흉내 냈다. 이쪽 글씨를 오래 본 사람이다.<br>셋째로 말 거는 사람을 믿지 말라는 건, 셋째가 진짜라는 뜻이다. 쪽지를 쓴 쪽이 둘째쯤에 있다.<br><br>제 글씨를 남의 글씨처럼 읽었다. 이쪽 버릇을 이쪽이 제일 잘 안다. 그게 무기가 됐다.`,
      ng:`버릇을 대 보는데 다 맞는다. ㅁ도 ㄹ도.<br><br>정말 이쪽 글씨다. 그런데 쓴 기억이 없다.<br>기억이 없는 동안 이쪽이 무엇을 했는지 모른다. 그 생각이 머리를 떠나지 않았다. 밤새 손바닥을 들여다봤다. 잉크가 묻어 있었다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-16 }, wake:1 },
    { l:'② 쪽지대로 셋째 사람을 피한다.', k:'steady', dc:20,
      ok:`셋째로 말을 건 사람에게 대답하지 않았다. 고개만 숙이고 지나갔다.<br><br>그 사람이 한참 뒤에서 이쪽을 봤다. 서운한 얼굴이다. 진짜 서운한 얼굴은 흉내 내기 어렵다.<br>쪽지가 거짓이었을 수도 있다. 그래도 살았다. 이 일은 살아서 나중에 따지는 일이다.`,
      ng:`셋째를 피했다. 넷째가 말을 걸었다. 쪽지에는 넷째 얘기가 없다.<br><br>넷째를 믿었다. 넷째가 이끈 문 뒤에 쫓는 것들이 있었다.<br>뛰었다. 문틀에 이마를 찧었다. 쪽지가 손에서 젖어 녹았다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, mind:-14 } },
    { l:'③ 쪽지 뒤에 이쪽 글씨로 다른 지시를 적어 흘린다.', k:'hide', dc:22,
      ok:`쪽지를 뒤집어 이쪽 글씨로 적었다. 『둘째에게 넘겨. 왼쪽 계단.』 왼쪽 계단은 막혀 있다.<br><br>쪽지를 복도 바닥에 떨어뜨렸다. 쓴 쪽이 주우러 올 것이다.<br>한참 뒤 누가 주워 갔다. 그리고 왼쪽 계단 쪽에서 무언가 막다른 데를 두드리는 소리가 오래 났다.`,
      ng:`쪽지를 떨어뜨렸다. 아무도 안 주워 간다.<br><br>대신 한참 뒤 같은 쪽지가 이쪽 주머니에 다시 들어 있었다. 뒷면 글씨 밑에 한 줄이 더 있다. 이쪽 글씨로. 『고마워.』<br>등골이 식었다. 그 밤 내내 주머니에 손을 넣지 못했다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-14, spirit:-18 } }
  ] },

{ at:'B', t:'쉬는 자리 — 이름 세기',
  x:`쉴 때 첩자는 이름을 센다. 이 일을 하며 쓴 이름들.<br><br>
    하나씩 짚는다. 어디서 썼는지, 누가 그 이름으로 불렀는지, 그 이름은 무엇을 좋아하는 척했는지.<br>
    이름이 많으면 하나쯤 잃어도 된다. 다만 몇 개인지는 알아야 한다.<br><br>
    오늘은 하나가 모자란다.`,
  o:[
    { l:'① 이름을 처음부터 다시 하나씩 짚는다.', k:'steady', dc:20,
      ok:`처음 쓴 이름부터 다시 셌다. 천천히. 이름마다 그 이름의 목소리로 한 번씩 속으로 말했다.<br><br>모자란 하나를 찾았다. 항구에서 쓴 이름이다. 그 이름을 쓰던 밤, 신발 한 짝을 잃었다. 그래서 같이 잊었다.<br>이름을 찾자 그 이름의 버릇도 돌아왔다. 왼발을 조금 끄는 걸음.<br><br>잊은 이름은 남이 줍는다. 찾아 둔 이름은 다시 쓸 수 있다. 이름들이 한 줄로 다시 섰다.`,
      ng:`세다가 이름 하나가 둘로 갈라졌다. 같은 이름, 다른 목소리.<br><br>하나는 이쪽이 쓰던 목소리다. 하나는 모르는 목소리다. 누가 그 이름을 쓰고 있다.<br>어느 쪽이 이쪽 것인지 한참 헷갈렸다. 일행이 이름을 부르는데 대답이 늦었다.`,
      win:{ exp:18, dream:2, mind:8 }, lose:{ mind:-16, spirit:-14 }, wake:1 },
    { l:'② 모자란 이름을 크게 불러 누가 대답하는지 본다.', k:'hide', dc:21,
      ok:`이름을 몰라도 된다. 모자란 자리에 맞는 이름 몇 개를 떠올렸다. 하나씩 복도 쪽에 대고 불렀다. 낮게.<br><br>셋째에 복도 끝에서 누가 대답했다. <span style="color:#9fb4c8;">"예."</span><br>그 이름이다. 누가 이쪽 이름 하나를 주워 쓰고 있다. 대답한 쪽은 대답한 걸 후회하는 발소리로 멀어졌다. 이제 그 이름은 그쪽에도 짐이다.`,
      ng:`셋째 이름을 불렀다. 대답이 바로 옆에서 났다.<br><br>일행 하나가 대답했다. 잠결에. 그 이름으로.<br>깨워서 물었다. 기억이 없다고 한다. 둘 다 그 밤 못 잤다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-14, spirit:-18 } }
  ] },

{ at:'B', t:'문 너머 — 엿듣기',
  x:`문 너머에서 말소리가 난다. 쫓는 쪽이다.<br><br>
    이쪽 일행 이름을 하나씩 부르며 무언가 적는다. 이름 뒤에 숫자를 붙인다.<br>
    첩자는 엿들은 것으로 산다. 다만 엿듣는 동안은 문 앞에 서 있어야 한다.<br><br>
    문 아래 틈으로 그림자가 오간다.`,
  o:[
    { l:'① 끝까지 엿듣고 숫자의 뜻을 맞힌다.', k:'sense', dc:21,
      ok:`이름 뒤 숫자는 시각이다. 그 이름을 데려갈 시각.<br><br>이쪽 이름 뒤에는 숫자가 없다. 대신 「보류」. 왜 보류인지도 들었다. <span style="color:#9fb4c8;">"그건 이름이 너무 많아서 어느 걸 지워야 할지 모르겠소."</span><br>일행 이름마다 시각을 외웠다. 제일 이른 것부터 그 시각 전에 자리를 옮기게 했다.`,
      ng:`엿듣는데 말소리가 멎었다. 문 너머에서 누가 말한다. <span style="color:#9fb4c8;">"문 앞에 있는 사람. 이름이 뭐요."</span><br><br>대답할 이름이 너무 많아 하나를 고르지 못했다.<br>그 사이 문이 열렸다. 손이 멱살을 잡았다. 뿌리치고 뛰었다. 목에 손톱자국이 났다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-22, spirit:-16 } },
    { l:'② 저쪽 목소리를 흉내 내 끼어든다.', k:'hide', dc:22,
      ok:`문 너머 목소리 중 제일 낮은 것을 골랐다. 몇 마디 들으며 숨 쉬는 자리를 맞췄다.<br><br>그 목소리로 문에 대고 말했다. <span style="color:#9fb4c8;">"명단 바뀌었소. 다 아래층이오."</span><br>문 너머가 잠깐 조용했다. 그리고 의자 끄는 소리. 여럿이 아래층으로 내려간다. 낮은 목소리의 주인도 같이 내려간다. 제 목소리를 듣고도.`,
      ng:`흉내 낸 목소리가 문 너머 그 목소리와 동시에 나왔다. 같은 말을 하려던 참이었다.<br><br>목소리 둘이 겹쳤다. 조용해졌다.<br><span style="color:#9fb4c8;">"둘 중 하나는 가짜요."</span> 문이 벌컥 열렸다. 문짝에 얼굴을 맞고 넘어졌다. 코피가 한참 안 멎었다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, mind:-14 } }
  ] },

{ at:'B', t:'거래 — 하나만 넘기면',
  x:`쫓는 쪽에서 사람이 하나 나와 거래를 걸어온다. 빈손을 보이며.<br><br>
    <span style="color:#9fb4c8;">"하나만 넘기시오. 나머지는 나가게 해 주지."</span><br>
    첩자는 거래를 안다. 처음 부른 값은 진짜 값이 아니다. 진짜 값은 거래가 깨질 때 나온다.<br><br>
    저쪽은 누구를 원하는지 말하지 않았다.`,
  o:[
    { l:'① 받아들이는 척하며 누구를 원하는지 캐낸다.', k:'hide', dc:21,
      doom:{ title:'이미 끝난 거래', what:'거래의 값으로 끌려갑니다', dc:17, sec:55,
        text:`<span style="color:#9fb4c8;">"누구를 원하시오. 값을 들어 봐야지."</span> 받아들이는 척했다.<br><br>남자가 웃는다. <span style="color:#9fb4c8;">"원하는 사람은 벌써 앞에 와 있소. 거래를 하자고 나서는 사람. 늘 그쪽이오."</span><br>처음부터 거래를 걸어올 사람을 산 것이다. 거래에 나선 쪽을.<br><br>남자 등 뒤에서 둘이 나온다. 정중하게 양팔을 잡는다.`,
        dieText:`쫓는 쪽에서 사람이 하나 나와 거래를 걸어온다. 빈손을 보이며.<br><br>그 등 뒤에 하나가 더 서 있다.<br>그쪽 손은 장부를 들었다. 이쪽 이름이 맨 위에 지워져 있다.` },
      ok:`캐묻기 전에 남자 손을 봤다. 빈손을 너무 오래 보인다. 보여 줄 것이 그것뿐인 사람이다.<br><br>그래서 값을 묻지 않고 반대로 물었다. <span style="color:#9fb4c8;">"이미 누가 넘어갔소?"</span> 남자 눈이 이쪽 어깨 너머 일행 쪽이 아니라 이쪽 얼굴에서 멈췄다.<br>원하는 건 거래에 나서는 사람이다. 알았으니 나서지 않으면 된다. 일행을 데리고 뒷걸음으로 물러났다. 남자는 쫓아오지 않았다. 거래가 깨졌으니까.`,
      win:{ exp:23, dream:3 } },
    { l:'② 거절하고 판을 엎는다.', k:'steady', dc:20,
      ok:`<span style="color:#9fb4c8;">"아무도 안 넘기오."</span><br><br>남자가 어깨를 으쓱한다. 진짜 값이 나왔다. <span style="color:#9fb4c8;">"그럼 다섯 다 가져가지. 다섯 시에."</span><br>시각을 흘렸다. 거래가 깨질 때 진짜가 나온다. 다섯 시 전에 나가면 된다.`,
      ng:`거절했다. 남자가 아무 말 없이 돌아섰다.<br><br>진짜 값을 끝내 안 말했다. 판이 엎어진 게 아니라 이쪽만 판 밖으로 밀려난 것이다.<br>그 밤 내내 언제 올지 모르는 걸 기다렸다. 아무것도 안 왔다. 그게 더 길었다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-14 } }
  ] },

{ at:'B', t:'서류 — 통행증',
  x:`잠긴 문 옆에 창구가 있다. 통행증을 보이면 열어 준다.<br><br>
    창구 유리에 견본이 붙어 있다. 종이 색, 도장 위치, 서명 하나.<br>
    첩자는 서류를 만든다. 진짜보다 진짜 같은 것.<br><br>
    가진 건 젖은 종이 몇 장, 볼펜 하나, 감자 한 알.`,
  o:[
    { l:'① 감자를 깎아 도장을 새기고 통행증을 만든다.', k:'fix', dc:21,
      ok:`감자를 반으로 갈라 단면에 견본 도장을 거꾸로 새겼다. 볼펜 잉크를 문질러 찍었다.<br><br>종이는 말려서 다렸다. 견본보다 조금 누렇다. 그래서 모서리를 손때로 문질러 오래 쓴 것처럼 만들었다. 진짜는 늘 조금 낡았다.<br>창구에 내밀었다. 창구 안 손이 종이를 오래 만졌다. 문이 열렸다.<br><br>없는 것으로 있는 걸 만들었다. 손이 서류 한 장을 끝까지 꾸미는 법을 알았다.`,
      ng:`도장이 번졌다. 감자가 너무 물렀다.<br><br>창구 안 손이 종이를 받아 불빛에 비춰 본다. 한참. 종이를 창구 안으로 거둬들였다. 돌려주지 않는다.<br>대신 창구 아래 문이 열렸다. 안쪽에서. 손이 나와 발목을 잡았다. 걷어차고 빠지는 데 발목이 삐었다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-24, spirit:-14 }, wake:1 },
    { l:'② 버려진 통행증을 주워 이름만 고친다.', k:'luck', dc:20,
      ok:`창구 아래 쓰레기통에 구겨진 통행증이 있다. 먼저 나간 누군가 버렸다.<br><br>이름 칸만 침으로 문질러 지우고 고쳐 썼다. 나머지는 진짜다.<br>창구 안 손이 도장을 손가락으로 쓸어 보고 고개를 끄덕였다. 문이 열렸다.`,
      ng:`주운 통행증의 날짜가 내일이었다.<br><br>창구 안 손이 날짜를 짚었다. 그리고 이쪽을 가리켰다. 내일 올 사람이 오늘 왔다는 뜻이다.<br>창구 옆 문이 열리며 흰 손들이 나왔다. 뛰었다. 등에 무언가 맞았다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, mind:-14 } }
  ] },

{ at:'B', t:'끝 — 남의 걸음으로',
  x:`나가는 문 앞에 쫓는 것들이 모여 있다. 여럿이다.<br><br>
    다 같은 옷, 같은 걸음, 같은 높이로 고개를 돌린다. 서로를 센다. 다 셌으면 문을 지킨다.<br>
    첩자는 생각한다. 저 걸음 하나만 배우면 저 숫자 안에 든다.<br><br>
    숫자 안에 들면 아무도 안 센다.`,
  o:[
    { l:'① 그것들의 걸음을 익혀 숫자 안에 섞인다.', k:'hide', dc:22,
      ok:`오래 봤다. 걸음은 두 박자, 고개는 세 박자. 돌릴 때 어깨가 먼저 간다.<br><br>그 박자로 걸어 들어갔다. 서로를 셀 때 이쪽도 셌다. 고개를 돌려 옆을 보고 고개를 끄덕였다. 이쪽도 세어졌다.<br>문 앞에 섰을 때 옆의 것이 문을 열어 주었다. 순번이 된 것이다.<br><br>일행을 하나씩 같은 박자로 불러들였다. 숫자는 늘 맞았다. 남의 무리 안에서 남의 숫자를 움직였다. 얼굴 하나 안 바꾸고.`,
      ng:`고개를 반 박자 빨리 돌렸다.<br><br>그것들이 한꺼번에 멈췄다. 숫자가 하나 많다. 다 같이 이쪽을 센다.<br>문 대신 벽 쪽으로 밀려났다. 사방에서 손이 뻗어 왔다. 겨우 빠져나왔을 때 외투가 다 찢겨 있었다.`,
      win:{ exp:25, dream:4 }, lose:{ hp:-32, spirit:-14 }, wake:1 },
    { l:'② 반대쪽에 미끼 소리를 던져 끌어낸다.', k:'luck', dc:21,
      ok:`주머니에 남은 동전을 반대편 복도 끝으로 굴렸다. 멀리서 쨍 소리가 난다.<br><br>그것들이 같은 박자로 돌아섰다. 소리 쪽으로. 운 좋게 다 따라갔다.<br>문 앞이 비었다. 다섯이 빠졌다.`,
      ng:`동전이 반대편이 아니라 그것들 발치에서 멈췄다.<br><br>그것들이 동전을 내려다본다. 그리고 동전이 굴러온 쪽을.<br>뛰었다. 등에 무언가 스쳤다. 갈비 사이가 길게 아렸다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, mind:-12 } },
    { l:'③ 그려 둔 길로 크게 돌아간다.', k:'sense', dc:20,
      ok:`손바닥에 그려 둔 지도를 폈다. 들어오면서 그린 것이다. 문은 하나가 아니다. 짐 나르는 문이 하나 더 있다.<br><br>멀다. 멀지만 그것들은 없다.<br>오래 걸어서 그쪽 문으로 나갔다.`,
      ng:`지도가 손땀에 번졌다. 짐 문 위치가 흐려졌다.<br><br>돌아가다 막다른 데를 두 번 만났다.<br>시간이 줄었다. 마지막엔 뛰었다. 다리가 다 풀렸다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, mind:-14 } }
  ] },

{ at:'B1', t:'경매장 — 노란 비옷과 번호표',
  x:`경매장 입구 고리에 노란 비옷이 여러 벌 걸렸다. 옆 상자에 번호표가 쌓였다.<br><br>
    노란 비옷들은 서로를 번호로 부른다. 얼굴은 모자 그늘에 있다.<br>
    첩자에게 이런 데는 문이 열려 있는 것과 같다. 옷 한 벌, 번호 하나면 된다.<br><br>
    경매판에 『다섯』이라고 적힌 물건이 올라갈 차례다.`,
  o:[
    { l:'① 노란 비옷을 입고 번호표를 달아 섞인다.', k:'hide', dc:21,
      doom:{ title:'일꾼 번호', what:'적재 일꾼으로 세어져 끌려갑니다', dc:17, sec:55,
        text:`비옷을 입고 번호표를 달았다. 31번. 노란 비옷들 사이에 섰다.<br><br>아무도 이쪽을 안 본다. 됐다. 그런데 경매사가 번호를 부른다. 28, 29, 30, 31.<br>불린 번호들이 판 앞으로 나간다. 팔린 물건을 나르는 순번이다. 해무호로.<br><br>이쪽도 떠밀려 나갔다. 비옷들 사이에 끼어 빠질 데가 없다. 판 위의 『다섯』 자루 하나가 이쪽 어깨에 얹힌다. 무겁다. 움직인다.`,
        dieText:`해무호 갑판에 노란 비옷들이 자루를 내려놓는다.<br><br>자루가 다섯. 비옷이 서른하나.<br>배가 떠난 뒤 다시 세면 비옷이 서른이다.` },
      ok:`비옷을 입기 전에 번호표 상자를 뒤졌다. 번호마다 뒷면에 연필 표시가 있다. 순번이다. 날짜도.<br><br>오늘 순번이 안 걸린 번호를 골랐다. 9번. 어제 쓴 번호다.<br>경매사가 번호를 불러 판 앞으로 일꾼들을 보낼 때, 9번은 안 불렸다. 노란 비옷들 사이를 지나 하역장 쪽 문까지 아무도 이쪽을 안 봤다.`,
      win:{ exp:23, dream:3 } },
    { l:'② 번호표를 들고 『다섯』에 값을 불러 본다.', k:'bond', dc:21,
      ok:`번호표를 들고 낮게 값을 불렀다. 경매사가 이쪽 번호를 받는다.<br><br>값이 오른다. 다른 번호가 따라온다. 그 번호를 쥔 쪽을 봤다. 검은 우산 아래 손이다. 처음에 일을 준 남자.<br>『다섯』을 판 쪽도 산 쪽도 같은 사람이다. 값을 올리는 건 장부에 남기기 위해서다.<br><br>값을 부르다 그만뒀다. 어디서 손을 떼야 하는지 아는 것까지가 거래다. 판을 사지 않고 판을 읽게 됐다.`,
      ng:`값을 불렀다. 아무도 안 따라왔다.<br><br>경매사가 망치를 쳤다. 『다섯』이 이쪽 번호에 낙찰됐다.<br>노란 비옷들이 이쪽을 둘러싼다. 산 사람은 물건을 받아 가야 한다. 판 위의 자루가 움직였다. 자루 하나에 손목이 묶였다. 끊는 데 손목이 다 쓸렸다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-24, spirit:-16 }, wake:1 }
  ] },

{ at:'B1', t:'2층 사무실 — 장부의 다섯째 줄',
  x:`경매장 2층 사무실 책상에 장부가 펼쳐져 있다. 오늘 날짜.<br><br>
    줄마다 물건 이름과 무게, 적재 시각. 『05:10 해무호』.<br>
    다섯째 줄에 『3번 창고 인원 다섯』. 옆 칸 『적재』가 비어 있다.<br><br>
    장부를 믿는 곳에서는 장부가 사람을 정한다.`,
  o:[
    { l:'① 다섯째 줄 적재 칸에 「완료」를 적어 넣는다.', k:'fix', dc:21,
      ok:`위 줄들의 「완료」를 봤다. 같은 볼펜, 같은 기울기, 끝을 살짝 올리는 버릇.<br><br>세 번 연습하고 네 번째에 적었다. 다섯째 줄 『적재 — 완료』. 잉크가 마르는 걸 기다렸다가 장부를 처음 펼쳐진 쪽으로 돌려 놓았다.<br>얼마 뒤 계단을 올라온 누가 장부를 넘기고 고개를 끄덕였다. 다섯째 줄을 손가락으로 지우듯 쓸었다. 끝난 일이다.<br><br>장부 한 줄로 쫓는 손을 거뒀다. 서류가 칼보다 멀리 간다는 걸 손이 알았다.`,
      ng:`「완료」의 끝을 올리지 않았다. 버릇을 하나 놓쳤다.<br><br>장부를 넘기던 손이 그 줄에서 멈췄다. 글씨를 오래 본다. 그리고 다섯째 줄 옆에 볼펜으로 동그라미를 쳤다. 다시 볼 일이다.<br>쫓는 것들이 두 배가 됐다. 계단을 뛰어 내려가다 발목을 접질렸다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-24, spirit:-14 }, wake:1 },
    { l:'② 장부를 읽기만 하고 시각을 외운다.', k:'gaze', dc:20,
      ok:`줄마다 적재 시각이 다르다. 청소부 일은 04:30까지. 정문 사슬은 05:00에 풀린다. 그다음 05:10.<br><br>그 사이 십 분. 정문이 풀리고 배가 오기 전. 사람들이 다 부두로 몰리는 십 분.<br>외웠다. 장부는 손대지 않았다. 손댄 장부는 누가 다시 본다.`,
      ng:`읽는 사이 책상 밑에서 무언가 이쪽 발을 쥐었다. 장부를 지키는 것이다.<br><br>장부를 덮고 발을 뺐다. 발목에 손톱이 박혔다.<br>시각은 반만 외웠다. 나머지 반은 피와 같이 흘렸다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, mind:-14 } }
  ] },

{ at:'B1', t:'야적장 — 무전',
  x:`컨테이너 그늘에 무전기 하나가 떨어져 있다. 지직거린다.<br><br>
    <span style="color:#9fb4c8;">"7구역 이상 없음. 다음 8구역."</span> 탐조등 탑의 목소리다. 졸린 목소리.<br>
    첩자는 목소리를 듣고 따라 한다. 이 일의 절반이 그거다.<br><br>
    8구역이 이쪽이 숨은 데다.`,
  o:[
    { l:'① 탑의 목소리를 흉내 내 무전을 친다.', k:'hide', dc:21,
      ok:`몇 번 더 들었다. 숨을 끝에 길게 끈다. 「이상」을 「이쌍」에 가깝게 한다.<br><br>단추를 눌렀다. <span style="color:#9fb4c8;">"8구역 건너뜀. 9구역부터."</span> 탑의 목소리로.<br>무전기 너머가 잠깐 조용했다. <span style="color:#9fb4c8;">"알았다."</span> 다른 목소리가 대답했다. 손전등들이 8구역을 비켜 갔다.<br><br>탑 위의 진짜 목소리는 아무 말 안 했다. 졸고 있었다.`,
      ng:`단추를 누르는 순간 탑에서도 무전이 왔다. 같은 목소리 둘이 동시에 나갔다.<br><br>무전기 너머가 조용해졌다. 그리고 손전등이 일제히 이쪽 무전기 쪽으로 돈다.<br>무전기를 던지고 뛰었다. 컨테이너 모서리에 옆구리를 찧었다.`,
      win:{ exp:21, dream:3 }, lose:{ hp:-26, mind:-12 } },
    { l:'② 무전만 엿들으며 순서를 받아 적는다.', k:'sense', dc:20,
      ok:`무전을 귀에 대고 손바닥에 적었다. 구역 이름, 시각, 누가 어디로.<br><br>순서가 정해져 있다. 1부터 12까지, 한 바퀴에 십오 분. 8구역 다음 9구역 갈 때 3구역이 빈다.<br>그 빈 때를 기다렸다가 건넜다.`,
      ng:`엿듣는데 무전기 너머 목소리가 말했다. <span style="color:#9fb4c8;">"무전기 하나 분실. 주운 사람 그 자리에 있을 것."</span><br><br>손전등들이 무전기를 찾아 모여든다. 무전기를 컨테이너 틈에 밀어 넣고 기었다.<br>철판 모서리에 손바닥이 길게 갈렸다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, mind:-14 } }
  ] },

{ at:'B1', t:'방파제 — 우산의 쪽지',
  x:`방파제 끝 우산이 쪽지를 건넨다. <span style="color:#9fb4c8;">"배 번호요. 놓치지 마시오."</span><br><br>
    쪽지는 사무실에서 본 장부와 같은 종이다. 같은 줄 간격, 같은 볼펜.<br>
    청소부 작업표도 같은 종이였다.<br><br>
    첩자는 종이를 믿는다. 종이는 누가 썼는지 숨기지 못한다.`,
  o:[
    { l:'① 종이의 접힌 자국과 볼펜 눌림을 읽는다.', k:'gaze', dc:21,
      ok:`쪽지를 불빛에 비췄다. 앞에 쓴 글씨 말고 눌린 자국이 하나 더 있다. 위 장에 쓰다 눌린 것이다.<br><br>엄지로 비스듬히 문질러 보니 글자가 떠오른다. 『3번 창고 다섯 — 미결 시 우산 처리.』<br>일을 준 사람이 일이 안 끝나면 끝을 맡는다. 우산도 같은 장부에 있다.<br><br>쪽지 뒷면에 눌린 한 줄로 판 전체를 봤다. 종이를 읽는 눈이 한 장 더 깊어졌다.`,
      ng:`불빛에 비추는데 우산이 손을 뻗어 쪽지를 덮었다.<br><br><span style="color:#9fb4c8;">"종이를 그렇게 보는 사람은 오래 못 가오."</span><br>우산 끝이 이쪽 손등을 눌렀다. 뼈가 울렸다. 쪽지는 우산이 도로 가져갔다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-22, spirit:-16 }, wake:1 },
    { l:'② 쪽지를 같은 종이로 바꿔치기해 돌려준다.', k:'hide', dc:21,
      ok:`사무실에서 챙긴 빈 장부 종이가 있다. 같은 줄 간격.<br><br>쪽지를 받는 척 손바닥 안에서 바꿨다. 빈 종이에 아무 번호나 적어 우산에게 돌려주었다. <span style="color:#9fb4c8;">"번호가 지워졌소."</span><br>우산이 새 쪽지를 받아 들고 고개를 갸웃했다. 진짜 쪽지는 이쪽 품에 있다. 진짜 번호와 함께.`,
      ng:`바꿔치기하는데 빈 종이가 비에 젖어 손바닥에 붙었다.<br><br>두 장이 같이 손에서 미끄러져 나왔다. 우산이 둘을 같이 봤다.<br>우산이 아무 말 없이 우산을 접었다. 처음으로. 그 아래 얼굴을 보기 전에 뛰었다. 방파제 돌에 무릎이 깨졌다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, mind:-14 } }
  ] },

{ at:'B2', t:'정각 점검 — 다른 이름으로',
  x:`정각이다. 간호사가 명패 이름을 하나씩 부른다.<br><br>
    일행 하나가 아직 안 돌아왔다. 그 이름이 불리면 대답이 없을 것이다. 대답이 없으면 찾으러 간다.<br>
    첩자는 이름을 바꿔 대답하는 데 익숙하다.<br><br>
    다만 한 사람이 두 번 대답하면 계수기가 두 번 눌린다.`,
  o:[
    { l:'① 이쪽 이름엔 일행 목소리로, 빈 이름엔 이쪽 목소리로 대답한다.', k:'hide', dc:22,
      ok:`먼저 이쪽 명패 이름이 불렸다. 옆 침대 일행에게 눈짓했다. 일행이 대답했다. 이쪽 대신.<br><br>빈 침대 이름이 불렸다. 이쪽이 대답했다. 빈 침대 쪽으로 고개를 돌려, 목소리를 조금 낮게. 소리가 그쪽에서 난 것처럼.<br>딸깍, 딸깍. 숫자가 맞았다. 대답한 입은 하나씩이고 이름도 하나씩이다. 자리만 바뀌었을 뿐.<br><br>한 입으로 두 사람이 되는 건 쉽다. 두 입으로 한 사람을 지키는 건 처음이다. 이름 다루는 손이 넓어졌다.`,
      ng:`빈 침대 이름에 대답했다. 목소리가 이쪽 침대에서 났다. 돌리는 걸 잊었다.<br><br>간호사가 이쪽 침대를 본다. 계수기를 두 번 누른다.<br>다음 정각까지 이쪽은 두 사람이다. 하나는 찾으러 올 것이다. 밤새 커튼 그림자가 두 번 다가왔다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-16, spirit:-18 }, wake:1 },
    { l:'② 명패를 바꿔 달아 빈 침대를 다른 침대로 만든다.', k:'fix', dc:20,
      ok:`정각 직전에 빈 침대 명패와 퇴원한 침대 명패를 바꿨다. 퇴원한 침대는 명패가 비스듬히 뒤집혀 있었다.<br><br>간호사가 빈 침대 앞에서 명패를 본다. 퇴원 이름이다. 지나간다.<br>안 돌아온 일행의 이름은 이제 퇴원한 침대에 있다. 퇴원한 사람은 안 센다.`,
      ng:`바꿔 단 명패 고리가 하나 빠졌다. 명패가 기울어 흔들린다.<br><br>간호사가 손으로 명패를 바로잡는다. 뒤집어 본다. 뒷면에 원래 침대 번호가 적혀 있다.<br>계수기 대신 수첩을 꺼냈다. 무언가 적는다. 그 밤 내내 복도 발소리가 이쪽 문 앞에서만 멈췄다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-14 } },
    { l:'③ 대답하지 않고 간호사 수첩을 훔쳐본다.', k:'gaze', dc:21,
      ok:`대답은 일행에게 맡기고 간호사 손을 봤다. 계수기를 쥔 손 말고 다른 손.<br><br>수첩에 숫자가 적혀 있다. 정각마다. 그런데 2시와 4시 칸만 비어 있다. 그 시각에는 안 센다.<br>그 두 시각을 일행에게 손가락으로 알렸다.`,
      ng:`수첩을 보는 눈을 간호사가 봤다. 마스크 위 눈이 웃는 모양이다.<br><br>간호사가 수첩을 펼쳐 이쪽에게 보여 준다. 맨 아래 칸에 이쪽 명패 이름. 옆에 시각. 다음 정각.<br>그 숫자가 머리에서 안 떠나 숨이 가빠졌다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-14 } }
  ] },

{ at:'B2', t:'간호사실 — 근무표',
  x:`간호사실 벽에 근무표가 붙어 있다. 칸마다 이름 대신 번호. 시간마다 누가 어디 서는지.<br><br>
    비상계단 앞 칸에 『7』. 오늘 밤 내내 7이다.<br>
    근무표를 믿는 데서는 근무표를 고치면 사람이 움직인다.<br><br>
    간호사실 의자에 지금 아무도 없다. 의자가 아직 따뜻하다.`,
  o:[
    { l:'① 비상계단 칸에 교대를 적어 넣는다.', k:'fix', dc:21,
      ok:`근무표의 다른 칸 교대 표시를 봤다. 빨간 볼펜, 사선 하나, 그 옆에 번호.<br><br>책상의 빨간 볼펜으로 비상계단 칸에 사선을 긋고 『12』라고 적었다. 12는 오늘 밤 칸이 하나도 없는 번호다.<br>정각에 7이 비상계단을 떠났다. 12는 오지 않았다. 없는 사람을 기다리는 칸이 됐다. 그 사이 계단을 내려갔다.`,
      ng:`사선을 긋는데 볼펜이 빨강이 아니라 분홍이었다. 비슷하다. 비슷하면 눈에 띈다.<br><br>돌아온 간호사가 근무표 앞에 섰다. 분홍 사선을 손가락으로 짚는다.<br>그리고 비상계단 칸 7 옆에 7을 하나 더 적었다. 둘이 서게 됐다. 계단을 다른 길로 돌아 한참 헤맸다. 발이 다 부르텄다.`,
      win:{ exp:21, dream:3 }, lose:{ hp:-22, mind:-14 } },
    { l:'② 근무표를 읽어 비는 자리를 찾는다.', k:'gaze', dc:20,
      ok:`칸을 따라 시간을 짚었다. 3시 15분에 7이 세탁실 칸으로 옮긴다. 십 분 동안 비상계단이 빈다.<br><br>근무표는 손대지 않았다. 손대지 않은 근무표는 아무도 다시 안 본다.<br>3시 15분까지 기다렸다. 칸에 적힌 대로 7이 떠났다.`,
      ng:`읽는 사이 의자가 삐걱했다. 아무도 없는데.<br><br>의자가 천천히 이쪽으로 돈다. 앉은 사람 없이.<br>뒷걸음으로 나왔다. 문을 닫는 손이 떨려 손가락을 문틈에 찧었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-20, spirit:-16 } }
  ] },

{ at:'B2', t:'탈의실 — 직원 가운',
  x:`직원 탈의실 옷걸이에 흰 가운이 줄지어 걸렸다. 가슴에 번호 명찰.<br><br>
    가운 한 벌이면 복도를 걸어도 아무도 안 센다. 직원은 세지 않는다.<br>
    다만 여기 직원은 직원이 아니다.<br><br>
    가운 하나에 『19』. 옷걸이 위 이름표 칸이 비었다.`,
  o:[
    { l:'① 19번 가운을 입고 직원처럼 걷는다.', k:'hide', dc:21,
      doom:{ title:'19번', what:'직원으로 세어져 끌려갑니다', dc:17, sec:55,
        text:`가운을 입었다. 몸에 맞는다. 너무 잘 맞는다.<br><br>복도에 나서자 흰 옷들이 고개를 끄덕인다. 19. 19. 다들 이쪽 번호를 안다.<br>간호사실 앞에서 누가 계수기를 쥐여 준다. 다음 정각은 19 차례다.<br><br>손이 계수기를 쥐었다. 엄지가 저절로 움직인다. 딸깍. 걸음이 복도를 돈다. 이쪽 걸음이 아니다.`,
        dieText:`정각이다. 간호사가 병실을 돈다. 딸깍.<br><br>가슴 명찰에 『19』.<br>마스크 위 눈이 어디서 본 눈이다.` },
      ok:`입기 전에 가운 안쪽 깃을 봤다. 바느질 자국에 이름 한 줄이 실로 박혀 있다. 지워지다 만 이름.<br><br>19는 원래 사람이었다. 가운을 입고 직원이 된 사람. 이 가운은 사람을 직원으로 만든다.<br>입지 않았다. 대신 팔에 걸쳤다. 세탁물 나르는 사람처럼. 가운을 든 사람은 아무도 세지 않는다. 직원도 환자도 아니니까.`,
      win:{ exp:24, dream:4 } },
    { l:'② 가운 주머니만 뒤진다.', k:'luck', dc:20,
      ok:`가운마다 주머니를 손끝으로 훑었다. 볼펜, 고무줄, 껌 종이.<br><br>한 주머니에 기름종이 꾸러미가 있다. 말린 고기다. 야근 군것질이다.<br>꾸러미를 꺼내고 주머니를 원래 모양으로 펴 놓았다.`,
      ng:`주머니에 손을 넣었는데 안에서 손이 잡혔다. 가운 안에 누가 있다.<br><br>걸린 가운이 천천히 옷걸이에서 내려온다. 발 없이.<br>손을 빼고 탈의실을 나왔다. 손목에 손가락 자국이 남았다.`,
      win:{ exp:14, item:'말린 고기' }, lose:{ hp:-22, spirit:-14 } }
  ] },

{ at:'B2', t:'원무과 — 퇴원 서류',
  x:`원무과 창구에 퇴원 서류 묶음이 있다. 담당의 서명 칸이 비었다.<br><br>
    서명만 있으면 정문 당직이 문을 열어 준다고, 창구 벽에 적혀 있다.<br>
    서명 견본이 벽에 붙은 다른 서류에 있다. 길게 흘린 서명이다. 끝이 위로 올라간다.<br><br>
    첩자는 남의 손으로 쓴다. 이 일의 오래된 기술이다.`,
  o:[
    { l:'① 서명을 흉내 내 다섯 장을 채운다.', k:'fix', dc:22,
      ok:`견본을 오래 봤다. 시작은 천천히, 가운데서 빨라지고, 끝에서 펜을 들며 올린다. 펜이 종이에서 떨어지는 순간까지가 서명이다.<br><br>빈 종이에 열 번 썼다. 열한 번째부터 서류에 썼다. 다섯 장. 다섯 장이 다 조금씩 달랐다. 진짜 서명도 매번 조금씩 다르다.<br>창구 안 손이 서류를 넘겨 보고 도장을 찍었다.`,
      ng:`다섯 장이 너무 똑같았다. 같은 사람이 같은 서명을 다섯 번 하면 다섯 번 다르다.<br><br>창구 안 손이 다섯 장을 겹쳐 불빛에 비춘다. 서명이 하나로 포개진다.<br>도장 대신 번호표가 나왔다. 입원 수속 번호. 창구 옆 문으로 흰 손이 나왔다. 뛰었다. 정강이가 의자에 깨졌다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, mind:-14 } },
    { l:'② 이미 서명된 남의 서류를 이름만 바꿔치기한다.', k:'hide', dc:21,
      ok:`서류 묶음 아래쪽에 서명이 끝난 것이 몇 장 있다. 이름 칸이 연필이다. 누가 나중에 채우려고.<br><br>연필 이름을 지우개 대신 침 묻힌 손톱으로 긁어냈다. 일행 이름을 적었다. 볼펜으로 덧쓰지 않고 연필로. 원래대로.<br>창구에 냈다. 도장이 찍혔다. 원래 그 서류의 주인은 아마 나갈 일이 없었을 것이다.`,
      ng:`연필 이름을 긁는데 아래에 또 이름이 있다. 그 아래 또.<br><br>여러 번 지우고 다시 쓴 서류다. 이름이 겹겹이 겹쳐 있다. 다 나가지 못한 이름들.<br>그걸 들여다보다 손이 떨렸다. 창구 안 손이 서류를 거둬 갔다. 그 밤 내내 그 이름들이 눈에 걸렸다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-16, spirit:-16 } }
  ] },

{ at:'B3', t:'검표 — 행선지 빈 표',
  x:`검표원이 온다. 표마다 행선지 칸이 비었다. 이쪽 표도.<br><br>
    옆자리 손님 표만 행선지가 찍혀 있다. 『저녁재 하차』.<br>
    검표원은 행선지 빈 표에 구멍을 하나 더 뚫는다. 그 구멍이 무슨 뜻인지는 아무도 모른다. 구멍이 둘인 손님은 다음 칸에서 안 보였다.<br><br>
    옆자리 손님이 졸고 있다. 표가 무릎 위에 놓였다.`,
  o:[
    { l:'① 무릎 위 표를 이쪽 표와 바꿔치기한다.', k:'hide', dc:21,
      ok:`열차가 이음매를 넘을 때 손등으로 무릎 위 표를 밀었다. 이쪽 표를 그 자리에 떨어뜨렸다. 한 번에.<br><br>검표원이 옆자리 표를 집는다. 행선지가 비었다. 구멍을 하나 더 뚫는다. 손님은 졸고 있다.<br>이쪽 표를 본다. 『저녁재 하차』. 고개를 끄덕이고 지나간다.<br><br>손이 한 번에 두 장을 바꿨다. 남의 운명 한 장을 이쪽 것으로. 그 무게를 오래 생각하지 않는 것도 이 일이다.`,
      ng:`표를 미는데 졸던 손님 손이 표를 덮었다. 깨어 있었다.<br><br>손님이 이쪽 표를 쥔다. 이쪽 손도. <span style="color:#9fb4c8;">"남의 표는 남의 길이오."</span><br>검표원이 둘의 표에 구멍을 하나씩 더 뚫었다. 손목이 집게에 집혀 피가 났다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-24, spirit:-16 }, wake:1 },
    { l:'② 검표원에게 말을 걸어 표를 보이지 않고 넘긴다.', k:'bond', dc:21,
      ok:`검표원이 오기 전에 먼저 일어나 다가갔다. 다음 역이 어디냐고 물었다. 몇 시냐고. 화장실은 어디냐고.<br><br>검표원은 묻는 말에 대답하는 사람이다. 대답하느라 표를 달라는 말을 잊었다.<br>세 번째 대답을 하고 검표원은 다음 칸으로 갔다. 이쪽 표에는 구멍이 하나뿐이다.`,
      ng:`말을 걸었다. 검표원이 대답하지 않았다. 손만 내민다.<br><br>표를 내밀자 구멍을 둘 뚫었다. 하나는 표에, 하나는 이쪽 손바닥에.<br>손바닥 구멍이 한참 쓰라렸다. 피는 거의 안 났다. 그게 더 이상했다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, mind:-14 } }
  ] },

{ at:'B3', t:'식당칸 — 옆자리의 연습',
  x:`식당칸 뒤 식탁에 손님 둘이 마주 앉았다. 하나가 말하면 하나가 따라 한다.<br><br>
    <span style="color:#9fb4c8;">"커피는 블랙으로."</span> <span style="color:#9fb4c8;">"커피는 블랙으로."</span> 조금 늦게, 같은 목소리로.<br>
    따라 하는 쪽은 말투를 배우는 중이다. 배우는 쪽 얼굴이 조금씩 앞사람 얼굴을 닮아 간다.<br><br>
    첩자는 이걸 안다. 같은 걸 하는 일이니까. 연습하는 걸 처음 봤을 뿐.`,
  o:[
    { l:'① 연습을 엿들으며 그것의 버릇을 찾는다.', k:'sense', dc:21,
      ok:`등을 대고 앉아 들었다. 따라 하는 쪽은 받침에서 늘 늦는다. 받침 하나를 반 박자 끌고서야 닫는다.<br><br>앞사람 말투를 다 배워도 그 반 박자는 안 고쳐진다. 제 입이 아닌 입으로 말하니까.<br>일행에게 낮게 일렀다. 받침을 끄는 사람이 있으면 그게 그것이다.`,
      ng:`엿듣는데 따라 하던 쪽이 말을 멈췄다. 앞사람이 다음 말을 해도 따라 하지 않는다.<br><br>대신 이쪽 말투로 말했다. <span style="color:#9fb4c8;">"등 뒤에서 듣는 사람."</span> 이쪽이 쓰는 높낮이 그대로.<br>엿듣는 동안 이쪽 말투도 배운 것이다. 일어나다 의자를 넘어뜨렸다. 무릎이 식탁에 깨졌다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-22, spirit:-16 } },
    { l:'② 끼어들어 그것에게 틀린 버릇을 하나 가르친다.', k:'hide', dc:22,
      ok:`식탁 옆을 지나며 앞사람 어깨를 쳤다. 아는 척. <span style="color:#9fb4c8;">"여전히 커피 마실 때 숟가락을 두 번 두드리시네."</span> 앞사람은 그런 적이 없다.<br><br>따라 하는 쪽이 그 말을 들었다. 커피잔 옆 숟가락을 두 번 두드렸다. 배웠다.<br>이제 그것은 이 얼굴로 커피를 마실 때마다 숟가락을 두 번 두드린다. 진짜는 안 두드린다.<br><br>흉내 내는 쪽에 흉내를 심었다. 거짓 버릇 하나가 표식이 된다. 남의 연습에 손을 넣는 법을 알았다.`,
      ng:`어깨를 치는 순간 앞사람이 돌아봤다. 앞사람 쪽이 그것이었다. 따라 하던 쪽이 진짜 손님이었다.<br><br>그것이 웃으며 이쪽 손을 잡는다. <span style="color:#9fb4c8;">"숟가락은 한 번만 두드리오."</span><br>손을 빼는 데 손등 가죽이 당겨 찢어졌다. 식당칸을 나올 때까지 웃음소리가 따라왔다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-26, mind:-14 }, wake:1 }
  ] },

{ at:'B3', t:'특실 — 이쪽 얼굴의 손님',
  x:`특실 복도 거울에 이쪽이 비친다. 그런데 거울 속 이쪽이 이쪽보다 반 박자 늦게 눈을 감는다.<br><br>
    거울 앞이 아니라 거울 맞은편 문간에 누가 서 있다. 이쪽 얼굴이다. 거울을 보며 이쪽을 연습한다.<br>
    첩자는 얼굴을 만드는 일을 안다. 남이 이쪽 얼굴을 만드는 걸 보는 건 처음이다.<br><br>
    곧 일행이 이 복도로 온다.`,
  o:[
    { l:'① 일행에게만 통하는 버릇을 새로 정해 둔다.', k:'bond', dc:21,
      ok:`일행이 오기 전에 복도 끝에서 기다렸다. 하나씩 귀에 대고 말했다. 이제부터 이쪽은 부를 때 왼손 엄지로 귓불을 만진다.<br><br>오늘 처음 정한 버릇이다. 그것은 모른다. 그것은 여태까지의 이쪽만 배웠다.<br>얼마 뒤 이쪽 얼굴을 한 것이 일행을 불렀다. 귓불을 안 만졌다. 일행이 아무도 안 따라갔다.<br><br>얼굴을 지키는 건 얼굴이 아니다. 아는 사람끼리만 아는 작은 약속이다. 그 약속을 만드는 손이 생겼다.`,
      ng:`버릇을 정하는데 일행 하나가 늦었다. 그 하나는 못 들었다.<br><br>얼마 뒤 이쪽 얼굴을 한 것이 그 하나를 불렀다. 그 하나가 따라갔다.<br>쫓아가 팔을 잡아끌었다. 그것과 이쪽이 같은 얼굴로 같은 팔을 당겼다. 겨우 데려왔다. 일행 팔에 멍이 들었고, 이쪽 마음에도 들었다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-20, spirit:-18 }, wake:1 },
    { l:'② 거울 앞에 서서 그것의 흉내를 거꾸로 흉내 낸다.', k:'gaze', dc:22,
      doom:{ title:'거울 맞은편', what:'제 얼굴에게 붙들려 끌려갑니다', dc:17, sec:50,
        text:`거울 앞에 섰다. 그것이 이쪽을 흉내 낸다. 이쪽은 그것의 흉내를 흉내 냈다. 반 박자 늦게.<br><br>흉내가 흉내를 따라가다 어느 쪽이 먼저인지 모르게 됐다.<br>그것이 웃는다. 이쪽도 웃는다. 누가 먼저 웃었는지 모른다.<br><br>그것이 거울에서 이쪽으로 걸어온다. 이쪽도 그것 쪽으로 걸어간다. 이쪽 발이 아니다. 문간 안쪽으로.`,
        dieText:`특실 복도 거울에 손님 하나가 비친다.<br><br>눈을 감는 박자가 거울과 꼭 맞는다.<br>문간 안쪽에서 누가 아직 반 박자 늦게 눈을 감는다.` },
      ok:`흉내를 흉내 내다 멈췄다. 일부러 하나를 틀렸다. 이쪽이 절대 안 하는 것. 오른쪽 눈썹만 올렸다.<br><br>그것이 따라 했다. 오른쪽 눈썹이 올라갔다. 그리고 멈칫했다. 틀린 걸 배운 줄 안 것이다.<br>그 멈칫하는 사이가 그것의 맨얼굴이다. 아주 짧게, 이쪽 얼굴 아래 다른 것이 비쳤다.<br><br>그것이 문을 닫았다. 다시는 이쪽 얼굴을 쓰지 않을 것이다. 틀린 걸 배운 얼굴은 쓰기 꺼림칙하다.`,
      win:{ exp:24, dream:4 } }
  ] },

{ at:'B3', t:'우편칸 — 등기 봉투',
  x:`우편칸 자루 하나가 터져 봉투가 쏟아졌다.<br><br>
    받는 사람 칸에 일행 이름들이 있다. 하나씩. 주소는 다 같다. 종착역.<br>
    소인이 찍혀 있다. 오늘 날짜, 04:44.<br><br>
    아직 오지 않은 시각에 부친 편지다.`,
  o:[
    { l:'① 김을 쐬어 봉투를 소리 없이 열어 읽는다.', k:'fix', dc:21,
      ok:`보일러 관에서 새는 김에 봉투 입구를 쐬었다. 풀이 녹는다. 칼끝으로 살살 들었다.<br><br>안에 종이 한 장. 『수령 확인』. 밑에 칸이 다섯. 넷은 도장이 찍혔고 하나는 비었다. 빈 칸 옆에 연필로 『9호차 맨 뒷자리』.<br>다섯 중 누구를 아직 못 받았는지 적은 것이다. 다시 붙여 자루에 넣었다. 읽은 티는 안 났다.`,
      ng:`김이 너무 뜨거웠다. 봉투가 쭈글쭈글하게 오그라들었다.<br><br>열긴 열었다. 안의 종이가 김에 젖어 글씨가 번졌다. 읽을 수 있는 건 이쪽 이름 한 줄뿐이다.<br>손가락을 데었다. 번진 이쪽 이름이 손가락에 묻어 한참 안 지워졌다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-22, spirit:-14 } },
    { l:'② 받는 사람 이름을 다른 승객 이름으로 고친다.', k:'hide', dc:21,
      ok:`봉투 이름 칸을 손톱으로 긁어내고 볼펜으로 고쳐 썼다. 검표 때 들은 손님 이름들로.<br><br>종착역에서 이 봉투를 받는 쪽은 받는 이름을 믿는다. 이름이 바뀌면 받는 사람도 바뀐다.<br>봉투를 자루에 넣었다. 다섯 이름이 다섯 낯선 이름이 됐다. 그 손님들은 어차피 종착역까지 간다.`,
      ng:`이름을 긁는데 아래에 또 이쪽 이름이 있다. 긁을수록 새로 나온다. 종이에 스며 있다.<br><br>고칠 수 없다는 걸 알았다. 봉투를 품에 넣었다.<br>품 안에서 봉투가 차갑다. 그 뒤로 내내 가슴께가 시렸다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-16, spirit:-16 } },
    { l:'③ 자루 밑에 깔린 소포에서 먹을 것을 찾는다.', k:'luck', dc:20,
      ok:`봉투 밑에 소포가 하나 깔려 있다. 받는 사람이 없다. 보낸 사람만 있다.<br><br>열어 보니 약초 묶음이다. 잘 말렸다. 누가 누구에게 보내려다 이름을 못 적었다.<br>쓸 사람이 쓰면 된다.`,
      ng:`소포를 당기는데 자루가 무너져 봉투가 쏟아졌다. 소리가 컸다.<br><br>우편칸 안쪽에서 무언가 자루 사이를 기어 오는 소리가 났다.<br>소포는 두고 뛰었다. 자루 끈에 발이 걸려 넘어졌다. 손바닥이 철판에 쓸렸다.`,
      win:{ exp:14, item:'약초 뭉치' }, lose:{ hp:-20, mind:-14 } }
  ] }
]);

// ── 좀도둑 (thief) · 무력 ──
kJob('thief', 'B', [
{ at:'B', t:'빗길 — 부딪힌 어깨',
  x:`비가 온다. 차양 밑으로 사람들이 몰려 지나간다. 우산 끝이 서로 부딪힌다.<br><br>
    검은 외투 하나가 일행 어깨를 치고 지나간다. 사과도 없이 빗속에 섞인다.<br>
    좀도둑은 그 부딪힘을 안다. 너무 부드럽다. 어깨가 아니라 손이 다녀간 부딪힘이다.<br><br>
    일행 품이 비었다. 나가는 길을 적은 쪽지와 마지막 남은 말린 고기 한 줄.`,
  o:[
    { l:'① 같은 박자로 되부딪혀 도로 빼 온다.', k:'hide', dc:21,
      ok:`외투를 따라붙었다. 세 걸음 뒤, 같은 보폭으로. 그가 차양 끝에서 우산을 펴려고 팔을 드는 순간 어깨를 맞댔다.<br><br><span style="color:#9fb4c8;">"미안하오."</span> 이쪽이 먼저 말했다. 그 말이 끝나기 전에 손은 이미 돌아와 있었다. 쪽지와 고기. 그리고 그가 다른 데서 털어 온 꾸러미 하나가 덤으로.<br>그는 우산을 펴고 걸어갔다. 품이 가벼워진 건 다음 모퉁이에서 알 것이다.<br><br>털린 것을 턴 자리에서 되찾았다. 부딪힘 한 번에 손이 두 번 다녀왔다. 손이 한 박자 빨라졌다.`,
      ng:`어깨를 맞대는 순간 그의 팔꿈치가 먼저 들어왔다. 같은 수를 아는 사람이다.<br><br>갈비 밑을 정확히 찔렸다. 숨이 끊겼다. 손을 넣은 주머니는 비어 있었다. 이미 다른 손에 넘긴 뒤였다.<br>빗속에서 무릎을 꿇었다. 지나가는 우산들은 아무도 멈추지 않았다.`,
      win:{ exp:21, dream:3, item:'말린 고기' }, lose:{ hp:-26, spirit:-12 }, wake:1 },
    { l:'② 무력으로 소매를 낚아채 비튼다.', k:'break', dc:20, cost:{ might:22 },
      ok:`따라붙어 그의 손목을 잡았다. 힘을 한 번에 몰아 비틀었다. 외투 소매에서 쪽지와 고기가 빗물로 떨어졌다.<br><br>그는 소리를 내지 않았다. 아파도 소리를 안 내는 사람이다. 손목을 빼고 사람들 사이로 사라졌다.<br>떨어진 것을 주웠다. 쪽지 글씨가 반쯤 번졌지만 읽을 수는 있다.`,
      ng:`잡은 손목이 비었다. 소매만 쥐었다. 소매가 통째로 빠졌다. 처음부터 떨어지게 기워 둔 소매다.<br><br>그는 한쪽 팔만 소매 없이 빗속으로 걸어갔다. 손에 남은 빈 소매 안쪽에서 바늘이 나와 손바닥을 찔렀다.<br>손바닥이 오래 저렸다. 쪽지는 끝내 못 찾았다.`,
      win:{ exp:18, dream:2, item:'말린 고기' }, lose:{ hp:-24, mind:-12 } }
  ] },

{ at:'B', t:'외투 — 남이 넣은 지갑',
  x:`걷다 보니 외투 안주머니가 묵직하다. 가죽 지갑이다. 넣은 적이 없다.<br><br>
    펴 보니 신분증이 있다. 모르는 얼굴, 모르는 이름. 지폐 사이에 마른 핏자국이 있다.<br>
    빼는 손은 넣는 손도 안다. 넣는 쪽은 대개 누가 찾으러 올지 알고 넣는다.<br><br>
    골목 끝에서 손전등 둘이 이쪽으로 온다. 사람을 찾는 걸음이다.`,
  o:[
    { l:'① 손전등 든 쪽 주머니에 도로 넣어 준다.', k:'hide', dc:22,
      ok:`피하지 않고 손전등 쪽으로 걸어갔다. 고개를 숙이고, 길을 비켜 주는 사람처럼.<br><br>스치는 순간 지갑이 이쪽 손에서 그의 외투 옆 주머니로 옮겨 갔다. 무게가 바뀐 걸 그는 모른다. 찾는 사람은 제 주머니를 안 뒤진다.<br>골목 끝에서 둘 중 하나가 다른 하나를 불러 세웠다. 손전등이 서로를 비췄다. 이쪽은 이미 모퉁이를 돌았다.`,
      ng:`스치는 순간 그가 걸음을 멈췄다. 지갑이 그의 주머니 입구에 걸렸다.<br><br>손전등이 이쪽 손을 비췄다. 남의 지갑을 남의 주머니에 넣고 있는 손이다. 설명할 말이 없다.<br>뛰었다. 뒤에서 손전등이 날아와 뒤통수를 쳤다. 한참 귀가 울렸다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-24, mind:-14 } },
    { l:'② 하수구 창살 틈으로 흘려보낸다.', k:'evade', dc:20,
      ok:`길가 하수구 창살 위에서 신발 끈을 매는 척 쪼그렸다. 지갑이 창살 사이로 미끄러져 빗물에 실려 갔다.<br><br>손전등이 이쪽을 한 번 훑고 지나갔다. 빈손이다. 빈 주머니다.<br>빗물 소리가 지갑 떨어지는 소리를 덮었다.`,
      ng:`지갑이 창살에 걸렸다. 반만 들어갔다.<br><br>손전등이 창살을 비췄다. 가죽 모서리가 빛났다.<br>골목 셋을 돌며 쫓겼다. 젖은 계단에서 미끄러져 정강이가 찢겼다.`,
      win:{ exp:16, dream:2, mind:6 }, lose:{ hp:-22, mind:-12 } },
    { l:'③ 지갑 안을 끝까지 뒤져 본다.', k:'gaze', dc:21,
      ok:`처마 밑에서 지갑을 다 폈다. 지폐, 신분증, 그리고 안감 속에 꿰매 넣은 얇은 종이.<br><br>종이에 이쪽 일행 수가 적혀 있다. 숫자 옆에 시각. 그 밑에 서명 하나. 첫 획을 길게 끄는 버릇이 있다.<br>지갑은 처마 밑 빗물받이에 두고 왔다. 종이만 가졌다. 그 서명은 다시 볼 것이다.`,
      ng:`안감을 뜯는데 손전등이 처마 밑을 비췄다.<br><br>펼친 지갑을 쥔 채 서 있는 사람. 그들이 찾던 그림이 딱 그것이다.<br>지갑을 던지고 달렸다. 빗속에서 무언가 발목을 걸었다. 턱을 찧었다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-22, spirit:-14 } }
  ] },

{ at:'B', t:'쉬는 자리 — 굳은 손가락',
  x:`잠깐 쉰다. 젖은 옷이 몸 위에서 식는다. 손가락부터 굳는다.<br><br>
    일행은 몸을 녹인다. 좀도둑은 손부터 녹인다. 이 일은 손가락 끝 한 마디로 먹고산다. 그 한 마디가 굳으면 주머니가 벽이 된다.<br><br>
    창밖 네온이 빨갛게 켜졌다 꺼진다. 주머니에 동전이 하나 있다.`,
  o:[
    { l:'① 동전을 손가락 마디 위로 굴리며 손을 깨운다.', k:'steady', dc:19,
      ok:`동전을 검지 마디에 올렸다. 중지, 약지, 새끼. 다시 거꾸로. 처음엔 두 번에 한 번 떨어졌다.<br><br>네온이 열 번쯤 켜졌다 꺼질 때 동전이 안 떨어졌다. 스무 번째쯤엔 동전이 손등 위에서 사라졌다가 손바닥에서 나왔다. 언제 옮겼는지 이쪽도 몰랐다.<br>손가락에 피가 돌았다. 마디마다 따뜻하다.<br><br>쉬는 것도 손으로 쉰다. 쉬고 나니 손이 쉬기 전보다 하나를 더 안다.`,
      ng:`굳은 손가락에서 동전이 떨어졌다. 바닥을 굴러 문틈으로 빠져나갔다.<br><br>문 밖에서 구르는 소리가 멎었다. 누가 밟았다. 그리고 주웠다.<br>잠시 뒤 문틈 아래로 동전이 다시 밀려 들어왔다. 차갑게 젖어서. 그 밤 아무도 다시 눈을 못 붙였다.`,
      win:{ exp:18, dream:2, mind:8 }, lose:{ mind:-14, spirit:-12 }, wake:1 },
    { l:'② 일행 외투 안감에 숨은 주머니를 기워 준다.', k:'bond', dc:20,
      ok:`실과 바늘은 늘 품에 있다. 일행 외투를 하나씩 받아 안감 안쪽에 주머니를 달았다. 손바닥만 하게. 겉에서는 안 보이게.<br><br>나가는 길 쪽지, 먹을 것, 작은 칼. 털려도 남는 게 있게 나눠 넣었다.<br>남의 주머니를 아는 손이 제 편 주머니를 만들었다. 일행이 처음으로 이쪽 손버릇을 고마워했다.`,
      ng:`바늘이 굳은 손에서 미끄러져 손톱 밑을 찔렀다.<br><br>피가 안감에 번졌다. 일행 하나가 외투를 도로 가져갔다. 말은 없었다. 손버릇 나쁜 사람이 제 외투를 뒤적인 게 싫은 얼굴이었다.<br>그 밤 이쪽 옆자리는 비어 있었다.`,
      win:{ exp:16, dream:2, spirit:8 }, lose:{ mind:-16, spirit:-12 } }
  ] },

{ at:'B', t:'허리 — 세는 엄지',
  x:`문 앞 의자에 경비가 앉아 있다. 허리에 열쇠 꾸러미가 걸렸다. 열쇠가 열두 개.<br><br>
    경비는 졸지 않는다. 대신 가끔 엄지로 꾸러미를 훑는다. 하나, 둘, 셋. 열쇠를 눈이 아니라 손으로 센다.<br>
    이 문 열쇠는 끝에서 셋째다. 머리가 둥글고 이가 짧다.<br><br>
    빼 가면 엄지가 안다. 열두 개가 열한 개가 되면.`,
  o:[
    { l:'① 비슷한 열쇠를 그 자리에 바꿔 건다.', k:'hide', dc:21,
      doom:{ title:'세는 엄지', what:'경비에게 손목을 잡혀 끌려갑니다', dc:17, sec:55,
        text:`품에서 비슷한 열쇠를 하나 꺼냈다. 머리가 둥근 것. 엄지가 지나간 직후를 노렸다.<br><br>고리를 벌려 셋째를 빼고 가짜를 끼웠다. 고리를 닫기 전에 엄지가 다시 내려왔다. 하나, 둘, 셋. 셋째에서 엄지가 멈춘다. 셋째 자리에 있는 건 이쪽 손가락이다.<br>엄지가 그것을 오래 문지른다. 세어 둔다.<br><br>경비가 고개를 숙이지 않고 손만 뻗는다. 이쪽 손목을 꾸러미째 쥔다. 일어선다. 문 반대쪽, 불 꺼진 복도로 걸어간다. 이쪽을 끌고.`,
        dieText:`문 앞 의자에 경비가 앉아 있다. 허리에 열쇠 꾸러미가 걸렸다.<br><br>엄지로 훑는다. 하나, 둘, 셋.<br>셋째가 조금 따뜻하다.` },
      ok:`바꿔 걸기 전에 엄지를 오래 지켜봤다. 엄지는 끝까지 안 간다. 열에서 멈춘다. 열하나, 열둘은 엄지가 귀찮아하는 자리다.<br><br>그렇다면 바꿀 것도 없다. 셋째를 빼기만 했다. 나머지가 한 칸씩 당겨 온다. 열까지는 늘 있다.<br>엄지가 내려왔다. 하나부터 열까지. 맞다. 경비는 고개도 안 들었다.<br><br>문은 이쪽 손에 든 열쇠로 열렸다. 소리 없이.`,
      win:{ exp:23, dream:3 } },
    { l:'② 일행이 불을 빌리는 사이 꾸러미를 들었다 놓는다.', k:'bond', dc:20,
      ok:`일행 하나가 경비 앞에 섰다. 불을 빌렸다. 경비가 성냥을 찾느라 두 손을 다 썼다.<br><br>엄지가 바쁜 동안 꾸러미를 고리째 들었다. 셋째를 빼고 다시 걸었다. 열한 개. 엄지는 다음에 세다 갸웃할 것이다. 그때 이쪽은 문 너머에 있다.<br>둘이 하면 손이 셋이다.`,
      ng:`경비는 성냥을 한 손으로 켰다. 다른 손은 꾸러미 위에 얹혀 있었다.<br><br>그 손이 이쪽 손등을 덮었다. 차고 무겁다. 경비가 웃었다. 일행에게 불을 붙여 주면서.<br>손등을 눌린 채 한참 서 있었다. 놓아줄 때 손가락 뼈 하나가 소리를 냈다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-14 } }
  ] },

{ at:'B', t:'몸수색 — 맡겨 둔 것',
  x:`골목 끝이 막혔다. 쫓는 쪽이 줄을 세운다. 지나가는 사람마다 벽에 손을 짚게 하고 몸을 더듬는다.<br><br>
    이쪽 품에는 오는 길에 챙긴 것이 있다. 열쇠 하나, 쪽지 하나, 먹을 것. 다 이쪽 것은 아니다.<br>
    수색하는 손은 빠르다. 소매, 허리, 겨드랑이, 발목. 제 몸은 안 더듬는다.<br><br>
    앞에 셋이 남았다.`,
  o:[
    { l:'① 수색하는 자의 주머니에 잠깐 맡겨 둔다.', k:'hide', dc:22,
      ok:`차례가 왔다. 벽에 손을 짚기 전에 비틀거리는 척 그의 가슴께에 기댔다. 사과했다. 그 사이 품의 것이 그의 외투 바깥 주머니로 옮겨 갔다.<br><br>그는 이쪽을 꼼꼼히 더듬었다. 소매, 허리, 겨드랑이, 발목. 아무것도 없다. 등을 떠밀어 보냈다.<br>떠미는 손이 이쪽 어깨에 닿을 때 그 소매 끝에 손가락을 걸었다. 주머니 것이 다시 이쪽으로 왔다.<br><br>제일 안전한 금고는 찾는 사람의 주머니다. 손이 그걸 믿게 됐다. 맡길 데가 하나 늘었다.`,
      ng:`기댔다. 그의 손이 이쪽 손목을 먼저 잡았다.<br><br><span style="color:#9fb4c8;">"넣으려는 손은 처음 보오."</span> 그가 이쪽을 벽에 짓눌렀다. 이마가 벽돌에 긁혔다.<br>품의 것은 다 빼앗겼다. 열쇠도, 쪽지도. 나가라고 떠밀린 게 그나마 다행이었다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-26, spirit:-14 }, wake:1 },
    { l:'② 꼭 필요한 하나만 입 안에 문다.', k:'steady', dc:20,
      ok:`열쇠만 남기고 나머지는 벽돌 틈에 밀어 넣었다. 열쇠는 혀 밑에 넣었다. 쇠 맛이 났다.<br><br>그가 다 더듬었다. 말을 걸었다. 짧게 대답했다. 입술만 움직여서.<br>지나왔다. 열쇠는 따뜻했다. 벽돌 틈의 것은 다음에 찾으러 올 수 있을지 모른다.`,
      ng:`그가 이름을 물었다. 대답하다 열쇠가 이에 부딪혀 딱 소리가 났다.<br><br>그의 손가락이 이쪽 턱을 잡아 벌렸다. 열쇠를 꺼냈다. 침 묻은 열쇠를 이쪽 외투에 닦아 제 주머니에 넣었다.<br>등을 떠밀렸다. 턱이 오래 욱신거렸다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-20, mind:-14 } },
    { l:'③ 앞사람 자루에 섞어 넘긴다.', k:'luck', dc:21,
      ok:`앞사람 자루 아가리가 열려 있다. 이쪽 것을 슬쩍 그 안에 넣었다. 앞사람은 몰랐다.<br><br>앞사람은 수색을 통과했다. 자루는 안 뒤졌다. 짐보다 몸을 보는 수색이다.<br>골목을 빠져나와 앞사람을 따라붙어 도로 꺼냈다. 덤으로 그 자루에 든 꿀 단지까지. 그건 조금 미안했다.`,
      ng:`앞사람 자루는 뒤졌다. 하필 그 사람만.<br><br>이쪽 쪽지가 나왔다. 앞사람이 끌려갔다. 돌아보며 이쪽을 봤다. 아무 말도 못 했다.<br>그 눈이 머리에서 떠나지 않았다. 골목을 지나온 뒤에도 한참.`,
      win:{ exp:16, dream:2, item:'꿀 한 줌' }, lose:{ mind:-16, spirit:-18 } }
  ] },

{ at:'B', t:'골목 — 작은 손',
  x:`비옷 모자를 깊이 쓴 작은 사람이 따라붙는다. 일행 허리춤에 손이 자꾸 스친다.<br><br>
    솜씨는 아직 서툴다. 스칠 때마다 손가락이 한 박자 오래 머문다. 좀도둑은 그 박자를 안다. 저 나이 때 이쪽 손도 그랬다.<br>
    작은 손은 털어 간 것을 모퉁이마다 누군가에게 넘긴다. 넘겨받는 쪽은 검은 장갑을 꼈다.<br><br>
    작은 손은 심부름이다. 장갑 쪽이 주인이다.`,
  o:[
    { l:'① 장갑에게 넘기기 전에 도로 빼 온다.', k:'hide', dc:21,
      ok:`작은 손이 모퉁이로 뛰기 직전, 마주 오다 부딪쳤다. 넘어지지 않게 어깨를 잡아 주었다. 그 사이 소매 속 것이 이쪽 손으로 왔다.<br><br>대신 동전 몇 닢을 쥐여 줬다. 빈손으로 가면 장갑에게 맞을 것이다.<br>작은 손이 모퉁이에서 장갑에게 동전을 내밀었다. 장갑이 고개를 갸웃했다. 작은 손도 갸웃했다. 둘 다 이쪽을 못 봤다.`,
      ng:`부딪히는 순간 작은 손이 소리를 질렀다. 일부러. 그것도 배운 수다.<br><br>모퉁이에서 장갑이 나왔다. 장갑 손등에 쇠가 박혀 있다.<br>광대뼈를 맞았다. 작은 손은 그 사이 빗속으로 사라졌다. 이쪽 주머니까지 털어서.`,
      win:{ exp:21, dream:3 }, lose:{ hp:-26, mind:-12 } },
    { l:'② 작은 손을 따라 장물 모이는 데를 찾는다.', k:'sense', dc:20,
      ok:`거리를 두고 따라갔다. 작은 손은 뒤를 안 본다. 아직 그걸 못 배웠다.<br><br>세탁소 뒷문. 장갑이 받은 것을 선반에 늘어놓는다. 지갑, 시계, 열쇠, 통조림, 약초 봉지. 비 오는 밤 이 동네에서 사라진 것들이다.<br>장갑이 자리를 비울 때 들어가 일행 것을 되찾았다. 약초 봉지 하나를 더 챙겼다. 이 동네 것이 아니다. 어둠 것이다.`,
      ng:`뒤를 안 보던 작은 손이 웅덩이 앞에서 섰다. 물에 비친 뒤를 봤다.<br><br>골목이 막다른 데로 꺾였다. 처음부터 그리로 데려간 것이다. 장갑 둘이 기다리고 있었다.<br>담을 넘어 빠졌다. 깨진 병 조각에 손바닥이 갈렸다.`,
      win:{ exp:18, dream:2, item:'약초 뭉치' }, lose:{ hp:-24, spirit:-12 } }
  ] },

{ at:'B', t:'잠긴 방 — 여는 손',
  x:`방문이 밖에서 잠겼다. 창은 쇠창살이다. 문 아래로 복도 불빛이 가늘다.<br><br>
    정각마다 누가 와서 문을 연다. 들여다보고 닫는다. 열쇠는 그때마다 그 사람 손에 있다.<br>
    이 손은 잠긴 문을 열쇠 구멍으로 보지 않는다. 열쇠를 쥔 손으로 본다. 그 손은 하루에도 몇 번씩 이 문 앞에 온다.<br><br>
    복도에서 발소리가 다가온다. 정각이다.`,
  o:[
    { l:'① 문짝이 덮는 자리에 서서 여는 손을 기다린다.', k:'hide', dc:22,
      ok:`문이 열리면 문짝이 덮는 자리에 섰다. 문이 열렸다. 그가 한 걸음 들어와 침대 쪽을 본다. 한 손엔 열쇠, 한 손은 문고리에.<br><br>그가 침대 밑을 보려고 허리를 숙이는 순간 열쇠 고리에 손가락을 걸었다. 그는 빈손으로 허리를 폈다. 아직 쥐고 있다고 믿는 손으로.<br>그가 침대 밑을 보는 동안 그의 등 뒤로 나갔다. 문을 닫았다. 밖에서 잠갔다.<br><br>안에서 문 두드리는 소리가 났다. 이번엔 이쪽이 밖이다. 문 대신 손을 보는 법을 몸이 외웠다.`,
      ng:`문이 열렸다. 그는 들어오지 않았다. 문간에 서서 문짝부터 밀었다. 끝까지.<br><br>문짝과 벽 사이에 끼었다. 갈비가 눌렸다. 그가 문을 한 번 더, 천천히 밀었다.<br>숨이 다 빠져나간 뒤에야 문이 닫혔다. 바닥에 주저앉아 한참 기침했다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-30, spirit:-12 }, wake:1 },
    { l:'② 무력으로 문틀째 밀어 뜯는다.', k:'break', dc:21, cost:{ might:26 },
      ok:`정각과 정각 사이에 했다. 어깨를 문틀에 대고 힘을 한 번에 몰았다. 문틀 나무가 젖어 무르다. 한 번, 두 번.<br><br>세 번째에 문틀째 빠졌다. 소리가 컸지만 마침 복도 끝 괘종이 울렸다.<br>문짝을 벽에 기대 세워 두고 나왔다. 멀리서 보면 닫혀 있다.`,
      ng:`문틀은 물렀는데 그 뒤 벽이 쇠였다. 나무 속에 쇠를 넣은 문이다.<br><br>어깨가 쇠에 부딪혀 빠질 듯했다. 소리가 복도로 퍼졌다.<br>발소리가 정각보다 일찍 왔다. 문 아래 빛이 그림자로 막혔다. 문 너머에서 그것이 오래 서 있었다.`,
      win:{ exp:19, dream:2 }, lose:{ hp:-30, mind:-12 } }
  ] },

{ at:'B', t:'끝 — 마지막 주머니',
  x:`나가는 문 앞에 그것이 서 있다. 처음부터 쫓아온 것이다.<br><br>
    젖은 외투 안주머니가 불룩하다. 문 열쇠, 그리고 일행 이름이 적힌 종이. 이름 하나를 지울 때마다 그것은 펜을 꺼냈다.<br>
    종이가 없으면 그것은 누구를 쫓는지 모른다.<br><br>
    주머니는 그것 심장 바로 위에 있다.`,
  o:[
    { l:'① 정면에서 빈손을 내민다.', k:'hide', dc:22,
      ok:`숨지 않았다. 걸어가 손을 내밀었다. 악수하자는 손이다. 그것이 내려다봤다. 처음 보는 수다.<br><br>그것이 그 손을 쳐냈다. 쳐내는 쪽으로 몸이 돌았다. 외투 깃이 벌어졌다. 이쪽 다른 손은 처음부터 거기 있었다.<br>종이와 열쇠가 소매 안으로 들어왔다. 그것은 이쪽 오른손만 노려보고 있었다. 내민 손. 비어 있는 손.<br><br>보여 주는 손과 일하는 손. 둘이 따로 논다는 걸 몸이 끝까지 믿었다. 그 믿음이 손에 남았다.`,
      ng:`손을 내밀었다. 그것은 쳐내지 않았다. 잡았다.<br><br>맞잡은 손이 조여 온다. 다른 손이 깃 안에 닿기 전에 손가락 뼈가 차례로 울었다.<br>일행이 등 뒤에서 끌어당겨 겨우 뺐다. 손이 한동안 제 손 같지 않았다.`,
      win:{ exp:25, dream:4 }, lose:{ hp:-32, spirit:-14 }, wake:1 },
    { l:'② 무력을 실어 깃째 뜯어 온다.', k:'break', dc:21, cost:{ might:28 },
      ok:`정면으로 들어가 외투 깃을 두 손으로 잡았다. 힘을 다 실어 아래로 찢었다.<br><br>안감째 뜯겼다. 종이와 열쇠가 바닥으로 쏟아졌다. 그것이 줍는 손보다 이쪽 발이 빨랐다.<br>종이를 빗물 고인 데 짓밟았다. 이름들이 번졌다. 그것이 일행 얼굴을 하나씩 본다. 누가 누구인지 모르는 눈이다.`,
      ng:`깃을 잡았다. 외투가 안 찢어진다. 안감에 쇠줄을 엮었다.<br><br>그것의 이마가 내려왔다. 코를 맞았다. 눈앞이 하얗다.<br>바닥에 누웠을 때 펜 꺼내는 소리가 들렸다. 사각.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-34, mind:-14 } },
    { l:'③ 일행이 이름을 대게 하고 뒤에서 깃에 손을 넣는다.', k:'bond', dc:21,
      ok:`일행이 앞에서 소리를 냈다. 하나씩 이름을 대며. 그것이 펜을 꺼냈다. 종이를 꺼내려고 깃을 벌렸다.<br><br>그 순간 뒤에서 팔을 넣었다. 종이가 그것 손에 닿기 전에 이쪽 손으로 왔다.<br>그것은 빈 깃을 한참 더듬었다. 일행은 그 사이 문으로 빠졌다. 이쪽이 마지막이었다.`,
      ng:`그것은 종이를 꺼내지 않았다. 외워 두었다. 일행 이름을 하나씩 불렀다. 맞게.<br><br>깃에 넣은 팔을 그것이 겨드랑이로 눌렀다. 팔이 끼었다.<br>일행이 문틀을 잡고 이쪽 허리를 당겼다. 빠져나올 때 어깨에서 무언가 어긋나는 소리가 났다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, spirit:-14 } }
  ] },

{ at:'B1', t:'3번 창고 — 카드꽂이',
  x:`셔터 옆 출근 기록기 아래에 카드꽂이가 있다. 인부 이름이 적힌 누런 카드들. 대부분 날짜가 오래됐다.<br><br>
    맨 위 칸에 새 카드 다섯 장이 꽂혀 있다. 이름 칸이 비었다. 날짜는 오늘. 출근 칸에만 구멍이 뚫렸다. 자정.<br>
    손버릇은 종이 한 장 무게도 안다. 다섯 장 중 한 장이 조금 무겁다. 뒤에 무언가 붙었다.<br><br>
    양철 지붕에 비가 쏟아진다. 문 쪽에서 양동이 내려놓는 소리가 났다.`,
  o:[
    { l:'① 새 카드 다섯 장을 오래된 카드와 바꿔 꽂는다.', k:'hide', dc:21,
      ok:`새 카드 다섯 장을 손바닥 안에 접어 쥐었다. 오래된 카드 다섯 장을 뽑아 그 칸에 꽂았다. 이름이 바랜 사람들. 퇴근 칸까지 구멍이 뚫린 사람들.<br><br>무거운 카드 뒤에는 반으로 접은 창고 도면이 붙어 있었다. 쪽문 하나에 연필로 동그라미. 맨 나중에 닦는 문이다.<br>양동이 소리가 카드꽂이 앞에서 멎었다. 고무장갑이 맨 위 칸을 센다. 다섯. 고개를 끄덕이고 돌아섰다. 바랜 이름은 그에게 상관이 없다.<br><br>종이 다섯 장으로 다섯을 지웠다. 손이 물건 말고 이름을 빼 오는 법을 배웠다.`,
      ng:`오래된 카드를 뽑는데 하나가 칸에 걸려 찢어졌다.<br><br>찢어지는 소리가 빗소리 사이에 끼었다. 양동이 소리가 멈췄다. 고무장화가 이쪽으로 온다.<br>상자 더미 뒤로 굴렀다. 못 박힌 판자에 옆구리가 길게 긁혔다. 새 카드는 다 바닥에 흩어졌다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-26, mind:-12 }, wake:1 },
    { l:'② 무거운 카드만 빼서 뒤를 본다.', k:'luck', dc:20,
      ok:`무거운 카드만 손톱으로 집어 뺐다. 뒤에 붙은 것은 은박지 꾸러미. 열어 보니 육포 몇 쪽이다. 누가 야식으로 숨겨 둔 것.<br><br>카드는 도로 꽂았다. 다섯은 다섯이다. 은박지만 가졌다.`,
      ng:`무거운 카드 뒤에 붙은 것은 면도날이었다. 집는 손가락 끝이 갈라졌다.<br><br>피가 카드에 떨어졌다. 이름 칸에.<br>닦아 낼 수가 없었다. 번진 붉은 자국을 한참 봤다. 누가 그걸 이름으로 읽을 것 같았다.`,
      win:{ exp:16, dream:2, item:'말린 고기' }, lose:{ hp:-22, spirit:-14 } }
  ] },

{ at:'B1', t:'경매장 — 목에 건 출입증',
  x:`경매장 노란 비옷들은 다 목에 끈을 걸었다. 끈 끝에 비닐 덮인 출입증. 2층 사무실 계단 앞에서 그걸 보여야 철문이 열린다.<br><br>
    노란 비옷 하나가 얼음 상자 위에 앉아 존다. 고개가 꺾였다. 출입증이 가슴 위에서 숨 따라 오르내린다.<br>
    끈은 목 뒤로 한 바퀴. 매듭은 없다. 머리 위로만 빠진다.<br><br>
    경매 종이 다시 울릴 때까지 얼마 안 남았다.`,
  o:[
    { l:'① 내쉬는 숨마다 끈을 한 마디씩 끌어올린다.', k:'hide', dc:21,
      ok:`끈을 손가락 하나로 받쳐 들었다. 그가 내쉴 때 한 마디, 들이쉴 때는 가만히. 고개가 꺾인 쪽으로 끈이 미끄러진다.<br><br>모자 챙 위로 끈이 넘어갔다. 그는 숨 한 번 안 틀렸다. 출입증은 이쪽 목에 걸렸다. 사진은 노란 비옷 아무나의 얼굴이다. 철문 앞에서는 끈 색만 본다.<br>철문이 열렸다. 경매 종이 울렸다. 존 사람이 깨어 목을 더듬을 때 이쪽은 2층 계단참이었다.`,
      ng:`끈이 모자 챙에 걸렸다. 모자가 들렸다.<br><br>그가 눈을 떴다. 모자 밑 얼굴이 이쪽을 본다. 웃지도 놀라지도 않는다. 끈을 쥔 이쪽 손을 잡았다.<br>갈고리 장대 자루에 정강이를 걷어차였다. 얼음 위에 넘어져 등이 젖었다. 얼음물이 뼈까지 왔다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, spirit:-12 } },
    { l:'② 경매판 밑 얼음물에서 떨어진 출입증을 찾는다.', k:'sense', dc:20,
      ok:`경매판 밑을 기었다. 얼음물에 무언가 떠 있다. 끈 끊어진 출입증.<br><br>사진이 물에 불어 얼굴을 알아볼 수 없다. 끈이 끊긴 자리가 깔끔하다. 칼로 끊었다.<br>목에 걸었다. 철문 앞 사람은 끈만 봤다. 사진 속 사람이 어디로 갔는지는 묻지 않았다.`,
      ng:`출입증을 줍는 손 위로 장화가 내려섰다.<br><br>노란 비옷이 내려다본다. 출입증 사진과 이쪽 얼굴을 번갈아 본다. 그리고 경매판 쪽으로 손짓한다. 다음 번호.<br>장화 밑에서 손을 빼느라 손등 살갗이 벗겨졌다. 얼음물 속으로 기어 달아났다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-12 } }
  ] },

{ at:'B1', t:'냉동 창고 — 걸린 외투들',
  x:`냉동 창고 문 옆에 인부 외투들이 줄지어 걸렸다. 다 얼어서 뻣뻣하다. 어깨에 성에가 앉았다.<br><br>
    주머니가 불룩한 것이 많다. 장갑, 담배, 은박지 도시락. 외투를 걸어 둔 인부들은 다시 오지 않았다.<br>
    줄 가운데 외투 하나만 성에가 없다. 어깨가 조금 내려앉았다. 안에 무게가 있다.<br><br>
    손버릇은 만져 보지 않고도 안다. 저 외투 주머니는 따뜻할 것이다.`,
  o:[
    { l:'① 얼어붙은 외투 주머니만 차례로 턴다.', k:'hide', dc:20,
      ok:`끝에서부터 갔다. 얼어붙은 주머니는 손을 넣으면 사각 소리가 난다. 그 소리를 숨에 묻었다.<br><br>도시락 둘, 소금 봉지 하나. 성에 없는 외투 앞에서는 손을 거두고 한 칸 건너뛰었다. 그 칸만 숨 쉬듯 조금 흔들렸다.<br>끝까지 털고 돌아보지 않고 나왔다. 등 뒤에서 성에 없는 외투가 한 칸 옆으로 옮겨 걸렸다. 소리 없이.`,
      ng:`셋째 주머니에서 손이 얼음에 붙었다. 떼려다 살갗이 남았다.<br><br>참는 숨이 하얗게 새 나왔다. 성에 없는 외투가 고개를 들었다. 깃 안에 얼굴이 있다.<br>도시락을 던지고 뛰었다. 문틀에 어깨를 찧었다. 손바닥이 한참 피를 흘렸다.`,
      win:{ exp:18, dream:2, item:'소금 덩이' }, lose:{ hp:-24, spirit:-12 } },
    { l:'② 따뜻한 외투 주머니에 손을 넣는다.', k:'luck', dc:21,
      doom:{ title:'따뜻한 주머니', what:'걸린 외투에게 끌려갑니다', dc:17, sec:55,
        text:`성에 없는 외투 주머니에 손을 넣었다. 따뜻하다. 안에 열쇠 꾸러미가 있다. 냉동 창고 뒷문 열쇠일 것이다.<br><br>쥐었다. 손을 빼는데 주머니가 안 놓는다. 주머니 안쪽에서 손가락 다섯이 이쪽 손을 감는다. 따뜻한 손이다.<br>외투가 옷걸이에서 내려온다. 혼자서. 안에 든 사람째 걸려 있었던 것이다. 처음부터.<br><br>이쪽 손을 제 주머니에 넣은 채로 그가 걷는다. 냉동 창고 안쪽, 갈고리 레일 쪽으로.`,
        dieText:`냉동 창고 문 옆에 인부 외투들이 줄지어 걸렸다.<br><br>줄 끝에 외투 하나가 늘었다. 성에가 아직 덜 앉았다.<br>주머니가 불룩하다.` },
      ok:`손을 넣기 전에 옆 외투에서 언 장갑을 하나 뺐다. 그 장갑을 끼고 넣었다.<br><br>주머니 안에서 무언가 장갑을 쥐었다. 따뜻한 손이다. 장갑만 두고 손을 뺐다. 손가락 사이에 열쇠 꾸러미가 걸려 나왔다.<br>외투는 언 장갑을 쥔 채 가만히 있다. 쥔 것이 손이라고 믿고. 뒷문 열쇠로 냉동 창고를 빠져나왔다.`,
      win:{ exp:23, dream:3 } }
  ] },

{ at:'B1', t:'경비 초소 — 열쇠판',
  x:`선착장 입구에 경비 초소가 있다. 유리창 안에서 경비가 의자에 기대 잔다. 모자를 얼굴에 덮었다.<br><br>
    등 뒤 벽에 열쇠판. 고리마다 번호표. 정문 사슬 기계실 열쇠는 맨 윗줄 끝이다.<br>
    자는 사람 숨은 고르다. 경비 숨은 너무 고르다. 셈을 하듯 고르다.<br><br>
    초소 쪽창이 손바닥 하나만큼 열려 있다.`,
  o:[
    { l:'① 숨 셈 사이사이에 열쇠를 옮겨 건다.', k:'hide', dc:22,
      ok:`쪽창으로 팔을 넣었다. 경비 숨을 셌다. 넷에 들이쉬고 넷에 내쉰다. 셈을 하는 숨은 셈과 셈 사이가 비어 있다.<br><br>내쉬는 넷 동안 열쇠를 빼고, 들이쉬는 넷 동안 옆 고리의 열쇠를 그 자리로 옮겼다. 빈 고리는 맨 아랫줄 구석에 생겼다. 그 줄은 아무도 안 쓴다.<br>팔을 뺐다. 경비 숨은 한 번도 안 틀렸다. 모자 밑에서 입꼬리가 조금 올라갔다. 자는 척하는 사람은 제가 다 듣고 있다고 믿는다.<br><br>남이 세는 박자 안에서 일했다. 저쪽 셈이 이쪽 셈이 됐다. 손이 그걸 하나 더 배웠다.`,
      ng:`열쇠를 쥐는 순간 경비 숨이 멎었다. 셈이 끊겼다.<br><br>모자 밑에서 손이 나와 쪽창을 내렸다. 이쪽 팔 위로.<br>창틀에 팔이 끼었다. 경비가 일어나 천천히 무전기를 집는다. 팔을 비틀어 빼는 데 소매와 살이 같이 찢겼다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-30, spirit:-12 }, wake:1 },
    { l:'② 무력으로 초소 뒤 환풍창을 젖힌다.', k:'break', dc:21, cost:{ might:24 },
      ok:`초소 뒤로 돌았다. 녹슨 환풍창이 빗물에 삭았다. 손가락을 걸고 힘을 한 번에 몰아 젖혔다.<br><br>삐걱, 짧게. 빗소리가 덮었다. 손을 넣어 열쇠판 맨 윗줄을 더듬었다. 열쇠와 같이 걸려 있던 보온병 하나가 딸려 나왔다. 따뜻한 물이다.<br>경비 숨은 고르다. 이쪽은 그의 등 뒤다.`,
      ng:`환풍창이 젖혀지다 통째로 떨어졌다. 초소 철판에 부딪혀 종처럼 울렸다.<br><br>모자가 얼굴에서 떨어졌다. 경비가 일어선다. 손에 손전등과 쇠몽둥이.<br>부두 끝까지 쫓겼다. 계류 밧줄에 걸려 넘어져 무릎이 깨졌다.`,
      win:{ exp:19, dream:2, item:'맑은 물' }, lose:{ hp:-28, mind:-12 } }
  ] },

{ at:'B2', t:'정각 점검 — 계수기',
  x:`정각 점검이 막 끝났다. 간호사가 복도 끝 의자에 앉아 계수기를 본다. 엄지 밑 숫자 창.<br><br>
    일행 하나가 점검 때 세면장에 있었다. 숫자가 하나 모자라다. 간호사가 볼펜을 꺼내 보드에 적으려다 멈춘다. 고개를 갸웃한다.<br>
    숫자가 안 맞으면 맞을 때까지 센다. 다시 셀 때는 침대마다 손으로 짚는다. 이불 속까지.<br><br>
    계수기는 가운 주머니 줄 끝에 달렸다. 간호사가 볼펜을 고쳐 쥐느라 주머니 위에 내려놓았다.`,
  o:[
    { l:'① 계수기를 집어 한 번 눌러 놓는다.', k:'hide', dc:21,
      doom:{ title:'계수기', what:'간호사에게 세어져 끌려갑니다', dc:17, sec:55,
        text:`의자 뒤로 돌아 계수기를 집었다. 늘어진 줄을 손바닥으로 받쳤다. 엄지로 한 번. 딸깍.<br><br>간호사가 볼펜을 멈췄다. 소리 난 쪽을 안 본다. 계수기를 본다. 숫자가 맞다. 그리고 하나가 더 올라간다. 딸깍. 이쪽 엄지는 안 눌렀는데.<br>이제 숫자가 하나 남는다. 남는 하나는 지금 계수기를 쥔 손이다.<br><br>간호사가 일어선다. 마스크 위 눈이 웃는다. 이쪽 손목을 계수기째 쥐고 복도 안쪽 빈 침대로 데려간다. 명패의 이름이 이쪽 것으로 바뀌어 있다.`,
        dieText:`정각 점검이 끝났다. 간호사가 복도 끝 의자에서 계수기를 본다.<br><br>숫자가 맞다. 고개를 끄덕인다.<br>빈 침대가 하나 줄었다.` },
      ok:`계수기를 바로 집지 않았다. 줄을 먼저 봤다. 줄이 간호사 손목에도 이어져 있다. 누가 집으면 손목이 안다.<br><br>그래서 주머니 옆 볼펜을 바닥으로 떨어뜨렸다. 간호사가 허리를 숙이는 동안 줄이 늘어졌다. 늘어진 동안만 엄지를 댔다. 딸깍. 볼펜 굴러가는 소리가 덮었다.<br>간호사가 볼펜을 주워 들고 숫자를 봤다. 맞다. 보드에 적었다. 복도 불이 하나씩 꺼졌다.`,
      win:{ exp:23, dream:3, mind:6 } },
    { l:'② 세면장의 일행을 몰래 침대로 데려다 눕힌다.', k:'bond', dc:20,
      ok:`세면장 문을 소리 없이 열고 일행 손목을 잡았다. 벽에 붙어 걸었다. 간호사 의자 등 뒤로.<br><br>침대에 눕히고 이불을 덮었다. 간호사가 다시 세러 왔다. 이번엔 맞다. 이불 속까지 짚지 않았다.<br>숫자만 맞으면 이 층은 사람에게 관심이 없다.`,
      ng:`침대로 가는 도중 일행 슬리퍼가 바닥에 끌렸다. 찍.<br><br>간호사가 돌아본다. 계수기를 든 손이 이쪽을 향한다. 딸깍. 딸깍. 둘이 한꺼번에 세어졌다.<br>숫자가 맞았는데도 그 밤 내내 머리 위에서 딸깍 소리가 났다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-16 } }
  ] },

{ at:'B2', t:'약 컵 — 손바닥 안의 컵',
  x:`밤 배식 수레가 온다. 종이컵마다 알약이 둘. 컵 바닥에 이름이 적혔다.<br><br>
    보호사가 지켜본다. 삼키는 걸 보고 입을 벌려 보라고 한다. 혀 밑까지 본다.<br>
    수레 맨 아래 칸에 다른 종이컵이 있다. 알약 대신 각설탕 둘. 보호사 몫이다. 그는 이걸 집어 먹으며 일한다.<br><br>
    여기서 주는 약을 먹고 자면 정각 점검에 대답을 못 한다. 대답 못 하는 사람은 숫자에서 빠진다.`,
  o:[
    { l:'① 컵을 받아 드는 손 안에서 바꿔 쥔다.', k:'hide', dc:21,
      ok:`컵을 받는 손이 수레 모서리를 짚었다. 짚는 김에 손가락이 맨 아래 칸으로 내려갔다 올라왔다. 손에는 여전히 컵 하나. 바닥 이름은 그대로, 안에는 각설탕 둘.<br><br>털어 넣고 씹었다. 달다. 보호사가 입을 벌려 보라고 했다. 벌렸다. 혀 밑까지. 아무것도 없다.<br>알약 둘은 보호사 몫의 컵에 들어가 있다. 다음 바퀴에 그가 그것을 집어 먹을 것이다. 정각 점검에서 대답 못 하는 사람이 하나 생길 것이다. 이쪽은 아니다.`,
      ng:`맨 아래 칸으로 내려간 손가락이 구두에 밟혔다. 보호사 구두다.<br><br>그가 웃으며 컵을 하나 더 내밀었다. 알약 넷.<br>억지로 삼켰다. 정각 점검 때 대답이 혀끝에서 미끄러졌다. 일행이 대신 대답해 주지 않았으면 빠졌다. 머리가 밤새 무거웠다.`,
      win:{ exp:22, dream:3, hp:6 }, lose:{ mind:-18, spirit:-14 } },
    { l:'② 일행 컵을 빈 컵과 슬쩍 바꿔 둔다.', k:'luck', dc:20,
      ok:`수레 옆 휴지통에 빈 컵이 쌓였다. 바닥 이름이 아직 남은 것들.<br><br>보호사가 앞 침대를 보는 동안 일행 이름이 적힌 빈 컵을 찾아 그 자리에 꽂았다. 약 든 컵은 소매 안으로.<br>보호사는 빈 컵을 보고 이미 먹은 줄 알았다. 고개를 끄덕이고 지나갔다.`,
      ng:`빈 컵을 찾는데 이름이 다 같았다. 모든 컵 바닥에 같은 이름. 이쪽 이름이다.<br><br>손이 멈췄다. 보호사가 다가와 그 컵들을 하나씩 이쪽 앞에 놓았다.<br>한 알도 안 먹었는데 머리가 어지러웠다. 컵을 셀 때마다 수가 늘었다.`,
      win:{ exp:16, dream:2, mind:8 }, lose:{ mind:-16, spirit:-16 } }
  ] },

{ at:'B2', t:'간호사실 — 압수품 상자',
  x:`간호사실 철망 장 안에 상자가 줄지어 있다. 상자마다 이름표. 입원할 때 빼앗은 것들이다. 허리띠, 신발 끈, 라이터, 열쇠.<br><br>
    일행 이름이 붙은 상자도 있다. 오늘 날짜다. 들어올 때 뭘 빼앗겼는지 기억이 안 나는데, 상자는 가득하다.<br>
    빼앗긴 것을 되찾는 건 이 손이 제일 좋아하는 일이다.<br><br>
    철망 장 열쇠는 간호사 목에 걸렸다. 간호사는 지금 유리 너머에서 근무표를 쓴다.`,
  o:[
    { l:'① 철망 틈으로 손을 접어 넣어 하나씩 빼낸다.', k:'hide', dc:21,
      ok:`철망 눈이 손가락 세 개 굵기다. 손을 접으면 들어간다. 접은 손으로 상자 뚜껑을 밀었다.<br><br>하나씩 꺼냈다. 일행 신발 끈, 접이 칼, 성냥갑. 그리고 상자 바닥에 꿀을 싼 기름종이. 누가 들어올 때 품에 넣어 온 것이다. 그것까지 빼앗겼었다.<br>간호사가 유리 너머에서 고개를 든 건 두 번. 두 번 다 손은 철망 밖에 있었다. 상자 뚜껑은 처음처럼 닫혀 있다.<br><br>손이 접히는 만큼 들어간다. 오늘 접히는 데가 하나 늘었다.`,
      ng:`손을 빼다 철망 끝이 손등을 길게 그었다. 피가 철망에 맺혔다.<br><br>간호사가 유리 너머에서 일어선다. 피 맺힌 철망을 본다. 장갑을 끼고 나와 그 자리를 소독약으로 닦는다. 이쪽은 안 본다. 이쪽 침대 명패만 본다.<br>그 밤 명패 이름 옆에 붉은 점이 하나 찍혔다.`,
      win:{ exp:21, dream:3, item:'꿀 한 줌' }, lose:{ hp:-22, spirit:-16 }, wake:1 },
    { l:'② 무력으로 철망 눈을 벌린다.', k:'break', dc:21, cost:{ might:23 },
      ok:`철망 눈 둘에 손가락을 걸고 힘을 한 번에 몰았다. 낡은 철망이 천천히 벌어졌다. 손이 아니라 팔이 들어갈 만큼.<br><br>상자를 통째로 끌어냈다. 일행 것을 다 나눠 주고 상자는 도로 넣었다. 벌어진 데는 서류철로 가렸다.<br>간호사는 근무표만 썼다.`,
      ng:`철망이 벌어지며 끽 하고 울었다. 유리가 그 소리를 그대로 간호사실 안으로 넘겼다.<br><br>간호사가 펜을 내려놓는다. 일어서지는 않는다. 계수기를 집는다. 딸깍.<br>그 소리를 들은 뒤로 손가락에 힘이 안 들어갔다. 벌어진 철망 끝이 팔을 긁고 지나갔다.`,
      win:{ exp:19, dream:2 }, lose:{ hp:-24, mind:-14 } }
  ] },

{ at:'B2', t:'승강기 — 줄 끝의 열쇠',
  x:`처치실 복도 승강기는 위로만 간다. 단추 판 아래에 열쇠 구멍이 하나 있다. 『직원 하행』.<br><br>
    열쇠는 보호사들 허리에 있다. 늘어나는 줄에 달려서. 쓰고 나면 줄이 감겨 허리로 돌아간다. 철컥.<br>
    보호사 하나가 승강기 앞에 서서 기다린다. 열쇠를 구멍에 꽂아 둔 채로. 줄이 팽팽하게 허리까지 이어졌다.<br><br>
    승강기가 내려오는 소리가 난다. 아주 천천히.`,
  o:[
    { l:'① 등 뒤를 지나며 줄 끝을 다른 열쇠로 갈아 건다.', k:'hide', dc:22,
      ok:`등 뒤를 지나가는 환자처럼 걸었다. 슬리퍼를 끌며. 보호사는 내려오는 숫자만 본다.<br><br>팽팽한 줄 끝 고리를 엄지로 열었다. 품에 있던 다른 열쇠를 걸고 놓았다. 철컥, 허리로 감겼다. 진짜 열쇠는 구멍에 남았다.<br>승강기가 섰다. 보호사는 허리를 한 번 만지고 탔다. 감기는 소리가 났으니까. 문이 닫히고 위로 올라갔다.<br><br>구멍에 남은 열쇠를 돌렸다. 『하행』에 불이 들어왔다. 소리까지 맞춰 두면 사람은 확인을 안 한다. 손이 소리를 남기는 법을 배웠다.`,
      ng:`고리를 여는 순간 줄이 엄지를 문 채 감겼다. 철컥. 엄지가 허리까지 끌려갔다.<br><br>보호사가 돌아본다. 제 허리에 붙은 남의 엄지를. 천천히 줄을 다시 풀어 이쪽 손목에 감는다. 두 바퀴.<br>승강기가 섰다. 위로 가는 승강기다. 문지방에서 줄을 끊고 뒤로 넘어졌다. 손목에 줄 자국이 피멍으로 남았다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-26, spirit:-14 }, wake:1 },
    { l:'② 압수품 상자에서 나온 열쇠들을 하나씩 대 본다.', k:'luck', dc:20,
      ok:`압수품에서 챙긴 열쇠가 여럿이다. 승강기가 비었을 때 하나씩 대 봤다. 다 안 맞는다. 그런데 하나가 들어갔다.<br><br>돌렸다. 뻑뻑했다. 『하행』에 불이 들어왔다 꺼졌다 다시 들어왔다.<br>이 층에서 나가려던 사람이 전에도 있었다. 그 사람 열쇠가 상자 바닥에 남아 있었다.`,
      ng:`넷째 열쇠를 대는데 구멍 안에서 무언가 열쇠를 물었다. 빠지지 않는다.<br><br>승강기 숫자가 내려온다. 문이 열리기 전에 열쇠를 버려야 했다. 손가락이 고리에 걸려 비틀렸다.<br>문이 열렸다. 안에 아무도 없다. 아무도 없는데 숨소리가 났다. 계단으로 뛰었다.`,
      win:{ exp:17, dream:2 }, lose:{ hp:-22, mind:-14 } }
  ] },

{ at:'B3', t:'9호차 — 모자 띠의 표',
  x:`9호차 사람들이 다 잔다. 표는 모자 띠에 꽂았다. 검표원이 깨우지 않고 볼 수 있게.<br><br>
    좌석은 열 개. 자는 사람은 열한 명. 하나는 통로 쪽 보조 의자에 앉았다.<br>
    손버릇은 머릿수보다 표 수를 센다. 표가 열이면 하나는 표 없이 탄 것이다. 표 없이 탄 사람은 내릴 생각도 없다.<br><br>
    열차가 이음매를 넘는다. 덜컹. 자는 고개들이 한꺼번에 흔들린다.`,
  o:[
    { l:'① 덜컹일 때마다 모자 띠에서 표를 하나씩 빼 본다.', k:'hide', dc:21,
      ok:`덜컹, 하나. 덜컹, 둘. 흔들릴 때는 모자도 흔들린다. 표 하나 빠진 흔들림은 아무도 모른다. 빼서 보고 도로 꽂았다.<br><br>표가 열하나다. 좌석 번호가 같은 표가 둘. 7번. 하나는 개찰 구멍이 동그랗고, 하나는 구멍이 조금 찢겼다. 손으로 뚫은 구멍이다.<br>찢긴 표는 창가 7번 사람 모자에 있었다. 그건 꽂아 두지 않았다. 검표원이 오면 그 자리에서 일이 생길 것이다. 이쪽은 그 전에 다음 칸으로 갔다.<br><br>표를 하나씩 쥐어 볼 때마다 손끝이 사람 대신 종이를 읽게 됐다.`,
      ng:`여섯째 표를 빼는 순간 덜컹이 끝났다. 흔들림이 멎은 객차에서 모자 하나만 흔들렸다.<br><br>모자 주인이 눈을 떴다. 고개는 그대로, 눈만. 이쪽 손에 든 제 표를 본다.<br>그가 웃으며 손을 내밀었다. 돌려줬다. 그 손이 이쪽 손목을 한 번 쓸었다. 손톱자국 넷이 오래 남았다. 그 밤 그는 이쪽만 봤다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-22, spirit:-16 }, wake:1 },
    { l:'② 보조 의자 사람의 표부터 빼 본다.', k:'hide', dc:21,
      doom:{ title:'보조 의자', what:'보조 의자의 손님에게 끌려갑니다', dc:17, sec:55,
        text:`덜컹에 맞춰 보조 의자 사람 모자 띠에서 표를 뺐다.<br><br>표가 아니다. 사진이다. 이쪽이 자는 얼굴. 언제 찍었는지 모른다. 뒷면에 좌석 번호. 이쪽 자리다.<br>보조 의자 사람이 눈을 뜬다. 얼굴이 사진 속 얼굴 쪽으로 조금씩 옮겨 간다. 이쪽 얼굴로.<br><br>그가 일어선다. 이쪽 팔을 끼고 통로를 걷는다. 다정하게. 끝 문 쪽으로. 빗소리가 커진다.`,
        dieText:`9호차 사람들이 다 잔다. 표는 모자 띠에 꽂았다.<br><br>통로 쪽 보조 의자가 비었다.<br>창가 자리 하나에 낯익은 얼굴이 앉아 잔다. 고개가 한 박자 늦게 흔들린다.` },
      ok:`손을 대기 전에 신발을 봤다. 다들 젖었다. 이 사람 신발만 말랐다. 비를 맞고 탄 사람이 아니다.<br><br>터널에 들어가 객차가 까매질 때까지 기다렸다. 어둠 속에서 표를 빼 만져만 봤다. 두껍고 매끄럽다. 표가 아니라 사진 종이다. 앞면을 안으로 접어 도로 꽂았다.<br>터널을 나왔다. 그는 그대로 잔다. 모자 띠의 것은 이제 아무 얼굴도 보여 주지 않는다. 누구 얼굴이었든 오늘 밤 그는 그 얼굴을 못 쓴다.`,
      win:{ exp:23, dream:3 } }
  ] },

{ at:'B3', t:'바 카운터 — 검은 성냥갑',
  x:`식당칸 끝 바 카운터. 바텐더가 손님마다 성냥갑을 하나씩 준다. 겉에 역 이름이 찍혔다. 시간표에 있는 역들이다.<br><br>
    빨간 외투를 입은 손님이 카운터에 기대 술잔을 돌린다. 외투 주머니가 납작하다. 성냥갑 하나 들어갈 두께.<br>
    그의 성냥갑만 색이 다르다. 검은 바탕. 바텐더가 카운터 밑 따로 둔 상자에서 꺼내 주는 걸 봤다.<br><br>
    시간표 맨 아래 역 이름 칸은 비어 있다.`,
  o:[
    { l:'① 술잔을 채워 주며 주머니에서 성냥갑을 바꾼다.', k:'hide', dc:21,
      ok:`술병을 들어 그의 잔을 채웠다. 넘치게. 그가 잔을 피해 몸을 젖혔다. 외투 주머니가 이쪽 손 쪽으로 벌어졌다.<br><br>검은 성냥갑이 손바닥 안으로 왔다. 대신 이쪽 성냥갑을 넣었다. 두께가 같다. 그는 젖은 소매만 털었다.<br>화장실 칸에서 열어 봤다. 성냥개비마다 몸통에 객차 번호가 작게 적혔다. 9, 8, 7은 이미 그어져 머리가 까맣다. 6이 맨 앞에 서 있다. 여기가 6호차다. 겉면의 역 이름은 시간표에 없다. 소리 내 읽지 않았다.<br><br>주머니 하나에서 그 사람 밤을 통째로 꺼냈다. 손이 물건보다 물건이 하는 말을 먼저 쥐게 됐다.`,
      ng:`잔이 넘치기 전에 그가 잔을 들어 이쪽 손목에 댔다. 차갑다.<br><br><span style="color:#9fb4c8;">"한 잔은 내가 사겠소."</span> 그가 검은 성냥갑을 꺼내 이쪽 손에 쥐여 줬다. 먼저.<br>받는 순간 손바닥이 데었다. 떨어뜨렸다. 손바닥에 역 이름이 거꾸로 찍혀 남았다. 읽을 수 없는 글자로.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-22, spirit:-16 }, wake:1 },
    { l:'② 바텐더가 돌아선 사이 카운터 밑을 턴다.', k:'luck', dc:20,
      ok:`바텐더가 얼음을 깨러 돌아섰다. 카운터 밑에 손을 넣었다. 검은 성냥갑 상자 옆에 다른 상자가 있다. 마른안주다. 육포와 소금 땅콩.<br><br>검은 상자는 건드리지 않았다. 안주만 한 줌.<br>바텐더가 돌아섰을 때 이쪽은 빈 잔을 들고 있었다.`,
      ng:`상자를 잘못 짚었다. 검은 성냥갑 상자였다. 손끝에 닿자 성냥 하나가 저절로 그어졌다.<br><br>작은 불. 식당칸 불이 한꺼번에 깜빡였다. 손님들이 다 이쪽을 돌아봤다. 얼굴 몇 개가 바뀌어 있었다.<br>손을 뺐다. 손톱 끝이 그을었다. 그 냄새가 오래 갔다.`,
      win:{ exp:16, dream:2, item:'말린 고기' }, lose:{ hp:-20, mind:-14 } }
  ] },

{ at:'B3', t:'차장실 — 시곗줄',
  x:`7호차 끝 미닫이문이 잠겼다. 열쇠는 차장이 가졌다. 회중시계와 같은 줄에 달아 조끼 주머니에 넣었다.<br><br>
    차장은 역을 지날 때마다 시계를 꺼낸다. 시각을 보고 장부에 적는다. 그때 열쇠도 딸려 나와 시곗줄 끝에서 흔들린다.<br>
    다음 역 불빛이 창밖에 길게 다가온다. 방송이 역 이름을 부른다.<br><br>
    시계가 나와 있는 동안은 숨 셋.`,
  o:[
    { l:'① 숨 셋 사이에 시곗줄에서 열쇠를 뗀다.', k:'hide', dc:22,
      doom:{ title:'시곗줄', what:'차장의 시곗줄에 묶여 끌려갑니다', dc:18, sec:50,
        text:`차장이 시계를 꺼냈다. 열쇠가 흔들린다. 숨 하나, 고리를 쥐었다. 숨 둘, 연다.<br><br>숨 셋. 시계 뚜껑이 닫힌다. 차장은 시계를 주머니에 넣지 않는다. 이쪽을 본다. 시곗바늘은 멈춰 있었다. 시각을 본 게 아니다. 손을 기다린 것이다.<br>시곗줄이 이쪽 손목을 한 바퀴 감는다. 줄이 길다. 계속 나온다. 두 바퀴, 세 바퀴.<br><br>차장이 장부를 덮고 걷는다. 줄 끝을 쥐고. 차장실 옷장 쪽으로.`,
        dieText:`차장이 역을 지날 때마다 시계를 꺼낸다.<br><br>시곗줄 끝에 열쇠와 함께 무언가 하나 더 달렸다.<br>작은 단추다. 이쪽 소매에 달려 있던 것.` },
      ok:`첫 역은 그냥 보냈다. 숨 셋 동안 차장 눈이 어디 있는지만 봤다. 시계에 없다. 창에 비친 이쪽을 본다.<br><br>두 번째 역. 시계가 나올 때 이쪽은 창에서 비켜섰다. 창에 비치는 건 빈 통로뿐이다. 차장 눈이 창을 더듬는 동안 줄 끝 고리를 열었다.<br>시계가 주머니로 돌아갔다. 열쇠는 이쪽 소매로. 미닫이문이 소리 없이 열렸다.`,
      win:{ exp:23, dream:3 } },
    { l:'② 무력으로 덜컹이는 순간 문을 밀어붙인다.', k:'break', dc:21, cost:{ might:25 },
      ok:`열차가 큰 이음매를 넘을 때 문이 한 번 덜컹 들썩인다. 그때를 기다렸다.<br><br>덜컹. 손잡이를 잡고 힘을 다 실어 옆으로 밀었다. 잠긴 채로 문이 한 뼘 밀려났다. 몸을 비틀어 빠져나갔다.<br>뒤에서 문이 혼자 제자리로 돌아갔다. 잠긴 그대로. 차장은 시계를 꺼내 시각을 적었다. 아무것도 안 변했다.`,
      ng:`덜컹 때 밀었다. 문은 안 들썩이고 이쪽 어깨만 들렸다.<br><br>어깨가 문틀에 부딪혀 소리가 났다. 차장이 장부를 덮었다. 시계를 꺼내 시각을 적는다. 이쪽을 보며.<br>그 뒤로 어깨가 잘 안 올라갔다. 차장이 적은 시각이 무엇을 뜻하는지는 끝내 몰랐다.`,
      win:{ exp:19, dream:2 }, lose:{ hp:-28, mind:-14 } }
  ] },

{ at:'B3', t:'특실 복도 — 바뀌지 않는 주머니',
  x:`특실 복도에서 사람들이 스쳐 간다. 차장, 승객, 짐꾼. 얼굴이 다 다르다.<br><br>
    얼굴을 바꾸는 손님이 이 열차에 있다. 얼굴은 바뀐다. 걸음도 흉내 낸다. 목소리도.<br>
    손버릇은 얼굴을 안 본다. 주머니를 본다. 아까 식당칸에서 스친 사람 주머니에서 소리가 났다. 동전 셋과 열쇠 하나. 짤랑, 그리고 한 박자 늦게 철컥.<br><br>
    지금 다가오는 짐꾼 주머니에서 같은 소리가 난다.`,
  o:[
    { l:'① 덜컹일 때 어깨를 부딪쳐 주머니를 확인한다.', k:'hide', dc:21,
      ok:`덜컹. 일부러 비틀거려 짐꾼 어깨에 부딪쳤다. 손이 다녀왔다. 동전 셋, 열쇠 하나. 열쇠 머리에 숫자가 새겨졌다. 특실 9호. 이 열차 특실은 8호까지다.<br><br>짐꾼은 이쪽을 부축하며 웃었다. 처음 보는 얼굴이다. 주머니는 아까 그 주머니다.<br>열쇠는 돌려 넣지 않았다. 동전 셋만 넣었다. 소리가 달라졌다. 짤랑, 그리고 아무것도. 이제 저쪽 주머니는 이쪽이 안다. 저쪽은 모르고.<br><br>얼굴은 거짓말을 해도 주머니는 못 한다. 손이 사람을 알아보는 길이 하나 더 생겼다.`,
      ng:`부딪혔다. 손이 주머니에 들어갔다. 비어 있었다.<br><br>짐꾼이 부축하며 귀에 대고 말했다. <span style="color:#9fb4c8;">"동전 셋과 열쇠 하나. 맞소?"</span> 저쪽도 이쪽 손을 외우고 있었다.<br>그가 지나간 뒤 이쪽 주머니에서 짤랑 소리가 났다. 동전 셋. 넣은 적 없다. 그 밤 내내 그 소리가 귀에서 안 떨어졌다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-18, spirit:-16 }, wake:1 },
    { l:'② 그 소리가 가는 반대쪽으로 일행을 돌린다.', k:'evade', dc:20,
      ok:`짐꾼은 특실 쪽으로 간다. 일행을 끌고 반대쪽 화장실 칸에 들어갔다. 다섯이 좁게 섰다.<br><br>문 밖으로 짤랑, 철컥 소리가 지나갔다. 한 번 섰다가 갔다.<br>다시 나왔을 때 복도엔 아무도 없었다. 소리를 외워 두면 얼굴을 몰라도 피할 수 있다.`,
      ng:`반대쪽으로 돌렸다. 반대쪽에서도 짤랑, 철컥 소리가 다가왔다.<br><br>두 쪽에서 같은 소리가. 하나는 흉내다. 어느 쪽인지 모른다.<br>좁은 통로에서 일행이 엉켜 넘어졌다. 이쪽이 맨 밑에 깔렸다. 일어서니 손등이 밟혀 부어 있었다.`,
      win:{ exp:17, dream:2 }, lose:{ hp:-22, mind:-14 } },
    { l:'③ 짐꾼 수레의 짐표를 바꿔 단다.', k:'luck', dc:21,
      ok:`짐꾼이 세워 두고 간 수레에 가방이 실렸다. 가방마다 짐표. 객차 번호와 좌석.<br><br>일행 좌석 번호가 적힌 짐표가 셋이다. 일행은 짐을 맡긴 적이 없다. 그 짐표들을 떼어 아무 데나 바꿔 달았다. 9호차 맨 끝, 화장실 옆, 빈자리.<br>가방 하나 밑에서 기름종이 꾸러미가 굴러 나왔다. 절인 산나물이다. 그건 짐표가 없었다.`,
      ng:`짐표를 떼는 순간 가방 하나가 안에서 꿈틀했다.<br><br>짐표가 손에 붙었다. 떨어지지 않는다. 좌석 번호가 이쪽 자리다.<br>억지로 뜯었다. 손바닥 살갗이 같이 뜯겼다. 수레가 혼자 굴러 이쪽을 따라왔다. 한참.`,
      win:{ exp:18, dream:2, item:'산나물' }, lose:{ hp:-24, spirit:-12 } }
  ] }
]);
